	wt += '#qm99 a:hover{background-color:#e7eaed;border-radius:4px;box-shadow:0px 0px 1px #555;}';
	wt += 'body #qm99 .qmactive {background-color:#C0C8D0;border-radius:4px;box-shadow:0px 0px 4px #555;}';
	wt += '#qm99 a{border-style:none;padding-left:14px;}';
