function qmvi_kill_select(e)
{
	
	if (qmad.br_modern)
		return;	

	e = e || window.event;
	var targ = e.srcElement || e.target;

	if (targ.tagName=="INPUT" || targ.tagName=="TEXTAREA")
		return;

	qm_kille(e);
	return false;
	

}


function qmv_init_context()
{

	var wt = "";

	wt += '<div id="qmvi_context" style="z-index:'+(qmv.base_zindex+200)+';position:fixed;visibility:hidden;top:10px;left:10px;" onclick="qmv_conditionally_cancel_context_click(event)" oncontextmenu="qm_kille(event)">'
		wt += '<div tabindex=0 id="qm99" onkeydown="qmv_keyboard_context_menu(event,this);" class="qmmc qmmcold" oncontextmenu="qm_kille(event)"></div>';
	wt += '</div>';

	return wt;

}


function qmv_build_context_menu_keyboard_short_text(val)
{
	var ih='';
	ih += '<span style="display:block;position:absolute;top:0px;left:-5px;width:100%;text-align:right;color:#888;margin:3px 0px 0px 0px;">'+val+'</span>';
	return ih;
}



