function qmvi_activate_main_menu(e,a)
{
	
	qm_arc("qmvi_main_menu_item_on",a,true);
	
	var cm = document.getElementById("qmvi_context");
	qmv_hide_main_menu_bar_on_state(cm);

	var xy = qmv_get_offset(a);
	var type = a.getAttribute("qmmbartype");
	qmv_show_context(e,"mainmenu_"+type,null,a,xy[0]+1,xy[1]+a.offsetHeight);
	
	if (type=="addons" || type=="view" || type=="settings")
		qmv_update_all_main_checks()
	
}


function qmvi_hover_main_menu(e,a)
{
	var cm = document.getElementById("qmvi_context");
	if (cm.qmmbaritem && cm.qmmbaritem!=a)
		qmvi_activate_main_menu(e,a);
	
}


function qmv_hide_main_menu_bar_on_state(a)
{
	if (a.qmmbaritem)
	{
		qm_arc("qmvi_main_menu_item_on",a.qmmbaritem);
		qm_arc("qmvi_main_bar_sub",a);
		a.qmmbaritem = null;
	}

}




function qmv_init_interface()
