	wt += '<div id="qmvi" tabindex=0 onkeydown="qmvi_global_keyboard_events(event)" onselectstart="qmvi_kill_select(event)" onclick="qmv_hide_context();qmv_evt_kill_click(event)" oncontextmenu="qmv_util_kill_contextmenu_except_system_inputs(event);" class="qmvi-container" style="outline:none;width:286px;background-color:#C7CED5;">'
		

		var dn = "";
		if (qmv.is_chrome)
			dn = "display:none;";
	
		wt += '<div id="qmvi_title" class="qmvi-common qmvi-title" oncontextmenu="qm_kille(event)" onmouseup="qmv_evt_title_mouseup(event,this)" onmousemove="qmv_evt_title_mousemove(event,this)" onmousedown="qmv_evt_title_mousedown(event,this)" style="'+dn+'">'+qmv.displayNameLong+'</div>'
		
		wt += '<div id="qmvi_main_menu_container" class="qmvi-common qmvi-menu" style="display:none;position:relative;z-index:'+(qmv.base_zindex+100000)+';">'
			wt += '<div id="qmvi_main_bar_item_file" qmmbartype="file" class="qmvi_main_menu_item" onmouseover="qmvi_hover_main_menu(event,this)" onclick="qmvi_activate_main_menu(event,this)">File</div>';
			wt += '<div id="qmvi_main_bar_item_view" qmmbartype="view" class="qmvi_main_menu_item" onmouseover="qmvi_hover_main_menu(event,this)" onclick="qmvi_activate_main_menu(event,this)">View</div>';
