				wt += '</td>';
				
				wt += '<td style="vertical-align:top;padding:0px 0px 0px 0px;'+ts+'">'
					wt += '<div id="qmvi_bbar_tab_transitions" onclick="qmvi_bbar_tab_switch(event,this)" style="cursor:'+uc+';width:69px;height:17px;" class="qmvi-iface-bbar-tab">';
					wt += '<div class="qmvi-common qmvi-iface-bbar-tab-inner">Transitions</div></div>';
				wt += '</td>';
					
				wt += '<td style="vertical-align:top;padding:0px 0px 0px 0px;'+ts+'">'
					wt += '<div id="qmvi_bbar_tab_reportlog" onclick="qmvi_bbar_tab_switch(event,this)" style="cursor:'+uc+';width:69px;height:17px;" class="qmvi-iface-bbar-tab">'
					wt += '<div class="qmvi-common qmvi-iface-bbar-tab-inner">Report Log</div></div>'
				wt += '</td>';
				
				wt += '<td style="width:100%;"></td>';
				wt += '<td style="white-space:nowrap;padding:3px 0px 0px 0px;"><div class="qmvi-common" style="white-space:nowrap;font-size:11px;font-weight:normal;color:#444444;margin:0px 5px 0px 0px;"><span id="qmvr_menu_id" style="color:#555;">Menu ID: <span style="color:#eee">qm0</span></span></div></td>';
				
				
			wt += '</tr></table>';
		
