function qmv_filter_click_title(aid)
{

	var aobj = document.getElementById(aid);
		
	if (document.createEvent)
	{
		var evt = document.createEvent("MouseEvents");
		evt.initMouseEvent("click", true, true, window,0, 0, 0, 0, 0, false, false, false, false, 0, null);
		aobj.dispatchEvent(evt); 
	}

}

function qmv_init_interface_tree_addon_title(title,iname)
{

	//iname is used for addons without any settings

	var wt = "";

	var ix = "";
	var type = "";
	if (iname)
	{
		
		ix = 'id="qmv_iadd_'+iname+'"';
		type = 'addontype="'+iname+'"';
	}

	if (qmad.br_ie && !qmad.br_ie8 && !qmad.br_ie9)
		wt += '<a href="#"><input '+type+' '+ix+' isaddon=1 onclick="qmv_evt_addremove_addon(event,this)" style="position:absolute;padding:0px;margin:-3px 0px 0px -2px;" type="checkbox"><span style="margin-left:19px;">'+title+'</span></a>';
	else
		wt += '<a href="#"><input '+type+' '+ix+' isaddon=1 onclick="qmv_evt_addremove_addon(event,this)" style="padding:0px;margin:0px 5px 2px 4px;" type="checkbox"><span>'+title+'</span></a>';	



	return wt;

}

function qmv_init_interface_tree_bracket(is_top)
{

	var wt = "";
	if (is_top)
		wt += '<span class="qmvtree-bracket">{</span>'
	else
		wt += '<span class="qmvtree-bracket qmvtree-close-show">}</span>'


	return wt;

}


function qmv_tree_item_filter_kill_context(e)
{

	e = e || event;
	var targ = e.srcElement || e.target;
	
	if (!(targ && targ.tagName == "INPUT"))
		qm_kille(e);
		
}


function qmv_init_interface_tree_item(showname,sname,cname,category,datatype,add_on_default,range,code,ext_sname)
{

	var wt = "";
		
	var ad = ""
	var ads = "";
	
	var star = "";
	if (add_on_default)
	{

		var defin = (add_on_default+"").split("|");
		if (!defin[0]) defin[0] = "blank";
		ad = 'addondefault="'+defin[0]+'"';

		if (defin.length<2)
			star = '<span style="color:#dd3300;">*</span>&nbsp;';
		else if (defin[1]=="or")
			star = '<span style="color:#888888;">*</span>&nbsp;';
		else
			ads = 'skipdefaultoff=1';		

		
	}


	wt += '<a sname="'+sname+'" cname="'+cname+'"><table oncontextmenu="qmv_tree_item_filter_kill_context(event)" width="100%" border=0 cellspacing=0 callpadding=0><tr>';

	var sep = '&nbsp;<span class="qmvtree-colon">:</span>&nbsp;'
	if (category.indexOf("classname")+1)
		sep = "&nbsp;&nbsp;";
	else if (category=="addon")
		sep = '&nbsp;<span class="qmvtree-colon">=</span>&nbsp;'
	else if (category=="skin" || category=="plus")
		sep = ":";

	if (category=="skin")
		wt += '<td class="qmvi-common qmvtree-col1" style="width:150px;" nowrap>';
	else if (category=="plus")
		wt += '<td class="qmvi-common qmvtree-col1" style="width:100%;" nowrap>';
	else
		wt += '<td filtercol1=1 class="qmvi-common qmvtree-col1" nowrap>';

	
	var uexts = "";
	if (ext_sname)
		uexts = ext_sname;


	var killhelp = false;
	if (category!="plus" && category!="skin")
	{
		killhelp = true;
		wt += "<span oncontextmenu='qmv_style_settings_help(event,this);return false;' class='qmvtree-style-name' onclick='qmv_style_settings_help(event,this)' style=''+qmv.css_prefix+'user-select:none;'>";
	}

	if (!showname)
		wt += star+sname+uexts+sep;
	else
		wt += star+showname+uexts+sep;

	if (killhelp)
		wt += "</span>";

	wt += '</td>';


	if (qmad.br_ie && !qmad.br_ie8 && !qmad.br_ie9)
		wt += '<td class="qmvtree-col2" width=100%>';
	else
		wt += '<td class="qmvtree-col2">';

	
	if (category!="skin" && category!="plus")
	{

		wt += '<span class="qmvtree-input-container"><input onfocus="this.prev_value = this.value" code="'+code+'" range="'+range+'" '+ad+' '+ads+' dtype="'+datatype+'" category="'+category+'" sname="'+sname+'" cname="'+cname+'" onkeypress="qmv_evt_update_tree_value_enter(event,this);qmv.input_changed=this;" onchange="qmv_evt_update_tree_value(this)" class="qmvtree-input"></span>';
		wt += '</td>';

		if (category=="create" || category.indexOf("classname")+1)
		{
			wt += '<td class="qmvtree-col3">';
			wt += '<span style="'+qmv.css_prefix+'user-select:none;">&nbsp;,&nbsp;</span>';
			wt += '</td>';
		}
		else
		{
			wt += '<td class="qmvtree-col3">';
			wt += '<span style="'+qmv.css_prefix+'user-select:none;">&nbsp;;&nbsp;</span>';
			wt += '</td>';
		}

		wt += '<td class="qmvtree-col4">';
		if (datatype.indexOf("unit")+1 || datatype.indexOf("int")+1 ||  datatype.indexOf("float")+1)
		{
			wt += '<span oncontextmenu="qmv_show_context(event,\'build_button_spinner\',null,this)" onclick="qmv_evt_build_button_click(new Object(),this,1)" class="qmvtree-button qmvtree-button-up" style="'+qmv.css_prefix+'user-select:none;"></span>';		
			wt += '<span oncontextmenu="qmv_show_context(event,\'build_button_spinner\',null,this)" onclick="qmv_evt_build_button_click(new Object(),this,2)" class="qmvtree-button qmvtree-button-down" style="'+qmv.css_prefix+'user-select:none;"></span>';
		}
		else if (qmv_find_is_droplist_multi(datatype))
		{
			wt += '<span oncontextmenu="qmv_show_context(event,\'build_button\',null,this)" onclick="qmv_fire_build_button_click(event,this)" class="qmvtree-button" style="'+qmv.css_prefix+'user-select:none;">';
			wt += '<img src="'+qmv.base+'images/spinner_down_droplist.gif" width=11 height=7></span>';
		}
		else
		{
			wt += '<span oncontextmenu="qmv_show_context(event,\'build_button\',null,this)" onclick="qmv_fire_build_button_click(event,this)" class="qmvtree-button" style="'+qmv.css_prefix+'user-select:none;">...</span>';
		}
		wt += '</td>';
		
	}
	else
	{
	
		if (category=="skin")
		{
			
			wt += '<span cname="'+cname+'" onclick="qmv_evt_apply_skin(event,this)" class="qmvtree-button qmvtree-button-apply" style="width:50px;font-size:11px;">Apply</span>';
			wt += '</td>';
		}
		else if (category=="plus")
		{
			var sym = "+";
			var snl = '';
			if (sname) snl = sname.toLowerCase();
			
			if (sname && ((snl.indexOf("remove")+1 || snl.indexOf("delete")+1) && snl.indexOf("apply")==-1))
				sym = "-";
		
			wt += '<span cname="'+cname+'" onclick="qmv_evt_apply_plus(event,this)" class="qmvtree-button qmvtree-button-apply" style="width:16px;height:16px;margin-right:4px;">'+sym+'</span>';
			wt += '</td>';
		}

	}

	wt += '</tr></table></a>';

	return wt;

}

function qmv_fire_build_button_click(e,a)
{

	if(e.button==0)
		qmv_evt_build_button_click(e,a);

}

function qmv_load(e,go,from_template)
{
	
	
	if (!go && !qmv.is_chrome)
	{
		setTimeout("qmv_load(null,true,"+from_template+")",1000);	
		return;
	}
	
	document.body.style.overflow = "hidden";
	
	var qmopen = document.getElementById("qmv_open_visual_interface");
	if (qmopen) qmv.opened_from_save = true;
	
	if (!from_template)
	{
		
		for (var i=0;i<10;i++)
		{
			var a;
			if (a = document.getElementById("qm"+i))
			{
				//oops the menu was not converted because the create method was missing
				if (a.tagName=="UL")
				{
					qm_create(i,false,250,250,false,false,false,false,false);
					setTimeout("qmv_load(new Object(),true)",10);
					return;
				}
			}
		}
		
		var wt = '';
		wt += qmv_init_context();
		wt += qmv_init_interface();
		wt += qmv_init_dialog();
				
		var tdiv = document.createElement("DIV");
		tdiv.innerHTML = wt;
		document.body.appendChild(tdiv);
			
		qmc_create("vtree",false,0,0,false);
		qmv_load_styles_object();
		
	}
	
	
	if (qmv.is_blank && !from_template)
	{
		
		//if (!qmad.br_modern)
			//alert("Please Use Firefox!\r\n\r\nThe NodeFire visual interface is optimized for the latest Firefox browser. You may continue to use this browser, however some visual design features can't be available.");
				
		qmvi_template_show_dialog("load");
		return;
	}
	
	qmv_set_interface_mode("full");	
	
	if (window.name=="qm_open")
		qmv.opened_from_published_doc = true;
		
	qmv_design_menu();
	qm_vtree_init();
	qmv_ibullets_init();
		
	var a;
	if (a = document.getElementById("qmvi_loading_div"))
		a.style.display = "none";

	if (qmopen)
	{
		qmopen.style.display = "none";
	}
	
	qmvi_bbar_tab_switch(new Object(),document.getElementById("qmvi_bbar_tab_"+qmv.persist_settings.bottom_bar_tab_state));
	
	
	if (!from_template)
	{
		var bgc = qm_lib_get_computed_style(document.body,"background-color","backgroundColor");
		if (bgc && bgc!="transparent")
		{
			var bgcdiv = document.getElementById("qmvi_design_bg_div");
			bgcdiv.value = bgc;
			bgcdiv.style.backgroundColor = bgc;
			
			qmvi_set_design_bg_color(bgc,bgcdiv)
		}
	}
	
	window.scrollTo(0,0);
	qmv.loaded = true;
	
	
	
}



function qmv_set_interface_mode(type)
{

	
	if (type=="full")
		qmv.interface_full = true;
	else if (type=="inpage")
		qmv.interface_full = false;
	

	qmv.qmvi = document.getElementById("qmvi");
	var mp = qmv.qmvi_design_panel = document.getElementById("qmvi_menu_panel");
	
	var mm = document.getElementById("qmvi_main_menu_container");
	mm.style.display = "block";
	mm = document.getElementById("qmvi_top_bbar_container");
	mm.style.display = "block";
	
	qmv_lightbox_kill_all();
	
	if (!qmv.interface_full)
	{
		
		
		if (qmv.is_chrome)
			document.getElementById("qmvi_title").style.display = "block";

		if (qmv.opened_from_published_doc)
			document.body.style.overflow = "";
		
		if (qmv.loaded)
		{

			for (var i=0;i<10;i++)
			{

				var a;
				if (a = document.getElementById("qm"+i))
				{
					
					var ph = document.getElementById("ph"+a.id);
					if (ph)
					{
							
						var killp = a[qp];
						
						ph[qp].insertBefore(a,ph);
						ph[qp].removeChild(ph);
						if (killp) killp[qp].removeChild(killp);
						
					}
					else
					{
						document.body.appendChild(a[qp]);
					}
					
				}
			}
			
			qmv.qmvi.style.width = "286px";
	
			var qtc = document.getElementById("qmvi_tree_menu_container");
			qtc.style.width = "";

		}
		

		var bb;
		var bbi=1;
		while (bb = document.getElementById("qmvbb_hide_button"+bbi))
		{
			bb.style.display = "none";
			bbi++;
		}

		mp.style.display = "none";
		
		var bp = document.getElementById("qmvi_bpanel");
		bp.style.display = "none";
		
		bp = document.getElementById("qmvi_bottom_bar");
		bp.style.display = "none";
				
		bp = document.getElementById("qmvi_vd_panel");
		bp.style.display = "none";

		var dw = document.documentElement.offsetWidth;
		qmv.qmvi.style.left = (dw-qmv.qmvi.offsetWidth)-30+"px";
		qmv.qmvi.style.top = "10px";
			
		qmv_handle_resize();
		qmv_position_pointer();


	}
	else
	{
		
	
		if (qmv.is_chrome)
			document.getElementById("qmvi_title").style.display = "none";
		
		document.body.style.overflow = "hidden";
		
		//this is the inherited font size
		mp.style.fontSize = "16px";
		
		var cc = 0;
		for (var i=0;i<10;i++)
		{
			
			var a;
			if (a = document.getElementById("qm"+i))
			{
				
				
				var mc;
				mc = document.createElement("DIV");
				
				mc.menufloater = 1;
				mc.style.position = "relative";
			
				mc.style.top = cc+"px";
				mc.style.left = "0px";
				if (qmad.br_ie)
					mc.style.zoom = 1;

				mc.onmouseup = function(event){qmv_evt_title_mouseup(event,this)}
				mc.onmousemove = function(event){qmv_evt_title_mousemove(event,this)}
				mc.onmousedown = function(event){qmv_evt_title_mousedown(event,this,this,true)}

				
				//set the place holder div
				var ph = document.createElement("DIV");
				ph.style.position = "absolute";
				ph.id = "ph"+a.id;
				a[qp].insertBefore(ph,a);

				mc.appendChild(a);
				mc = mp.appendChild(mc);

				cc+=200;

			}

		}
	
		
		var bb;
		var bbi=1;
		while (bb = document.getElementById("qmvbb_hide_button"+bbi))
		{
			bb.style.display = "";
			bbi++;
		}
		
		
		qmv.interface_full_loaded = true;
		qmv_resize_interface(new Object(),true);
	}
	
	if (qmv.loaded && qmad.br_ie)		
	{
		qmv_set_all_subs_to_default_position(true);
		qmv_position_pointer();
	}
	
}

function qmv_resize_interface(init)
{

	if (!qmv.loaded && !init)
		return;

	if (qmv.interface_full && qmv.interface_full_loaded)
	{
		
		var bbar = document.getElementById("qmvi_bottom_bar");
		var bpanel = document.getElementById("qmvi_bpanel");
		var rp = document.getElementById("qmvi_report_panel");
		var rpd = document.getElementById("qmvi_report_panel_data");
		var mp = qmv.qmvi_design_panel;
		var vd = document.getElementById("qmvi_vd_panel");
		var qtc = document.getElementById("qmvi_tree_menu_container");
		var transp = document.getElementById("qmvi_transition_panel_timeline");
		
		var hp1 = document.getElementById("qmvi_df_htmledit_design");
		var hp2 = document.getElementById("qmvi_df_htmledit_panel_code");
		var hp3 = document.getElementById("qmvi_df_htmledit_code");
			
		var vdheight = 25;
		var bbar_height = 20;
		var bpanel_sizing_bar_height = 4;
		
		if (init)
		{
			qtc.style.width = qtc.offsetWidth-2+"px";
			qmv.qmvi.style.top="0px";
			qmv.qmvi.style.left = "0px";	
		}

		
		var dd = qm_get_doc_wh();
		qmv.qmvi.style.width = dd[0]-1+"px";
		
		
		var seth = (Math.abs(qtc.offsetTop-dd[1])-7);
		qtc.style.height = (seth-bbar_height)+"px";
		
		
		//var rh = qmv.report.height;
		var rh = qmv.bpanel.height;
		var rh_tabs = 24;
		var design_area_padding = 50;
		
		if (qmad.br_s3 || qmad.br_s4) rh_tabs = 29;
		if (qmad.br_strict || qmv.is_chrome) rh_tabs += 5;  //this is the padding applied to the panel data div
		
		mp.style.height = (seth-(rh+rh_tabs)-bbar_height-vdheight-bpanel_sizing_bar_height)-design_area_padding+"px"; 
		rpd.style.height = rh+1+"px";
		transp.style.height = rh+1-15+"px";
		
		hp1.style.height = rh-40+"px";
		hp2.style.height = rh-54+"px";
		hp3.style.height = rh-54+"px";
		
			
		mp.style.top = (qtc.offsetTop+vdheight)+"px";
		bpanel.style.top = (qtc.offsetTop+parseInt(seth-(rh+rh_tabs))-bbar_height)+"px";
			
		var t1 = (qtc.offsetWidth+qtc.offsetLeft+0);
		mp.style.left = t1+"px";
		bpanel.style.left = t1+"px";
		vd.style.left = t1+"px";
		
		var t2 = (Math.abs(t1-dd[0])-7);
		mp.style.width = t2-design_area_padding+"px";
		bpanel.style.width = t2+"px";
		vd.style.width = t2+"px";

		mp.style.display = "block";
		bpanel.style.display = "block";
		vd.style.display = "block";
		bbar.style.display = "block";
		
		if (qmv.vdesign_tab!="design")
			qmvi_vd_size_csshtml_panel(mp);
				
		qmvi_transition_panel_timeline_set_width();
	}
		
	
}


function qmv_get_doc_wh()
{	
	

	db = document.body;
	var w=0;
	var h=0;

	if (tval = window.innerHeight)
	{
		h = tval;
		w = window.innerWidth;
		
	}
	else if ((e = document.documentElement) && (e = e.clientHeight))
	{
		
		h = e;
		w = document.documentElement.clientWidth;
		
	}
	else if (e = db.clientHeight)
	{
		if (!h) h = e;
		if (!w) w = db.clientWidth;
	}

	
	return new Array(w,h);

}




function qmv_handle_resize()
{

		
	if (qmv.loaded && !qmv.interface_full)
	{
		var wd = qmv_lib_get_window_dimensions();
		var aobj = document.getElementById("qmvi");

		var bobj = document.getElementById("qmvi_tree_menu_container");
		var coreh = aobj.offsetHeight - bobj.offsetHeight;
		nbh = (wd[1]-coreh-30-aobj.offsetTop);
		if (nbh<100) nbh = 100;
		bobj.style.height = nbh+"px"
		
	}
	else
		qmv_resize_interface();


	if (qmv.tplate_dialog && qmv.tplate_dialog.style.visibility=="visible")
		qmvi_template_dialog_resize();

	if (qmv.logon_blockout)
		qmvi_logon_shadow_size(qmv.logon_blockout);

	qmvi_ktop_blockout_sizer();
	
}



function qmv_load_styles_object()
{
	
	qmv.styles = qmv_lib_get_qm_stylesheet();
	
	var i;
	var c = 0;
	for (i in qmv.styles)
	{
		
		if (qmv.styles[i].cssRules)
		{
			qmv["style_rules"+c] = qmv.styles[i].cssRules;
			qmv["style_rules_sheet"+c] = qmv.styles[i];
		}
		else if (qmv.styles[i].rules)
		{
			qmv["style_rules"+c] = qmv.styles[i].rules;
			qmv["style_rules_sheet"+c] = qmv.styles[i];
		}


		if (c==0)
		{
			if (qmv.styles[i].insertRule)
				qmv.styles_addtype="insertrule";
			else if (qmv.styles[i].addRule)
				qmv.styles_addtype="addrule";
			
			if (qmv.styles[i].removeRule)
				qmv.styles_removetype = "removerule"
			else
				qmv.styles_removetype = "deleterule";
		}
		
		c++;
	}


	
}

function qmv_update_styles_object()
{


	if (qmad.br_s3 || qmad.br_s4 || qmad.br_chrome)
	{
		
		
		var c=0;
		while (qmv["style_rules"+c])
		{
			
			qmv["style_rules"+c] = qmv["style_rules_sheet"+c].cssRules;
			c++;
		}
		
	}

}


