function qmv_evt_update_item_title_innerHTML(a,val)
{

	
	if (qmad.br_ie)
	{	
		
		var b = a.cloneNode(true);
		
		b.onclick = a.onclick;
		b.className = a.className;
		b.ondblclick = a.ondblclick;
		b.oncontextmenu = a.oncontextmenu;
				
		b.innerHTML = val;

		a.parentNode.replaceChild(b,a);	

	}
	else
	{
		a.innerHTML = val;

	}
		
}

