function qmv_update_selected_classname(type,cname,val,is_undo)
{

	var is_add = false;
	if (val && val.toLowerCase()=="true")
		is_add = true;

	if (type=="classname-selected-sub")
	{
	
		var sub = qmv_getsubfor_selected_classname(cname,is_add,is_undo);
		if (sub.sub && !sub.skip_apply)
			qm_arc(cname,sub.sub,is_add);
		
		if (cname=="qm-horizontal-stretch-items" && !is_add)
		{
			qmv_reset_stretch_item_minwidths(qmv.cur_sub);
		}
	
	}

}


function qmv_update_selected_attribute(type,cname,val,is_undo)
{

	var ap_type = ((type.match("item"))?"item":"sub");
	var ap_elm = ((type.match("item"))?qmv.cur_item:qmv.cur_sub);
	
	if (ap_elm)
	{
		
	
		var eat = ap_elm.getAttribute("qmevents");
		var ev;
		
		if (eat)
			ev = eval("("+eat+")");
		else
			ev = {};
			
		ev[cname] = val;
		var es = qmv_event_listener_get_object_string(ev);
	
		if (es)
			ap_elm.setAttribute("qmevents",es);
		else
			ap_elm.removeAttribute("qmevents",es);
		
	}
}


function qmv_event_listener_get_object_string(a)
{
	var rs = "";
	for (var i in a)
	{
		if (a[i])
		{
			var uv = a[i].replace(/\"/g,"'");
			uv = uv.replace(/\'/g,"\\'");
			rs+= i+":'"+uv+"',";
		}
	}
	
	if (rs.length)
	{
		rs = rs.substring(0,rs.length-1);
		return "{"+rs+"}";
	}
	else
		return "";
}



function qmv_getsubfor_selected_classname(cname,is_add,from_undo)
{
	var robj = {sub:qmv.cur_sub};
	
	if (is_add && qm_a(robj.sub) && (cname=="qm-flush-left" || cname=="qm-flush-top" || cname=="qm-rtl" || cname=="qm-btt"))
	{
		if (qmv.cur_item.cdiv)
		{
			robj.sub = qmv.cur_item.cdiv;
		}
		else
		{
			if (!from_undo)
			{
				qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>Select a sub menu before applying this setting.",350);
				qmv_load_selected_classnames_to_tree();
			}
			
			robj.skip_apply = true;
		}
	}
	
	if (is_add)
	{
		if (!from_undo)
		{
			var pd = qm_get_pdiv(robj.sub);
			if (pd)
			{
				
				if (cname=="qm-flush-left" && (qm_a(qmv.cur_sub) || pd.className.indexOf("qm-horizontal-c")==-1))
				{
					qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>Flush left positioning can only be applied to sub menus with parent items that are horiztonally aligned.",350);
					qmv_load_selected_classnames_to_tree();
					robj.skip_apply = true;
				}
				else if (cname=="qm-flush-top" && (qm_a(qmv.cur_sub) || pd.className.indexOf("qm-horizontal-c")+1))
				{
					qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>Flush top positioning can only be applied to sub menus with parent items that are vertically aligned.",350);
					qmv_load_selected_classnames_to_tree();
					robj.skip_apply = true;
				}
				
			}
			
			if (cname=="qm-horizontal-stretch-items" && (robj.sub.className.indexOf("qm-horizontal-c")==-1 && robj.sub.firstChild.tagName!="DL"))
			{
				qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>Stretch items can only be applied to main or sub menus with horizontally aligned items.",350);
				qmv_load_selected_classnames_to_tree();
				robj.skip_apply = true;
			}
						
		}
	}
	
	if (!from_undo)
	{
		if (qm_a(robj.sub) && cname=="qm-horizontal-c")
		{
			qmv_input_code_ask_width(!is_add);
			
		}
	}
	
	
	return robj;

}


function qmv_load_selected_classnames_to_tree()
{

	var a = document.getElementById("qmvtree_classnames_selected_sub").getElementsByTagName("A");
	for (var i=0;i<a.length;i++)
	{
	
		var inp = a[i].getElementsByTagName("INPUT")[0];
		if (inp)
		{
			var cname = inp.getAttribute("cname");
			if (qmv.cur_sub.className.indexOf(cname)+1)
				inp.value = "true";
			else
				inp.value = "";
				
			inp.prev_value = inp.value;
		}
	
	}
	
}

function qmv_load_selected_event_listeners_to_tree()
{

	var a = document.getElementById("qmvtree_event_listener_selected").getElementsByTagName("A");
	
	var iteme = qmv.cur_item.getAttribute("qmevents");
	try{if (iteme) iteme = eval("("+iteme+")");}
	catch(e){iteme=null;}
	
	var sube = qmv.cur_sub.getAttribute("qmevents");
	try{if (sube) sube = eval("("+sube+")");}
	catch(e){sube=null;}
	
	for (var i=0;i<a.length;i++)
	{
	
		var inp = a[i].getElementsByTagName("INPUT")[0];
		if (inp)
		{
		
			var cname = inp.getAttribute("cname");
			var iv;
		
			var ob = iteme;
			if (cname.match("sub")) ob=sube;
			
				if (ob && (iv = ob[cname]))
					inp.value = iv;
				else
					inp.value = "";
			
			
			inp.prev_value = inp.value;
		}
	
	}
	
}


function qmv_load_inline_styles_to_tree()
{
	
	var a = document.getElementById("qmvtree_inline_styles").getElementsByTagName("DIV");
	for (var i=0;i<a.length;i++)
	{
		var tr = a[i].getAttribute("rule");

		var is_multi = false;
		var obj = qmv.cur_item;
		
		if (tr.indexOf("parent")+1)
		{
			if (obj[qp] && obj[qp].tagName=="DD" && obj[qp][qp] && obj[qp][qp].className.indexOf("qmmulti")+1)
			{
				is_multi=true;
				obj = obj[qp][qp][qp];
			}
			else
				obj = obj[qp];
				
		}
		else if (tr.indexOf("column")+1)
		{
			if (obj[qp] && obj[qp].tagName=="DD" && obj[qp][qp] && obj[qp][qp].className.indexOf("qmmulti")+1)
			{
				is_multi=true;
				obj = obj[qp][qp];
			}
			else
				continue;
			
		}


		if (!obj) continue;

		var aa = a[i].childNodes;
		for (var j=0;j<aa.length;j++)
		{

			if (aa[j].tagName=="A")
			{
				
				var inp = aa[j].getElementsByTagName("INPUT")[0];
				if (inp)
				{
					var cname = inp.getAttribute("cname");
					if (!cname) continue;
					
					var val = obj.style[cname];
					if (val)
						inp.value = qmv_load_css_styles_convert_values(val,inp.getAttribute("dtype"));
					else
						inp.value = "";


					var dtype = inp.getAttribute("dtype");
					if (dtype == "color" || dtype=="colormulti")
						qmv_color_build_button_set(inp,dtype);
								
					
					inp.rule_obj = obj;
					inp.prev_value = inp.value;
					
				}
			}

		}
		
	}

}

