function qmv_load_styles_to_tree(id,tree_obj)
{
	
	var a;
	if (!tree_obj)
		a = document.getElementById("qmvtree_css_styles").getElementsByTagName("DIV");	
	else
		a = tree_obj;

	for (var i=0;i<a.length;i++)
		a[i].stylesloaded = null;

		
	var c = 0;
	while (qmv["style_rules"+c])
	{
		
		var rules = qmv["style_rules"+c];
		if (!id) id = qmv.id;
				
		for (var i=0;i<rules.length;i++)
		{	
			
			var st = rules[i].selectorText.toLowerCase();
			if (st.indexOf(".qmmc")==0 || st.indexOf(".qmclear")==0)
				continue;
			
			if (st.indexOf("#qm")+1 && st.indexOf("#qm"+id)==-1)
				continue;
			
			
			qmv_load_styles_to_tree_node(rules[i],st,null,a);

		}
	
		c++;
	}


	for (var i=0;i<a.length;i++)
	{

		var tr = a[i].getAttribute("rule");
		if (tr)
		{
			var tr = tr.replace("[i]",qmv.id);
			qmv_load_style_set_rule_desc(a[i],tr);
			
			if (!a[i].stylesloaded)
			{
				qmv_load_styles_to_tree_node(null,tr,true,a);
			}

		}
	}
	
}


function qmv_load_style_set_rule_desc(a,tr)
{
	var rd = a.idiv.getAttribute("ruledesc");
	if (rd)
	{
		var as = a.idiv.getElementsByTagName("SPAN");
		for (var j=0;j<as.length;j++)
		{
			if (as[j].getAttribute("isruledesc"))
			{
				tr = tr.replace("body","");
				as[j].innerHTML = rd+"&nbsp;&nbsp;<span class='qmvtree-rule' title='"+tr+"'>[&nbsp;"+qmv_rule_truncate(tr,22)+"&nbsp;]</span>";
			}

		}
	
	}

}


function qmv_load_styles_to_tree_node(rule,st,force_noval,a,test)
{
	
	st = st.split(",")[0];
	//st = st.replace(/ > /g,">");
	
	for (var i=0;i<a.length;i++)
	{
		var origrule = a[i].getAttribute("rule");
		var tr = origrule;
			
		if (tr && tr!="addon")
		{

			tr = tr.replace("[i]",qmv.id);
			
			if (tr==st)
			{
				
				a[i].stylesloaded = 1;

				var aa = a[i].childNodes;
				for (var j=0;j<aa.length;j++)
				{
					if (aa[j].tagName=="A")
					{
							
						var cname = aa[j].getAttribute("cname");
							
						
						if (!cname)
							continue;
						
						var val = "";
						if (!force_noval)
						{
							var val = rule.style[cname];
							
							if (val && qmad.br_fixborderradius_chrome && cname=="borderRadius")
								val = qmv_fix_chrome_border_radius_invert_value_bug(val);
						}
				
							
						var inp = aa[j].getElementsByTagName("INPUT")[0];
												
						var dtype = inp.getAttribute("dtype");
						if (val)
						{
							
							inp.value = qmv_load_css_styles_convert_values(val,inp.getAttribute("dtype"));
						
							if (dtype == "color" || dtype=="colormulti")
								qmvi_color_recent_add(inp);
							
						}
						else
							inp.value = val;


						if (dtype=="color" || dtype=="colormulti")
							qmv_color_build_button_set(inp,dtype);

						var ir;
						if (ir = a[i].getAttribute("inheritrule"))
							inp.setAttribute("inheritrule",ir);
						
						
						inp.origrule = origrule;
						inp.rule = tr;
						inp.prev_value = inp.value;
						

					}

				}


			}	


		}
	
		
	}	

}



function qmv_color_build_button_set(inp,dt)
{


	a = inp[qp];
	while (a && a.tagName && a.tagName!="A")
		a = a[qp];

	
	var s = a.getElementsByTagName("SPAN");

	if (s.length>0)
	{
		
		for (var i=0;i<s.length;i++)
		{
			
			if (s[i].className.indexOf("qmvtree-button")+1)
			{
				s[i].isbuildcolor = 1;
				if (inp.value)
				{
					if (dt=="colormulti")
					{
						
						var svals = qmv_lib_parse_edge_values(inp.value,"color");
						s[i].style.borderColor = "#333333";
						
						var bi = '';
						bi = '<span isbinner="1" style="background-color:'+svals.top+';width:8px;height:8px;font-size:1px;position:relative;display:block;"></span>';
						bi += '<span isbinner="1" style="background-color:'+svals.left+';left:8px;top:-8px;width:8px;height:8px;font-size:1px;position:relative;display:block;"></span>';
						bi += '<span isbinner="1" style="background-color:'+svals.right+';left:8px;top:-8px;width:8px;height:8px;font-size:1px;position:relative;display:block;"></span>';
						bi += '<span isbinner="1" style="background-color:'+svals.bottom+';top:-16px;left:0px;width:8px;height:8px;font-size:1px;position:relative;display:block;"></span>';
												
						s[i].innerHTML = bi;
						
						
					}
					else
					{
						s[i].style.backgroundColor = inp.value;
						s[i].style.borderColor = "#333333";
						s[i].innerHTML = "";
					}
									}
				else
				{
					s[i].style.backgroundColor = "";
					s[i].style.borderColor = "";
					s[i].innerHTML = "...";
					
				}
				break;
			}
				
		}
		
		
	}

}


function qmv_convert_color_to_hex(value)
{

	if (value && value.toLowerCase().indexOf("rgba")+1)
		return value;
	
	var rval = value.toLowerCase();
	var cv = value.split(") ");
	if (cv.length==4)
	{
		
		if (cv[0]==cv[1] && cv[0]==cv[2] && cv[3].indexOf(cv[0])+1)
			rval = cv[0];
			
	}

	var rl = rval.toLowerCase();
	if (rl!="transparent" && rl.indexOf("rgb")+1)
		rval = qmv_color_parse_split(cv[0],true);
	

	return rval;
}


function qmv_load_css_styles_convert_values(value,dtype)
{

	var rval = value;
	value = value+"";
	
	if (dtype=="color")
	{
			
		if (rval.indexOf("rgba")+1) return rval;
		
		if (rval.indexOf("rgb")+1)
			rval = qmv_color_parse_split(rval.toLowerCase(),true);
		
	}
	else if (dtype=="colormulti")
	{
		var ts = rval.replace(/ ,/g,",");
		var ts = rval.replace(/, /g,",");
		ts = ts.split(" ");
		
		for (var i=0;i<ts.length;i++)
		{
			if (ts[i].indexOf("rgba")+1)
				continue;
				
			if (ts[i].indexOf("rgb")+1)
				ts[i] = qmv_color_parse_split(ts[i].toLowerCase(),true);
		}
		
		if (ts.length)
		{
			rval = '';
			for (var i=0;i<ts.length;i++)
			{
				rval += ts[i];
				if (i!=ts.length-1)
					rval+=" ";
			}
		}
		
		return rval;
	
	}
	else
	{
		var cv = value.split(" ");
		if (cv.length==4)
		{
			if (cv[0]==cv[1] && cv[0]==cv[2] && cv[0]==cv[3])
				rval = cv[0];	
		}
	}	
	
	return rval;

}


function qmv_update_visible_dialog_data()
{
	if (qmv.anchor_dialog_visible) qmv_url_init();
	if (qmv.lightbox_item_dialog_visible) qmv_lightbox_dialog_init();
}


//************************** Visual Interface Event Handlers

//start point - search me - zzz
function qmv_a(o,ext)
{
	
	
	if (qmv.preview_mode)
		return;
		
	var m = qm_get_menu(o);
	if (m.id=="qm99" || m.id=="qm98") return;
	
	var is_multi = false;
	if (o[qp] && o[qp].tagName=="DD")
		is_multi=true;
		
	var is_horizontal = false;
	if (o[qp] && qmv_is_container_horizontal(o[qp]))
		is_horizontal=true;	
		
	
	if (qmv.htmleditor.panel_code_edited) qmv_htmledit_save_codeview(true);	
	if (qmv.anchor_dialog_visible) qmv_save_anchor_settings();
	if (qmv.lightbox_item_dialog_visible) qmv_lightbox_dialog_save();
		
	if (qmv.input_changed)
	{
		qmv_evt_update_tree_value(qmv.input_changed);
		qmv.input_changed = false;
	}
	
	
	qmv.cur_item = o;
	
	if (o && o[qp])
	{
		if (o[qp].tagName=="DIV")
		{ 
			qmv.cur_sub = o[qp];
			qmv.cur_column = null;
		}
		else if (o[qp].tagName=="DD")
		{
			if (o[qp][qp] && o[qp][qp][qp].tagName=="DIV")
			{
				qmv.cur_column = o[qp][qp];
				qmv.cur_sub = qmv.cur_column[qp];
			}
			else
			{
				qmv.cur_sub=null;
				qmv.cur_column=null;
			}
		}
		else
		{
			qmv.cur_sub=null;
			qmv.cur_column=null;
		}
	}
	else
	{
		qmv.cur_sub=null;
		qmv.cur_column=null;
	}

	
	qmv_set_texturl_field(o,null,null,null,"text");
	qmv_set_texturl_field(o,null,null,null,"url");
	qmv_load_inline_styles_to_tree();
	qmv_load_selected_classnames_to_tree();
	qmv_load_selected_event_listeners_to_tree();
	qmv_load_title_applied_to_tree();
	qmv_load_cbox_applied_to_tree();
	qmv_load_divider_applied_to_tree();
		
	
	qmv_update_visible_dialog_data();
	
	var id;
	if (m.id && (id = m.id.substring(2)) && !isNaN(id = parseInt(id)))
	{	

		if (qmv.id==-1 || qmv.id != id)
		{
			
			qmv.force_id_update = false;
			qmvi_save_report_object();
			qmv.color_recent = new Array();
			
			qmv.id = id;
			
			qmv_load_styles_to_tree();
			qmv_load_menu_settings_to_tree();
			qmv_load_addon_settings_to_tree();
			qmv_load_title_styles_to_tree();
			qmv_load_cbox_styles_to_tree();
			qmv_load_stripe_styles_to_tree();
			qmv_load_divider_styles_to_tree();
			qmv_load_box_styles_to_tree();
			qmv_load_custom_styles_to_tree();
			
			if (document.getElementById("qmvtree_filter").cdiv.style.display=="block")
				qmv_filter_init2();
				
			var a = document.getElementById("qmvtree_color_shortcuts");
			if (a.style.display=="block")
				qmv_shortcut_init(a);
			
			qmv_setbox_update_quick_color();
			qmvi_initialize_report_object();
			qmvi_transition_panel_initialize();
			qmv_update_all_addons(null,true);
			qmv_lightbox_test_for_addon(true);
			
		}
	
	}
		
	qmv_turn_move_buttons_on_off();
	qmv_position_pointer(true);
	qmv_hide_context();
		
	qmv_setbox_update_individual();
	qmv_setbox_update_inline();
	
	if (document.getElementById("qmvacc_apply_allitems"))
		qmv_custom_class_list_change(new Object());
		
	qmv_htmledit_update_from_visual_change();
	qmv_htmleditor_reset_dialog_insert_image();
	
	qmv_filter_update_automatically('item');
	
	
	if (!qmv.qmvi_kb_focus_menu_item)
		qmv.qmvi_kb_focus_menu_item = document.getElementById("qmvi_kb_focus_menu_item");
		
	qmv.qmvi_kb_focus_menu_item.focus();
	
	
	
}

function qmv_htmledit_update_from_visual_change(skip_bot_panel_update,force)
{
	
	if (!skip_bot_panel_update)
	{
		if ((qmv.persist_settings.bottom_bar_tab_state=="itemeditor" && qmv.loaded) || qmv.htmleditor_dialog_insert_image_visible || force)
			qmv_htmleditor_init_dialog(document.getElementById("qmv_edittext_field"),true,qmv.loaded);
	}
	
	if (qmv.htmldesign_dialog_visible)
		qmv_htmleditor_init_dialog(document.getElementById("qmv_edittext_field"),false);
	

}


function qmv_turn_move_buttons_on_off()
{

	if (qmv.cur_item)
	{
		
		var is_h = qmv_is_container_horizontal(qmv.cur_item[qp]);
		
		var is_multi = false;
		if (qmv.cur_item[qp] && qmv.cur_item[qp].tagName=="DD")
			is_multi = true;
		
		//disable move item options based on orientation
		if (is_h)
		{
			
			document.getElementById("qmvebb_mdown").src = qmv.base+"images/qmv_bb_movedown_d.gif";
			document.getElementById("qmvebb_mup").src = qmv.base+"images/qmv_bb_moveup_d.gif";
			document.getElementById("qmvebb_mleft").src = qmv.base+"images/qmv_bb_moveleft.gif";
			document.getElementById("qmvebb_mright").src = qmv.base+"images/qmv_bb_moveright.gif";
			
		}
		else
		{
		
			document.getElementById("qmvebb_mdown").src = qmv.base+"images/qmv_bb_movedown.gif";
			document.getElementById("qmvebb_mup").src = qmv.base+"images/qmv_bb_moveup.gif";
			
			if (is_multi)
			{
				document.getElementById("qmvebb_mleft").src = qmv.base+"images/qmv_bb_moveleft.gif";
				document.getElementById("qmvebb_mright").src = qmv.base+"images/qmv_bb_moveright.gif";
			}
			else
			{
				document.getElementById("qmvebb_mleft").src = qmv.base+"images/qmv_bb_moveleft_d.gif";
				document.getElementById("qmvebb_mright").src = qmv.base+"images/qmv_bb_moveright_d.gif";
			}
			
		}
		
	}

}


function qmv_hide_pointer(id,skip_container,column_only,skip_column)
{
	
	
	var po;
		
	if (!column_only)
	{
		if ((po = qmv.pointer) && (po = po[id]) && (po = po.a))
			po.style.display = "none";
		
		if (!skip_container)
		{
			if ((po = qmv.c_pointer) && (po = po[id]) && (po = po.a))
				po.style.display = "none";
		}
	}
	
	if (!skip_column)
	{
		if ((po = qmv.q_pointer) && (po = po[id]))
		{
			if (po = po.a)
				po.style.display = "none";
			
		}
	}
}



function qmv_position_pointer(show,container_sizing,c_move,column_sizing,type)
{

	if (!window.qmv)
		return;
		
	var imax = 2;
	if (qmv.cur_column)
		imax = 3;
	else
		qmv_hide_pointer("qm"+qmv.id,false,true);

			
	for (var i=0;i<imax;i++)
	{
	
		if ((container_sizing && i!=1) || (column_sizing && i!=2))
			continue;
	
		var pfix = '';
		var iobj = qmv.cur_item;
		var ow = 1;
		var g1 = 1;
		
		if (i==1)
		{
			pfix = "c_";
			iobj = qmv.cur_sub;
		}
		else if (i==2)
		{
			pfix = "q_";
			iobj = qmv.cur_column;
		}
		
		if (i==1 || i==2)
		{
			ow=1;
			g1 = 1;
		}
		
		if (!qmv[pfix+"pointer"]["qm"+qmv.id])
			return;
			
		var po = qmv[pfix+"pointer"]["qm"+qmv.id].a;

		if (!iobj.offsetWidth)
			return;
	
		
		
		var lt = qmv_lib_get_position_relative_to_main_menu_container(iobj);
		if (i==1 && iobj && qm_a(iobj))
		{
			lt[0] -= qm_gcs(iobj,"border-left-width","borderLeftWidth",true);
			lt[1] -= qm_gcs(iobj,"border-top-width","borderTopWidth",true);
		}
		
				
		po.style.left = (lt[0]-ow)+"px";
		po.style.top = (lt[1]-ow)+"px";
				
		
		var sp = po.getElementsByTagName("SPAN");
				
		var sp_top,sp_right,sp_bot,sp_left,sp_sizerlr,sp_sizerud;
		for (var j=0;j<sp.length;j++)
		{
			
			if (sp[j].getAttribute("top"))
				sp_top = sp[j];
			else if (sp[j].getAttribute("right"))
				sp_right = sp[j];
			else if (sp[j].getAttribute("bottom"))
				sp_bot = sp[j];
			else if (sp[j].getAttribute("left"))
				sp_left = sp[j];
			else if (sp[j].getAttribute("sizer_leftright"))
				sp_sizerlr = sp[j];
			else if (sp[j].getAttribute("sizer_updown"))
				sp_sizerud = sp[j];				
		}
		
		//hide the left right sizer for tree menu subs
		if (i==1 && sp_sizerlr)
		{
			if (qmv.addons.tree_menu["on"+qmv.id] && !qm_a(iobj))
				sp_sizerlr.style.visibility = "hidden";
			else
				sp_sizerlr.style.visibility = "inherit";
		}
		
			
		var sw = iobj.offsetWidth;
		var sh = iobj.offsetHeight;
		
				
		if ((container_sizing && i==1) || (column_sizing && i==2))
		{
			if (type=="ud")
			{
				if (container_sizing)
					sh = c_move-2;
				else if (column_sizing)
					sh = c_move+21-2;
			}
			else
			{
				sw = c_move;
				g1 = 0;
			}
			
		}
		
		sp_top.style.width = (sw+g1)+"px";
		sp_bot.style.width = (sw+g1)+"px";
		sp_bot.style.top = (sh+ow)+"px";
	
		
		if (sw-ow>=0)
		{
			sp_left.style.height = (sh-ow)+"px";
			sp_left.style.top = ow+"px";

			sp_right.style.height = (sh-ow)+"px";
			sp_right.style.top = ow+"px";
			sp_right.style.left = (sw+g1)+"px";
		}
		
		if (sp_sizerlr && sw+g1>=0)
		{
			sp_sizerlr.style.left = (sw+g1)+"px";
			
		}
		
		if (sp_sizerud && sw+g1>=0)
		{
			var tof = 0;
			if (i==2)
				tof = 21;
				
							
			sp_sizerud.style.top = (sh-tof+2)+"px";
			sp_sizerud.style.left = (sw+g1)+"px";
		}
		
		
		
	}
	
	if (!container_sizing && !column_sizing)
	{
		for (var i=0;i<3;i++)
		{
			var pfix = '';
			if (i==1)
				pfix = "c_";
			else if (i==2)
				pfix = "q_";
			
			var po = qmv[pfix+"pointer"]["qm"+qmv.id].a;
			
			if (show && !qmv.interface_hide_selected_box)
			{
				//only show the container selection box for standard drop down menus
				if (!(i==1 && qmv.addons.scroll["on"+qmv.id]))
				{
					if (!(i==2 && !qmv.cur_column))
						po.style.display = "block";
				}
							
				//hide pointer selectors for all other menus
				var j;
				for (j in qmv[pfix+"pointer"])
				{
					if (j+""!="qm"+qmv.id && qmv[pfix+"pointer"][j]!=null)
						 qmv_hide_pointer(j+"");
				}
			
			}
		}
	}

}





function qmv_check_texturl_build()
{

	if (qmv.texturl_state=="text" && qmv.cur_item.className.indexOf("qmdivider")+1)
	{
		qmv_show_dialog("alert",null,"Custom text can't be applied to divider items.",400);
		return false;
	}


	return true; 

}



function qmv_set_texturl_field(a,gettext,publish,for_undo,type)
{


	var tuf;
	if (type=="text")
		var tuf = document.getElementById("qmv_edittext_field");
	else if (type=="url")
		var tuf = document.getElementById("qmv_editurl_field");
	
		
	if (type=="text" || gettext || publish)
	{
		var b = a.cloneNode(true);
		var after = qmv_atag_text_remove_objects(b,publish,for_undo);
	

		if (gettext)
		{
			if (for_undo)
				return b.innerHTML.replace(/\n/g,"")+after;
			else
				return b.innerHTML.replace(/\n/g,"");
		}
		else if (publish)
			return b.innerHTML.replace(/\n/g,"")+after;
		else
		{

			var sv = b.innerHTML;
			sv = sv.replace(/\n/g,"");
			
			try
			{
				sv = decodeURI(sv);
			}
			catch(e){}
			
			

			tuf.value = sv;
			tuf.prev_value = tuf.value;

								
			if (a.className.indexOf("qmdivider")+1 && !tuf.value)
				qmv_texturl_enable_disable(tuf,true);
			else
				qmv_texturl_enable_disable(tuf,false);

		}

	
	}
	else
	{
		var tv1 = a.getAttribute("href",2);
		if (tv1==null)
			tv1 = "";		
		
		tuf.value = tv1;
		tuf.prev_value = tuf.value;

		if (a.className.indexOf("qmdivider")+1 || a.className.indexOf("qmtitle")+1 || a.className.indexOf("qmcbox")+1)
			 qmv_texturl_enable_disable(tuf,true);
		else
			 qmv_texturl_enable_disable(tuf,false);

	}

}

function qmv_texturl_enable_disable(tuf,disable)
{

	if (disable)
	{
		tuf[qp].style.backgroundColor = "#eeeeee";
		tuf[qp].style.borderStyle = "dotted";
		tuf.disabled = true;
	}
	else
	{
		tuf.disabled = false;
		tuf[qp].style.backgroundColor = "";
		tuf[qp].style.borderStyle = "";	

	}

}

function qmv_atag_text_remove_objects(a,publish,for_undo)
{
	
	
	var rval = "";
	var s = a.childNodes;
	for (var i=0;i<s.length;i++)
	{
		
		if (s[i].getAttribute && (s[i].getAttribute("qmvbefore") || s[i].getAttribute("qmvafter")))
		{

			
			if (publish || for_undo)
			{
				
				if (s[i].getAttribute("qmvafter"))
				{
					
					if (s[i].className && s[i].className.indexOf("qm-is")+1)
					{
						
						if (for_undo)
						{
							//used for reporting string
							rval += '[image: '+qm_image_base(s[i],true)+']';

						}
						else
						{
							
							rval = '<img ';
						
							talt = s[i].getAttribute("alt",2);
							if (!talt)
								talt = "";
							else
								talt = ' alt="'+talt+'"';							

							rval += ' class="'+s[i].className+'" src="'+qm_image_base(s[i],true)+'" width="'+s[i].getAttribute("width",2)+'" height="'+s[i].getAttribute("height",2)+'"'+talt+'>';
						}

					}
					

				}


			}


			a.removeChild(s[i]);
			i--;
		}
		

	}

	return rval;

}

//update the menu
function qmv_evt_update_tree_value(a,fromspin,skip_validate,skip_update,skip_inherit,is_quickcolor,skip_filter_update,skip_mirror,is_undo,skip_update_addons,skip_prev_val_check,skip_report_log,skip_bot_panel_update)
{
    
	
	if (!skip_prev_val_check && a.value==a.prev_value)
		return;

	if (a.getAttribute("isnontree"))
		return
	
	
	try
	{
	
		var dt = a.getAttribute("dtype");
		

		if (!skip_validate)
		{
			var alow = a.value.toLowerCase();
			
			if (a.value && dt)
			{
		
				var range = a.getAttribute("range");
				var oops = false;
				var oops_range = false;
			
				var t;
				var es;
				if (dt=="int")
				{
					t = parseInt(a.value);
					if (isNaN(t))
						oops = true;		

					a.value = t;

				
					if (!oops && range)
					{
						es = range.replace("x",t);
						es = es.replace("x",t);		
						if (eval(es))
							oops_range=true;

					}
			
				}
				else if (dt=="unit")
				{
					if (a.value.toLowerCase()!="auto")
					{
				
						t = parseInt(a.value);
						var r = parseFloat(a.value);
						if (isNaN(t) && isNaN(r))
							oops = true;
						else if (!qmv_lib_get_units(a.value))
							a.value = a.value+"px";

						if (isNaN(t))
							t = r;
					
						if (!oops && range)
						{
							es = range.replace("x",t);
							es = es.replace("x",t);	
							if (eval(es))
								oops_range=true;
						}
					
					}

				}
				else if (dt=="bool")
				{
					t = a.value.toLowerCase();
					if (t && t!="false")
						a.value = "true";

				}
				else if (dt=="float")
				{

					t = parseFloat(a.value);
					if (isNaN(t))
						oops = true;


				
					if (!oops && range)
					{
						es = range.replace("x",t);
						es = es.replace("x",t);	
						if (eval(es))
							oops_range=true;
					
					}
				}
				else if (dt.indexOf("edge")+1)
				{
					

					if (dt.indexOf("borderwidth")+1 || dt.indexOf("borderradius")+1 || dt.indexOf("margin")+1 || dt.indexOf("padding")+1)
					{	
						
						if (t = a.value.replace(/\,/g," "))
						{
							if (isNaN(parseInt(t)) && isNaN(parseFloat(t)))
							{
								oops = true;

							}
							else
							{
						
								if (t.indexOf(" ")==-1)
								{
								
									if (!qmv_lib_get_units(t))
										a.value = t+"px";
								}
								else
								{
									var tt = "";
									t = t.split(" ");
									for (var k=0;k<t.length;k++)
									{
										if (t[k] && !qmv_lib_get_units(t[k]))
											t[k] = t[k]+"px";

									}
	
									var count = 0;
									for (var k=0;k<t.length;k++)
									{
										if (count>3 || !t[k]) continue;
									
										tt+=t[k]+" ";
										count++	
									}	
		
									a.value = tt.substring(0,tt.length-1);
	
								}
							}
						}

					}
				}
				else if (dt == "styleimage")
				{
					
					if (a.value)
					{
						if (alow=="none" || alow=="null")
						{
							a.value = "none";
						}
						else if (alow.indexOf("linear-gradient")+1)
						{
							var aci=alow.indexOf("linear-gradient");
							a.value = qmv.css_prefix+"linear-gradient"+alow.substring(aci+15);
						}
						else
						{
							if (a.value.toLowerCase().indexOf("url(")==0)
								a.value = a.value.substring(4);
						
							if (a.value.toLowerCase().lastIndexOf(")")==a.value.length-1)
								a.value = a.value.substring(0,a.value.length-1);
								
							a.value = a.value.replace(/\ /g,"%20");
							a.value = a.value.replace(/\(/g,"%28");
							a.value = a.value.replace(/\)/g,"%29");
						
							a.value = "url("+a.value+")";	
						}
					}
					
					
					
				}
				else if (dt == "color" || dt=="colormulti")
				{
					
					if (!isNaN(parseInt(a.value,16)))
						a.value = "#"+a.value;
										
					if (a.value)
						a.value = a.value.replace(/^[ \t]+|[ \t]+$/,"");
				}

			
				if (oops || oops_range)
				{

				
					a.value = a.prev_value;
	
					var show_range = "";	
					if (oops_range)
					{
						if (range=="x<0 || x>1")
							show_range = "<br><br>The valid range for this settings is between 0 and 1.";
						else if (range=="x<0")
							show_range = "<br><br>The value for this setting must be greater than 0.";
						else if (range=="x<0 || x>50")
							show_range = "<br><br>The valid range for this settings is between 0 and 50.";
						else if (range=="x<0 || x>20")
							show_range = "<br><br>The valid range for this settings is between 0 and 20.";
						else if (range=="x<0 || x>10")
							show_range = "<br><br>The valid range for this settings is between 0 and 10.";
				
					}

					if (!fromspin)
					{
						qmv_show_dialog("alert",null,"The value you selected or entered is invalid."+show_range,450);	
						return;
					}
	
				}
	
			
			}
		
		}
		
		var cat = a.getAttribute("category");
			
		
		if (a.iseditcolor)
		{
			
			var compare = a.prev_value.toLowerCase();
			for (var i=0;i<qmv.color_recent.length;i++)
			{
					
				if (qmv.color_recent[i].value==compare)
				{
							
					qmv.color_recent[i].inp.value = a.value;
					qmv_evt_update_tree_value(qmv.color_recent[i].inp,false,false,false,true,true);

					if (!a.value || a.value.toLowerCase()=="transparent")
						i--;

				}

			}

			a.prev_value = a.value;

			
			var ta = document.getElementById("qmvtree_color_shortcuts");
			if (ta.style.display=="block")
				qmv_shortcut_init(ta);	
			
			
			
			qmv_setbox_update_quick_color();
			return;

		}

		
		if (dt && (dt=="color" || dt=="colormulti"))
			qmv_color_build_button_set(a,dt);
			
		
		var undo_inp = a;
		
		
		if (!skip_mirror && a.mirror)
			a.mirror.value = a.value;
			
			
		
		if (cat=="create")
			qmv_evt_update_menu_settings(a.value,a.rule,a.getAttribute("sname"),a.getAttribute("cname"),a.getAttribute("dtype"),a);
		else if (cat=="inline")
		{
			
			qmv_evt_update_inline_style(a.value,a.rule_obj,a.getAttribute("sname"),a.getAttribute("cname"));
			
			
			if (a.getAttribute("sname")=="width" && a.rule_obj && a.rule_obj.idiv)
			{
				
				if (a.value)
					qm_arc("qm-fixedwidth",a.rule_obj,true)
				else
					qm_arc("qm-fixedwidth",a.rule_obj)
				
			}
			
		}
		else if (cat=="texturl")
		{
			
			var dlg = a.getAttribute("dlginp");
			if (!dlg || dlg=="text")
				qmv_evt_update_texturl(a);
			else
				qmvi_update_anchor_settings(a,dlg);

		}
		else if (cat=="addon")
		{
			
			if (!skip_mirror)
			{
				
				qmv_evt_update_addon(a.value,a.rule_obj,a.getAttribute("sname"),a.getAttribute("cname"),a.getAttribute("dtype"),a,skip_update);
				
			}	

		}
		else if (cat=="css")
		{
			
			if (!skip_mirror && !a.getAttribute("skipapplyval"))
			{
				qmv_evt_update_css_style(a.value,a.rule,a.getAttribute("sname"),a.getAttribute("cname"),null,null,fromspin);
			}
			
			if (a.isfilter)
			{
				var rinp = qmv_find_update_tree_value("css",a.origrule,a.getAttribute("cname"),a.value,false,true);
				rinp.prev_value = a.value;
				undo_inp = rinp;
			}
			else if (!skip_filter_update && document.getElementById("qmvtree_filter").cdiv.style.display=="block")
			{
				qmv_filter_init2();
			}
			

			if (a.origrule.indexOf("qmpersistent")+1 && !qmv.addons.sopen_auto["on"+qmv.id])
			{
				qmv_show_dialog("question-yesno",null,"Persistent styles apply to all menu items which have URL links which match the location of the web page displaying the menu.<br><br>The persistent state add-on must be enabled and published with your menu for the styles to display, would you like to enable the persistent state add-on?",500,"qmv_context_cmd(new Object(),'addon_sopen_auto')");	
			}
			
		}
		else if (cat.indexOf("classname")+1)
		{
			qmv_update_selected_classname(cat,a.getAttribute("cname"),a.value,is_undo);
		}
		else if (cat.indexOf("attribute")+1)
		{
			qmv_update_selected_attribute(cat,a.getAttribute("cname"),a.value,is_undo);
		}
		
		//else if (cat=="iextra")
		//{
			//if (!skip_mirror)
				//qmv_evt_update_item_extra(a.value,a.getAttribute("sname"),a.getAttribute("cname"),a.rule,a.getAttribute("dtype"),a);
		//}
		
		
		if (!is_undo && !a.mirror && !skip_report_log)
			qmvi_report_add_line("edits","undo","tree",cat,"",undo_inp,a.prev_value);
		

		if (!skip_inherit && !fromspin && !is_quickcolor)
		{
			var ir = a.getAttribute("inheritrule");
			if (ir)
				qmv_inherit_style_question(ir,a.getAttribute("cname"),a.value,a);
			
		}

		
		
		qm_sam_stretch(document.getElementById("qm"+qmv.id));
		qmv_reselect_all_menu_items_from_root_for_big_update(true);
		
		if (cat!="addon" && !skip_update_addons)
			qmv_update_all_addons(null,null,null,null,"{skip_htmledit_panel:"+skip_bot_panel_update+"}");
			
		if (!skip_mirror)
		{
			if (a.mirror)
			{
				//a.mirror.value = a.value;
				qmv_evt_update_tree_value(a.mirror,null,null,null,null,null,null,true);
			}
			else
			{

				
				var sb = document.getElementById("qmvi_setbox");
				if (sb.style.visibility == "visible")
				{
					var sbi = sb.getElementsByTagName("INPUT");
					for (var i=0;i<sbi.length;i++)
					{
						if (sbi[i].mirror==a)
						{
							
							sbi[i].value = a.value;
							qmv_evt_update_tree_value(sbi[i],null,null,null,null,null,null,true);

							break;
						}

					}

				}

			}
		}
		
		
		qmv_position_addon_tools();
		qmv_position_pointer();
		a.prev_value = a.value;
	
		if (dt && !a.iseditcolor && !a.isfilter && !a.mirror)
		{
			
			if (dt=="color" || dt=="colormulti")
			{
				if (a.value)
					qmvi_color_recent_add(a,true);
				else
					qmvi_color_recent_remove(a);
			}

		}


		if (dt && (dt=="color" || dt=="colormulti") && !is_quickcolor && !a.mirror)
		{
			
			var ta = document.getElementById("qmvtree_color_shortcuts");
			if (ta.style.display=="block")
				qmv_shortcut_init(ta);

			qmv_setbox_update_quick_color();
			
		}

	
	}
	catch(e)
	{
		alert(e);
		if (a.prev_value)
		{
				
			qmv_show_dialog("warning-undo",a,"Invalid Value: The value you entered is not valid.",450)
			a.value = a.prev_value;
			return true;
		}

	}
	
	var code = a.getAttribute("code");
	if (!is_undo && code)
		eval(code);

	
	if (qmv.vdesign_tab!="design")
		qmvi_vd_tab_update_content();

		
	if (cat!="addon")
	{
		qmv_htmledit_update_from_visual_change(skip_bot_panel_update);	
		qmv_htmleditor_reset_dialog_insert_image();
	}
	
	qmv.changed = true;
	
}


function qmv_reset_stretch_item_minwidths(a)
{
	var ch = a.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		if ((ch[i].qmmi && ch[i].tagName=="A") || (ch[i].tagName=="DL"))
		{
			ch[i].style.minWidth="";	
			
		}
	
	}
}


function qmv_reselect_all_menu_items_from_root_for_big_update(sam_only)
{
	
	
	var build_path = new Array();
	var ci = qmv.cur_item;
	build_path.push(ci);
	
	while ((ci=ci[qp]) && !qm_a(ci))
	{
		if (ci.idiv)
			build_path.push(ci.idiv);
	}
	
	for (var i=build_path.length-1;i>=0;i--)
	{
		if (sam_only)
		{
			if (build_path[i] && build_path[i].cdiv)
				qm_sam(build_path[i],build_path[i].cdiv);
		}
		else
			qm_oo(new Object(),build_path[i]); 
	}
	
}


