function qmvi_get_multi_columns(a)
{

	if (a[qp] && a[qp].tagName=="DD" && a[qp][qp].className.indexOf("qmmulti")+1)
	{

		var mc = a[qp][qp];
		var mc_id = -1;
				
		for (var i=0;i<10;i++)
		{
			if (mc.className.indexOf("qmml"+i)+1)
			{
				mc_id = i;
				break;
			}
		}
		
		var robj = new Object();
		
		robj.id = mc_id;
		robj.columns = mc[qp].getElementsByTagName("DL");
		
		return robj;
				
	}

}



function qmv_evt_update_tree_value_enter(e,a)
{

	e = e || window.event;


	if (e.keyCode==13)
		qmv_evt_update_tree_value(a);
		
	

}



function qmv_evt_title_mousedown(e,src,type,isrel)
{
	

	
	e = e || window.event;
				
	qmv.title_mdown = true;
	qmv.title_prev_x = e.screenX;
	qmv.title_prev_y = e.screenY;
	qmv.title_move_shadow = false;
	qmv.title_type = type;
	qmv.title_relative = isrel;

	if (!type)
	{
		if (qmv.interface_full)
			return;

		qmv.title_obj = document.getElementById("qmvi");
		qmv.title_adjust_floating_window = true;
	}
	else
	{
		if (type==1)
			qmv.title_obj = document.getElementById("qmvi_dialog");
		else if (type==2)
			qmv.title_obj = document.getElementById("qmvi_msg_dialog");
		else if (type==3)
			qmv.title_obj = document.getElementById("qmvi_help_dialog");
		else if (type==4)
			qmv.title_obj = document.getElementById("qmvi_setbox");
		else if (type==5)
		{
			qmv.title_obj = document.getElementById("qmvi_logon");
			qmv.title_move_shadow = document.getElementById("qmvi_logon_shadow");
		}
		else if (type==6)
			qmv.title_obj = document.getElementById("qmvi_ftop_dialog");
		else if (type==7)
			qmv.title_obj = document.getElementById("qmvi_gtop_dialog");
		else if (type==8)
			qmv.title_obj = document.getElementById("qmvi_ktop_dialog");
		else if (type=='bpsizer')
			qmv.title_obj = document.getElementById("qmvi_bpanel_sizer");
		else
			qmv.title_obj = type;
			
		
	}

	if (type!='bpsizer')
		src.style.cursor = "move";

	qm_kille(e);
	return false;

}



function qmv_evt_title_mousemove(e,from_capture)
{
	
	
	var m = qmv.title_obj;	
	if (!m) return;

	if (qmv.title_mdown)
	{
		
		
		var xdif = qmv.title_prev_x-e.screenX;
		var ydif = qmv.title_prev_y-e.screenY;
	
		if (qmv.title_relative)
		{

			if (qmv.title_type!='bpsizer')
				m.style.left = (parseInt(m.style.left)-xdif)+"px";
				
			m.style.top = (parseInt(m.style.top)-ydif)+"px";

		}
		else
		{
			
			if (qmv.title_type!='bpsizer')
				m.style.left = (m.offsetLeft-xdif)+"px";
				
			m.style.top = (m.offsetTop-ydif)+"px";
		}
		

		if (qmv.title_move_shadow)
		{
			
			qmv.title_move_shadow.style.left = parseInt(m.style.left)+3+"px";
			qmv.title_move_shadow.style.top =  parseInt(m.style.top)+3+"px";
		}

		
		qmv.title_prev_x = e.screenX;
		qmv.title_prev_y = e.screenY;


		qmv.title_moved = true;		
		
		
		qm_kille(e);
		return false;
		
	}

}


function qmv_evt_title_mouseup(e,src)
{
	
	if (qmv.title_adjust_floating_window) qmv_handle_resize();
		

	qmv.title_mdown = false;
	if (qmv.title_moved && qmad.br_ie)
		src.releaseCapture(true);
	
	if (qmv.title_type=='bpsizer')
	{
		var nh = parseInt(qmv.title_obj.style.top)+4;
		
		qmv.bpanel.height = qmv.bpanel.height-nh;
		if (qmv.bpanel.height<0) qmv.bpanel.height=0;
		
		if (qmv.bpanel.height<20)
			qmv.bpanel.saveHeight = 20;
		else
			qmv.bpanel.saveHeight = qmv.bpanel.height;
		
		
		qmv_persistent_save_setting("tabpanel_height",qmv.bpanel.saveHeight);	
				
		qmv_resize_interface();
		qmv.title_obj.style.top = "-4px";
		
		qmv_lightbox_resize();
		
	}
	else
		src.style.cursor = "";
	
	
	
	
	
	
}


function qmv_evt_move_fixcapture(e)
{
		
	if (qmv.title_mdown)
		qmv_evt_title_mousemove(e,true);
				
	if (qmv.addontools_moved)
		qmv_addontools_mouse_move(e,qmv.addontools_obj);

	if (qmv.pointersizer_moved)
		qmv_pointer_sizer_move(e,qmv.pointer_sizer_obj);
		
	if (qmv.gradient && qmv.gradient.md && qmv.gradient.md.mdown)
		qmv_imgdialog_gstop_handle_mousemove(e,qmv.gradient.md.stopdiv);
		
	if (qmv.slider && qmv.slider.mdown)
		qmv_dialog_edge_part_slider_arrow_mmove(e,qmv.slider.arrowdiv);	
	
}


function qmv_evt_fix_mouse_up(e)
{

	if (!qmv.preview_mode) qm_la = null;
	
	if (qmv.color_vals && qmv.color_vals.bright_down)
		qmv_color_brightness_mouseup(e,document.getElementById("qmvi_color_bright_bar"))

	if (qmv.color_vals && qmv.color_vals.hs_down)
		qmv_color_huesaturation_mouseup(e,document.getElementById("qmvi_color_hs_div"))

	if (qmv.addontools_moved)
		qmv_addontools_mouse_up(e,qmv.addontools_obj);

	if (qmv.pointersizer_moved)
		qmv_pointer_sizer_up(e,qmv.pointersizer_obj);
	
	if (qmv.gradient && qmv.gradient.md && qmv.gradient.md.mdown)
		qmv_imgdialog_gstop_handle_mouseup(e,qmv.gradient.md.stopdiv);
	
	if (qmv.slider && qmv.slider.mdown)
		qmv_dialog_edge_part_slider_arrow_mup(e,qmv.slider.arrowdiv);	
	
}


