{

	var count = 0;

	for (var i=0;i<10;i++)
	{

		if (document.getElementById("qm"+i))
			count++;
	}
	

	return count;
}

function qmv_lib_get_new_menu_id()
{

	var i = 0;
	while (document.getElementById("qm"+i))
		i++;
	

	return i;
}

function qmv_lib_update_add_rule_styles(style,rules,search,value,append,skip_split)
{
	
	for (var i=0;i<rules.length;i++)
	{
		
		if (rules[i].selectorText.toLowerCase() == search)
		{
			if (append)
				rules[i].style.cssText+=value;
			else
				rules[i].style.cssText = value;
	
			return;
		}	
	}	
	
	var ss = new Array(search);
	if (!skip_split)
		ss = search.split(",");
	
	if (!value) value='';
	for (var i=0;i<ss.length;i++)
		qmv_css_addrule_to_sheet(style,ss[i],value);
		
	//qmv_update_styles_object();

}

function qmv_lib_update_remove_rule(style,rules,search,value,skip_split)
{
	
	for (var i=0;i<rules.length;i++)
	{
	
		var s = rules[i].selectorText.toLowerCase();
		if (!skip_split)
		{
			s = s.split(",")[0];
			//s = s.replace(/ > /g,">");
		}
	
		if (s == search)
		{
			try
			{
				if (style.removeRule)
					style.removeRule(i);
				else if (style.deleteRule)
					style.deleteRule(i);
			}
			catch(e)
			{
				continue;
			}
			
			return true;
		}	

	}	

}



function qmv_lib_parse_value(value,dtype,rfalse,rnull)
{

	var rv;

	if (dtype=="int")
	{
		
		if (value)
		{
			
			rv = parseInt(value);
			if (!isNaN(rv)) return rv;
			
		}
		
		if (rfalse)		
			return false;
		else if (rnull)
			return null;
		else
			return 0

	}
	else if (dtype=="float")
	{

		if (value)
		{
			
			rv = parseFloat(value);
			if (!isNaN(rv)) return rv;

		}
				
		if (rfalse)		
			return false;
		else if (rnull)
			return null;
		else
			return 0


	}
	else if (dtype=="bool")
	{

		if (value+"".toLowerCase()=="false")
			return false;
		else if (value+"".toLowerCase()=="true")
			return true;
		else if (value)
			return true;

		if (rnull)
			return null;
		else
			return false;

	}
	else if (dtype=="corners-bool-array")
	{
		if (value)
			return eval("new Array("+value+")");
		else if (rnull)
			return null;
		else if (rfalse)
			return false;
		else
			return "";	

	}

	return value;


}



function qm_get_level(a)
{

	lev = 0;
	if (a && a.idiv) lev++;
	while (!qm_a(a) && (a=a[qp]))
	{
		if (a.idiv)
			lev++;
	}
	
	return lev;

}

function qm_index(a)
{
	
	if (a && qm_get_menu(a))
		return qm_get_menu(a).id.substring(2);
	else
		return "";


}

function qm_get_menu(a)
{

	while (!qm_a(a) && (a=a[qp]))
		continue;


	return a;

}


function qmv_lib_get_qm_stylesheet(searchfor,first_only)
{

	
	if (!searchfor)
		searchfor = ".qmclear";


	var ss = document.styleSheets;
	var robj = new Object();


	for (var i=0;i<ss.length;i++)
	{
		if (ss[i])
		{
			try
			{
			
				var rules = ss[i].cssRules;
				
				if (rules)
				{
					for (var j=0;j<rules.length;j++)
					{
							
						if (rules[j] && rules[j].selectorText && rules[j].selectorText.toLowerCase().indexOf(searchfor)+1)
						{
							robj["ss"+i] = ss[i];
							break;
						}

					}
				}
			
			}
			catch(e){}	
	
		}

	}
	


	if (!first_only)
	{
		var i;
		var c = 0;
		for (i in robj)
			c++;
	

		if (c>0)
			return robj;
	}
	else
	{

		var i;
		for (i in robj)
			return robj[i];

	}
	

}




function qmv_lib_is_menu_vertical(id)
{
	
	var fa = document.getElementById("qm"+id);
	if (qmv_is_container_horizontal(fa))
		return false;
	else
		return true;
	
}


function qmv_lib_get_window_dimensions()
{

	var dh = 0;
	var dw = 0;
	if (window.innerHeight)
	{
		dh = window.innerHeight;
		dw = window.innerWidth;
	}
	else
	{
		dh = document.documentElement.clientHeight;
		dw = document.documentElement.clientWidth;
	}
		
	return new Array(dw,dh);

}

function qmv_lib_center_element_in_window(a)
{
	
	var wd = qmv_lib_get_window_dimensions();
	var dw = wd[0];
	var dh = wd[1];

		
	var qw = a.offsetWidth;
	var qh = a.offsetHeight;

	var d;
	var st = 0;
	var sl = 0;
	if (d = document.documentElement)
	{
		st = d.scrollTop;
		sl = d.scrollLeft;
	}


	if (qmad.br_ie && !qmad.br_strict)
	{
		a.style.top = 50+"px";
		a.style.left = 50+"px";

	}
	else
	{
		a.style.top = (parseInt((dh-qh)/2)+st)+"px";
		a.style.left = (parseInt((dw-qw)/2)+sl)+"px";
	}

}


function qmv_lib_insert_after(ins,obj)
{

	var a;
	if (a = obj.nextSibling)
	{
		if (obj.nextSibling.idiv)
		{
			if (a.nextSibling)
				return obj.parentNode.insertBefore(ins,a.nextSibling);
			else
				return obj.parentNode.appendChild(ins);

		}
		else
			return obj.parentNode.insertBefore(ins,a);

	}
	else
		return obj.parentNode.appendChild(ins);

}

function qmv_lib_get_nextsibling_atag(a)
{

	ps = a.nextSibling;
	while (ps && ps.tagName!="A")
		ps = ps.nextSibling;


	return ps;
}

function qmv_lib_get_previoussibling_atag(a)
{

	ps = a.previousSibling;
	while (ps && ps.tagName!="A")
		ps = ps.previousSibling;


	return ps;
}


function qmv_lib_get_nextsibling_atag_or_span(a,is_multi)
{
	
	
	ps = a.nextSibling;
	while (ps)
	{
		
		if (ps.tagName=="SPAN")
		{
			
			
			
			if (ps.className.indexOf("qmtitle")+1)
				break;	
			
			if (ps.className.indexOf("qmdivider")+1)
				break;	
			
			if (ps.className.indexOf("qmcbox")+1)
				break;	
				
		}

		if (ps.tagName=="A" || ps.tagName=="DD")
			break;

		ps = ps.nextSibling;

	}

	if (!ps || (ps.tagName!="SPAN" && ps.tagName!="A" && ps.tagName!="DD")) ps = null;

	
	if (ps && is_multi)
		ps = ps.firstChild;
	
	return ps;
}


