function qmv_set_publish_menus_object()
{
	
	if (!qmv.publish)
	{
		qmv.publish = new Object();
				
		qmv.publish.css_type = "inpage";
		qmv.publish.code_type = "inpage";
		qmv.publish.structure_type = "inpage";
	}

	qmv.publish.smenus = new Array();
	qmv.publish.smenus_pos=0;

	for (var i=0;i<10;i++)
	{

		if (document.getElementById("qm"+i))
			qmv.publish.smenus.push(i);
			
	}


}

function qmv_wizard_create(type,twiz)
{
		
	var ih = "";
	var pg;
	var len=1;
	
	while (pg = twiz["page"+len]) len++;
	len--;
		
	for (var i=len;i>=1;i--)
	{
				
		pg = twiz["page"+i];
		var sr = 'style="position:absolute;visibility:hidden;width:100%;"';
		if (pg.isroot)sr = 'style="" isroot=1';
		
		var sf = "";
		if (pg.isfinish) sf = "isfinish=1";
			
		ih += '<div id="qmvi_'+type+'_container_page'+i+'" '+sr+' '+sf+'>';
			ih += '<div class="qmvi-publish-title" style="margin-bottom:20px;font-weight:bold;">'+pg.title+'</div>';
			ih += '<div style="padding:15px 0px 15px 0px;">';
			
			if (!pg.isfinish)
			{
				ih += '<table cellpadding=0 cellspacing=0 border=0 style="margin:0px auto;">';
				
				var item;
				var j=1;
				var jcount=1;
				while (pg["z"+jcount]) jcount++;
				jcount--;
				
				while (item = pg["z"+j])
				{
					var tnext = "";
					if (item.next) tnext = "qmvnext="+item.next;
					
					ih += '<tr>';
						ih += '<td><input '+tnext+' id="qmvi_'+type+'_page'+i+'_opt'+j+'" name="qmvi_'+type+'_page'+i+'" type="radio" value="'+j+'"></td>';
						ih += '<td><div style="width:10px;">&nbsp;</div></td>';
						ih += '<td onclick="document.getElementById(\'qmvi_'+type+'_page'+i+'_opt'+j+'\').checked = true;" class="qmvi-common qmvi-dialog-input-title" style="color:#222222;text-align:left;">'+item.text+'</td>';
					ih += '</tr>';
				
					if (j!=jcount)
						ih += '<tr><td><div style="font-size:1px;height:5px;"></div></td></tr>'
					
					j++;
				}
				
				ih += '</table>';
			}
			else
			{
				ih+=pg.content;
			
			}
			
			ih += '</div>';
		ih += '</div>';
		
	}
	
	return ih;

}

function qmv_wizard_get_current_option_selected(type,page_num)
{
	
	var co = document.getElementsByName("qmvi_"+type+"_page"+page_num);
	for (var i=0;i<co.length;i++)
	{
		if (co[i].checked)
			return {index:i+1,obj:co[i]}
		
	}

}


function qmv_wizard_move(type,button)
{
	
	var wiz = qmv[type];
	
	
	if (button=="next")
	{
		
		var cs = qmv_wizard_get_current_option_selected(type,wiz.cur_page);
		if (cs)
			wiz.track[wiz.track.length-1].selected = cs.index;
			
		if (cs && (mn = cs.obj.getAttribute("qmvnext")))
		{
			wiz.cur_page=parseInt(mn);
			wiz.track.push({page:wiz.cur_page});
		}
		else
			alert("Developer Alert Error - The wizard needs a 'qmvnext' param on the radio to tell it where to go");
		
	}
	else if (button=="previous")
	{
		if (wiz.track.length>1)
		{
			wiz.cur_page=wiz.track[wiz.track.length-2].page;
			wiz.track.pop();
		}
	}
	
	
	var wc = document.getElementById("qmvi_"+type+"_container_page"+wiz.cur_page);
	if (wc)
	{
		wc.style.visibility = "inherit";
	}
	
	if (wc.getAttribute("isfinish"))
		qmv_wizard_set_finish(type);
	
	
	var i=1;
	var hc;
	while (hc = document.getElementById("qmvi_"+type+"_container_page"+i))
	{
		if (i!=wiz.cur_page)
			hc.style.visibility = "hidden";
	
		i++;
	}
	
	
	qmv_wizard_set_button_states(type,wiz.cur_page);
	qmv_wizard_init_option(type,wiz.cur_page);

}

function qmv_wizard_set_finish(type)
{
	var wiz = qmv[type];
	
	if (type=="pubwizard")
	{
		var fl = document.getElementById("qmv_pubwizard_finish_link");
		var pointer = '<span style="color:#444;font-weight:bold;">&gt;</span> ';
		
		var p_type = "manual";
		var p_where = "inline";
		var p_split = "false";
		
		var wt = wiz.track;
		for (var i=0;i<wiz.track.length;i++)
		{
			if (i==wiz.track.length-1)
				break;
			
			if (wt[i].page==3 && wt[i].selected==1 && wt[0].selected==1)
				p_type="auto";
						
			if (wt[i].page==4 && wt[i].selected==2 && wt[0].selected==1)
				p_where="external";
			
			if (wt[i].page==2 && wt[i].selected==1 && wt[0].selected==2)
				p_where="external";			
				
			if (wt[i].page==5 && wt[i].selected==2)
				var p_split = "true";
			
		}
			
		var bt1 = document.getElementById("qmv_pubwizard_finish_buttons_t1");
		var bt2 = document.getElementById("qmv_pubwizard_finish_buttons_t2");	
		var bl = "File "+pointer+" ";
		var oc;
		if (p_type=="manual")
		{
			if (p_split=="true")
			{
				oc = "qmv_show_dialog('publish1',null,null,null,null,null,null,null,null,null,true)";
				bl += "Publish (manual) "+pointer+" Custom Publish";
			}
			else
			{
				if (p_where=="external")
				{
					oc = "qmv_show_dialog('quick_publish',null,null,null,null,null,null,null,null,null,true)";
					bl += "Publish (manual) "+pointer+" Quick Publish (external)";
				}
				else
				{
					oc = "qmv_show_dialog('quick_publish_inline',null,null,null,null,null,null,null,null,null,true)";
					bl += "Publish (manual) "+pointer+" Quick Publish (inline)";
				}
			}	
			
			bt1.style.display="none";
			bt2.style.display="";
			
		}
		else
		{
			if (p_where=="inline")
			{
				oc = "qmv_show_dialog('publish_auto',null,null,null,null,null,null,null,null,null,true)";
				bl += "Publish (auto)";
			}
			else
			{
				oc = "qmv_show_dialog('publish_auto',null,null,null,['pall2'],null,null,null,null,null,true)";
				bl += "Publish (auto)";
			}
			
			bt2.style.display="none";
			bt1.style.display="";
				
		}
		
		var blk = document.getElementById("qmv_pubwizard_finish_link");
		if (blk)
			blk.innerHTML = bl;
		
		
		wiz.finish_click = oc;
		
	}

}


function qmv_wizard_click_finish(type)
{

	var wiz = qmv[type];
	eval(wiz.finish_click);
	
	var close_b = document.getElementById("qmv_dialog_"+wiz.dlg.dlgtype+"button2");
	if (close_b)
		close_b.value = "Close";
}


function qmv_wizard_set_button_states(type,page_num)
{
	var wiz = qmv[type];
	var wc = document.getElementById("qmvi_"+type+"_container_page"+page_num);
	
	var prev_b = document.getElementById("qmv_dialog_"+wiz.dlg.dlgtype+"button0");
	var next_b = document.getElementById("qmv_dialog_"+wiz.dlg.dlgtype+"button1");
	var close_b = document.getElementById("qmv_dialog_"+wiz.dlg.dlgtype+"button2");
	
	if (wc.getAttribute("isroot"))
		prev_b.disabled = true;
	else
		prev_b.disabled = false;
	
	
	if (wc.getAttribute("isfinish"))
	{
		next_b.disabled = true;
		//close_b.value = "Finish";
	}
	else
	{
		next_b.disabled = false;
		close_b.value = "Cancel";
	}
	
	
}

function qmv_wizard_init(dlg,type)
{
	
	if (!qmv[type])
		qmv[type] = new Object();
		
	var wiz = qmv[type];
	wiz.track = new Array();
	wiz.dlg = dlg;
	
	wiz.cur_page = 1;
	wiz.track.push({page:wiz.cur_page});
	
	qmv_wizard_set_button_states(type,wiz.cur_page)
	qmv_wizard_init_option(type,wiz.cur_page)
	
}

function qmv_wizard_init_option(type,page_num)
{
	var wiz = qmv[type];
	
	var opt_selected;
	if (wiz.track[wiz.track.length-1].selected)
	{
		opt_selected = wiz.track[wiz.track.length-1].selected;
		wiz["page"+page_num+"_selected"] = opt_selected;
	}
	else
	{
		opt_selected = wiz["page"+page_num+"_selected"]
		if (!opt_selected)
			opt_selected = wiz["page"+page_num+"_selected"] = 1;
			
		wiz.track[wiz.track.length-1].selected = opt_selected;
	}
		
	var r = document.getElementById("qmvi_"+type+"_page"+page_num+"_opt"+opt_selected);
	
	if (r)
		r.checked = true;	

}

