function qmv_htmleditor_save_inline_setting_or_apply(sname,value,is_panel)
{

	if (!is_panel)
	{
		if (!qmv.htmleditor.dialog_save_inlines)
			qmv.htmleditor.dialog_save_inlines = new Object();
		
		qmv.htmleditor.dialog_save_inlines[sname] = value;
	}
	else
	{
	
		var inp = qmv_find_update_tree_value("inline","inline",sname,value,false,true);
		if (inp) qmv_evt_update_tree_value(inp);
	
	}

}

function qmv_htmleditor_apply_inline_setting()
{
	var si = qmv.htmleditor.dialog_save_inlines;
	if (si)
	{
		for (var i in si)
		{
			var inp = qmv_find_update_tree_value("inline","inline",i,si[i],false,true);
			if (inp) qmv_evt_update_tree_value(inp);
		
		}
	}

}

function qmvi_htmledit_apply_class(e,cb,type)
{

	var qd = document.getElementById("qmvi_df_htmledit_design").contentWindow;
	var ze = qd.document.getElementById("z_edit_item");

		
	if (type=="active")
		qm_arc("qmactive",ze,cb.checked);
	else if (type=="persistent")
		qm_arc("qmpersistent",ze,cb.checked);
		
	qmv_htmleditor_addon_init(ze);

}


function qmv_htmleditor_pastecontent(qd,ze)
{

	var pt = parent.xqmv_clipboard_get_contents();
	qd.document.execCommand("insertHTML",null,pt);
	
}

function qmv_htmleditor_copycontent(type,qd,ze)
{

		
	var is_panel = false;
	if (ze.id=="z_edit_item")
		is_panel = true;

	var sel = qd.getSelection();
		
	var copied = false;
	if (sel.rangeCount==1)
	{
		var r = sel.getRangeAt(0);
		
		var tn;
		if ((sel.focusNode==sel.anchorNode) && (tn=sel.focusNode))
		{
			var df = r.cloneContents()
			if (df)
			{
			
				var ch = df.childNodes;
				if (ch.length==1 && ch[0] && ch[0].tagName=="IMG")
				{
					var cstr = '<img src="'+ch[0].src+'" width="'+ch[0].width+'" height="'+ch[0].height+'">';
					parent.xqmv_clipboard_copy(cstr);
									
					copied = true;
				}
			
			}
		
		}

	}

	
	if (type=="copy")
	{
		if (!copied)
			parent.xqmv_clipboard_copy(sel.toString());
	}
	else if (type=="cut")
	{
		if (!copied)
			parent.xqmv_clipboard_copy(sel.toString());
			
		sel.deleteFromDocument();
	}
	
}

function qmv_htmleditor_style_all(ze,sname,jname,value,tag,arg)
{

	var ch = ze.childNodes;
	var hit = false;
	if (ch.length==1 && ((ch[0].tagName=="SPAN" && ch[0].style) || (tag && ch[0].tagName==tag)))
	{
		if (tag)
		{
			ze.innerHTML = ch[0].innerHTML;
			hit = true;
		}
		else
		{
			var csst = (ch[0].style.cssText+"").toLowerCase();
			var len = csst.split(";").length;
		
			if (ch[0].style[jname].toLowerCase()==value)
			{	
				//undo a match setting (button toggles the setting on and off) - remove the outer span
				if (len<=2)
					ze.innerHTML = ch[0].innerHTML;
				else
					ch[0].style[jname] = "";
					
				hit = true;
			}
			else
			{
				//change the setting
				ch[0].style[jname] = value;
				hit = true;
			}
		}
	}
	
	if (!hit)
	{
		if (tag)
		{
			if (!arg) 
				arg = "";
			else
				arg = " "+arg;
				
			ze.innerHTML = '<'+tag+arg+'>'+ze.innerHTML+'</'+tag+'>';
		}
		else
			ze.innerHTML = '<span style="'+sname+':'+value+';">'+ze.innerHTML+'</span>';
	}
}


function qmv_htmleditor_button_click(e,type,is_panel)
{

	var pfix = "";
	if (!is_panel) pfix = "dlg_";
	
	var qd = document.getElementById("qmvi_"+pfix+"df_htmledit_design").contentWindow;
	var ze = qd.document.getElementById("z_"+pfix+"edit_item");
	
	var sel = qd.getSelection();
	var tsel = qmv_util_get_selection_text_start_end(ze,sel);
	var all_selected = (tsel.start&&tsel.end);
		
	
	if (type=="bold")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
		{
			if (!all_selected)
				qd.document.execCommand("bold",null,null);
			else
				qmv_htmleditor_style_all(ze,"font-weight","fontWeight","bold")
		}
	}
	else if (type=="italic")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
		{
			if (!all_selected)
				qd.document.execCommand("italic",null,null);
			else
				qmv_htmleditor_style_all(ze,"font-style","fontStyle","italic")
		}
	}
	else if (type=="underline")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
		{
			if (!all_selected)
				qd.document.execCommand("underline",null,null);
			else
				qmv_htmleditor_style_all(ze,"text-decoration","textDecoration","underline")	
		}
	}
	else if (type.indexOf("justify")+1)
	{
		var tj = "";
		
		if (type.indexOf("center")+1)
			tj="center";
		else if (type.indexOf("right")+1)
			tj="right";
		else if (type.indexOf("left")+1)
			tj="left";
				
		ze.style.textAlign = tj;
		qmv_htmleditor_save_inline_setting_or_apply("textAlign",tj,is_panel);
	
	}
	else if (type=="copy")
	{
		qd.document.execCommand("copy",null,null);
		
	}
	else if (type=="paste")
	{
		qd.document.execCommand("paste",null,null);
	}
	else if (type=="fore_color")
	{
		if (!sel.isCollapsed)
			qmv_htmleditor_do_color_change("fore_color",is_panel);
		else
		{
			var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color");
			fcb.value = fcb.style.backgroundColor+"";
			qmv_show_dialog("color",fcb,null,null,null,null,null,null,null,null,true);
		}
	}
	else if (type=="fore_color_change")
	{
		var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color");
		fcb.value = fcb.style.backgroundColor+"";
		qmv_show_dialog("color",fcb,null,null,null,null,null,null,null,null,true);
	}
	else if (type=="back_color_inline")
	{
		var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_back_color_inline");
		fcb.value = fcb.style.backgroundColor+"";
		qmv_show_dialog("color",fcb,null,null,null,null,null,null,null,null,true);
	}
	else if (type=="fore_color_inline")
	{
		var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color_inline");
		fcb.value = fcb.style.backgroundColor+"";
		qmv_show_dialog("color",fcb,null,null,null,null,null,null,null,null,true);
	}
	else if (type=="back_color_revert")
	{
		
		var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_back_color_inline");
		fcb.style.backgroundColor = "";
		
		ze.style.backgroundColor = "";
		qmv_htmleditor_save_inline_setting_or_apply("backgroundColor","",is_panel);
	}
	else if (type=="fore_color_revert")
	{
		var fcb = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color_inline");
		fcb.style.backgroundColor = "";
		
		ze.style.color = "";
		qmv_htmleditor_save_inline_setting_or_apply("color","",is_panel);
	}
	else if (type=="sync")
	{
		qmv_htmleditor_sync_from_visual_design(e,is_panel)
	}
	else if (type=="remove-format")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
			qd.document.execCommand("removeFormat",null,null);
	}
	else if (type=="font-size-up")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
		{
			if (!all_selected)
				qd.document.execCommand("increaseFontSize",null,null);
			else
				qmv_htmleditor_style_all(ze,null,null,null,"BIG");
				
			qmv_htmleditor_set_design_window_height(is_panel);	
		}
	}
	else if (type=="font-size-down")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
		{
			if (!all_selected)
				qd.document.execCommand("decreaseFontSize",null,null);
			else
				qmv_htmleditor_style_all(ze,null,null,null,"SMALL");
				
			qmv_htmleditor_set_design_window_height(is_panel);	
		}
		
	}
	else if (type=="font-size")
	{
		if (sel.isCollapsed)
			qmv_show_dialog("alert",null,"You must first select some content in the item edit area.",420);
		else
			qmv_show_context(e,"htmleditor-font-size",document.getElementById("qmvi_"+pfix+"df_htmledit_design"));
		
	}
	else if (type=="selected_image")
	{
		
		if (is_panel)
			qmv_show_dialog("item_insert_image_from_panel")
		else
			qmv_show_dialog("item_insert_image_from_dialog")
		
	}
	else if (type=="test")
	{
		//qd.document.execCommand("incre",null,"#f00");
	}
	
	
	qmv_htmleditor_sync_code_view(e,is_panel,false,false,true);

}


function qmv_htmleditor_button_selected_image_handle(img)
{

	var qd = document.getElementById("qmvi_df_htmledit_design").contentWindow;
	var ze = qd.document.getElementById("z_edit_item");
	var sel = qd.getSelection();	
	
		
	
	if (img)
	{
		try 
		{	
			if (sel.anchorNode)
				qd.document.execCommand("insertImage",null,img);
			else
				ze.innerHTML = '<img src="'+img+'">'+ze.innerHTML;	
		}
		catch(e)
		{
			
			ze.innerHTML = '<img src="'+img+'">'+ze.innerHTML;
		}
		
		if ((ze.innerHTML+"").toLowerCase().indexOf("<img")==-1)
				ze.innerHTML = '<img src="'+img+'">'+ze.innerHTML;
		
		
		//update on time to avoid some quirky behavior
		setTimeout("qmv_htmleditor_sync_code_view(new Object(),true,false,false,true)",10);

	}
	
}



function qmv_htmleditor_apply_font_size_to_selection(size,is_panel)
{
	var pfix = "";
	if (!is_panel) pfix = "dlg_";
	
	var qd = document.getElementById("qmvi_"+pfix+"df_htmledit_design").contentWindow;
	var ze = qd.document.getElementById("z_"+pfix+"edit_item");
	
	var sel = qd.getSelection();
	var tsel = qmv_util_get_selection_text_start_end(ze,sel);
	var all_selected = (tsel.start&&tsel.end);
	
	if (!all_selected)
		qd.document.execCommand("fontSize",null,size);
	else
		qmv_htmleditor_style_all(ze,null,null,null,"FONT",'size="'+size+'"')
		
	qmv_htmleditor_sync_code_view(new Object(),is_panel,false,false,true);

	qmv_htmleditor_set_design_window_height(is_panel);
}


function qmv_htmleditor_set_button_color(hval,bdiv)
{
	var is_panel = true;
	if (bdiv.id && bdiv.id.indexOf("_dlg_")+1) is_panel = false;
		
	bdiv.style.backgroundColor = hval;
	var type = bdiv.getAttribute("qmvibtype");
	if (type)
		qmv_htmleditor_do_color_change(type,is_panel);
	
}

function qmv_htmleditor_do_color_change(type,is_panel)
{
	
	
	var pfix = "";
	if (!is_panel) pfix = "dlg_";
	
	var qd = document.getElementById("qmvi_"+pfix+"df_htmledit_design");
		
	if (qd)
	{
		qd = qd.contentWindow;
		var ze = qd.document.getElementById("z_"+pfix+"edit_item");
		
		var sel = qd.getSelection();
		var tsel = qmv_util_get_selection_text_start_end(ze,sel);
		var all_selected = (tsel.start&&tsel.end);
		
		if (type=="fore_color")
		{
			
			var cdiv = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color");
			var color = cdiv.style.backgroundColor;
			if (color)
			{
				
				if (!all_selected)
					qd.document.execCommand("foreColor",null,color);
				else
					qmv_htmleditor_style_all(ze,"color","color",color)	
				
				qmv_htmleditor_sync_code_view(new Object(),is_panel,false,false,true);
				qmv_persistent_save_setting("htmledit_forecolor",color);
			}
		}
		else if (type=="back_color_inline")
		{
			var cdiv = document.getElementById("qmvi_"+pfix+"htmledit_button_back_color_inline");
			var color = cdiv.style.backgroundColor;
			
			ze.style.backgroundColor = color;
			qmv_htmleditor_save_inline_setting_or_apply("backgroundColor",color,is_panel);
			
		}
		else if (type=="fore_color_inline")
		{
			var cdiv = document.getElementById("qmvi_"+pfix+"htmledit_button_fore_color_inline");
			var color = cdiv.style.backgroundColor;
			
			ze.style.color = color;
			qmv_htmleditor_save_inline_setting_or_apply("color",color,is_panel);
		}
		
	}
}


function qmv_htmledit_save_codeview(is_panel)
{
	qmv_htmleditor_handle_ok("apply",document.getElementById("qmv_edittext_field"),is_panel);
}

function qmv_htmledit_save(is_panel)
{

	qmv_htmleditor_sync_code_view(new Object(),is_panel);
	qmv_htmleditor_handle_ok("apply",document.getElementById("qmv_edittext_field"),is_panel);
	
}


function qmv_htmleditor_handle_ok(type,owner,is_panel,skip_report_log,from_visual_edit,skip_addons)
{
	
	var pfix = "dlg_";
	if (is_panel) pfix = "";
	
	val = document.getElementById("qmvi_"+pfix+"df_htmledit_code").value;
	val = val.replace(/\n/g,"");

	if (type=="ok" || type=="apply")
	{
		var skip_bot_panel_update = false;
		if (from_visual_edit)
			skip_bot_panel_update = true;
			
		qmv_tree_set_value(owner,val);
		//a,fromspin,skip_validate,skip_update,skip_inherit,is_quickcolor,skip_filter_update,skip_mirror,is_undo,skip_update_addons,
		var bad_val = qmv_evt_update_tree_value(owner,false,false,false,false,false,false,false,false,skip_addons,false,skip_report_log,skip_bot_panel_update);
				
		if (!is_panel)
			qmv_htmleditor_apply_inline_setting();
				
		if (!bad_val)
			return true;
	}
}


