function qmv_imgdialog_gradient_context_show_bar_handle(e,type)
{

	if (type=="color" || type=="opacity")
		qmv_imgdialog_gstop_add({clientX:qmv.gradient.temp_x},type);
	else if (type=="apply")
		qmv_imgdialog_gradient_apply_gradient_value(qmv.gradient.qmd,true);
	else if (type=="remove")
		qmv_imgdialog_gradient_apply(qmv.gradient.qmd,'remove');
	else if (type=="save")
		qmv_imgdialog_gradient_presets_save();
	
}


