function qmv_imgdialog_gradient_import()
{
	qmv_show_dialog("import_gradient",null,null,null,null,null,null,null,null,null,null,true);

}


function qmv_imgdialog_gradient_import_code()
{
	var a = document.getElementById("qmvi_df_import_gradient");
	if (a)
	{
		var gv = a.value;
		if (gv)
		{
		
			gv = gv.replace(/.*?gradient\(/g,qmv.css_prefix+"linear-gradient(");
			
			var c;
			if (qmv.css_prefix=="-moz-")
				c = gv.match(/\-moz\-linear\-gradient/g);
			else if (qmv.css_prefix=="-webkit-")
				c = gv.match(/\-webkit\-linear\-gradient/g);
			else
				c = gv.match(/linear\-gradient/g);
				
			if (c && gv.match(/\)/))
			{
			
				gv = gv.replace(/\;/g,'');
				gv = gv.replace(/\/\*.*?\*\//g,'');
				gv = gv.replace(/background\-image\:/g,'');
				gv = gv.replace(/background\:/g,'');
				
				if (c.length>1 || c.length==0)
				{
					if (c.length>1)
						qmv_show_dialog("alert",null,"Multiple values found, only include a single gradient value.",300);
					else
						qmv_show_dialog("alert",null,"The gradient cannot be imported, please check your syntax.",300);
				}
				else
				{
				
					qmv.gradient.value = gv;
					qmv_imgdialog_init2();
					
					if (qmv.gradient.inp_auto_sync.checked)
						qmv_imgdialog_gradient_apply_gradient_value(qmv.gradient.qmd,true);
						
					return true;
				}
			
			}
			else
				qmv_show_dialog("alert",null,"The gradient cannot be imported, please check your syntax.",300);
			
		}
		else
			qmv_show_dialog("alert",null,"There is no CSS code entered to import!",300);
	
	}
	return false;
}


function qmv_math_pointOfAngle(a) 
{
    return {x:Math.cos(a),y:Math.sin(a)};
}


function qmv_math_degreesToRadians(d) 
{
    return ((d * Math.PI) / 180);
}


function qmv_gradient_get_svg_points_from_angle(a)
{
	var eps = Math.pow(2, -52);
	var angle = (a % 360);
	
	var startPoint = qmv_math_pointOfAngle(qmv_math_degreesToRadians(180 - angle));
	var endPoint = qmv_math_pointOfAngle(qmv_math_degreesToRadians(360 - angle));
	
	if( startPoint.x <= 0 || Math.abs(startPoint.x) <= eps)
		startPoint.x = 0;

	if (startPoint.y <= 0 || Math.abs(startPoint.y) <= eps)
		startPoint.y = 0;

	if (endPoint.x <= 0 || Math.abs(endPoint.x) <= eps)
		endPoint.x = 0;

	if (endPoint.y <= 0 || Math.abs(endPoint.y) <= eps)
		endPoint.y = 0;

	
	var x1 = parseInt(startPoint.x*100);
	var x2 = parseInt(endPoint.x*100);
	var y1 = parseInt(startPoint.y*100);
	var y2 = parseInt(endPoint.y*100);
	
	var oa = [x1,x2,y1,y2];
	var na = [x1,x2,y1,y2];
	na.sort(function(a,b){return a-b});
	
	var d=0;
	for (var i=0;i<4;i++)
	{
		if (oa[i]==na[3])
		{
			d = 100-oa[i];
			oa[i]=100;
			
		}
	}
	
	for (var i=0;i<4;i++)
	{
		if (oa[i]==na[2])
		{
			oa[i]+=d;
		}
	}
		
	return 'x1="'+oa[0]+'%" y1="'+oa[2]+'%" x2="'+oa[1]+'%" y2="'+oa[3]+'%"';
}


function qmv_imgdialog_gradient_get_cross_browser_css(a,tabs,sname,format)
{
	var wt = '';
			
	//create SVG IE9 compatible gradient variant
	var glow=a.substring(a.indexOf("linear-gradient"));
	glow = glow.replace("center ","");
	var pg = qmv_parse_gradient(glow);			
	var dv = 0;
	if (pg.type=="deg")
		dv = (pg.type_value % 360);
	else if (pg.type=="top")
		dv = "-90";
	else if (pg.type=="right")
		dv = "180";
	else if (pg.type=="bottom")
		dv = 90;
	
	var points = qmv_gradient_get_svg_points_from_angle(dv);
		
	var ie8_start = '';
	var ie8_end = '';
	var ie8_type = 1;
	if ((dv<-45 && dv>-135) || (dv>45 && dv<135))
		ie8_type = 0;
		
	var svg = '<?xml version="1.0" ?>';
	svg += '<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 1 1" preserveAspectRatio="none">';		
		
		svg += '<linearGradient id="nf-grad-gen" gradientUnits="userSpaceOnUse" '+points+'>';
			
			for (var k=0;k<pg.stops.length;k++)
			{
				if (k==0)
					ie8_start = qmv_colors.toHex(pg.stops[k].color);
				else if (k==pg.stops.length-1)
					ie8_end = qmv_colors.toHex(pg.stops[k].color);
				
				var cc = pg.stops[k].color;
				if (pg.stops[k].colorType!="hex")
					cc = qmv_color_parse_split(cc,true);
				
				svg += '<stop offset="'+pg.stops[k].distance+'" stop-color="'+cc+'" stop-opacity="'+pg.stops[k].opacity+'"/>';
			}
			
		svg += '</linearGradient>';
		svg += '<rect x="0" y="0" width="1" height="1" fill="url(#nf-grad-gen)" />';
	svg += '</svg>';
	var b64 = btoa(svg);
	//reverse with atob()
	
	var nl_after_sname = "";
	var nl_before_sname = "";
	if (format=="css_view")
	{
		nl_before_sname = '\r\n\r\n';
		nl_after_sname = '';
	
	}
		
	//add the ie9 svg variant
	if (format=="css_view") wt += '/*IE9 SVG*/ ';
	wt += tabs+sname+":"+nl_after_sname+"url(data:image/svg+xml;base64,"+b64+");";
	
	//firefox / mozilla
	wt += nl_before_sname;
	if (format=="css_view") wt += '/*Mozilla Firefox*/ ';
	wt += sname+":"+nl_after_sname+"-moz-"+glow+";"
	
	//webkit
	wt += nl_before_sname;
	if (format=="css_view") wt += '/*Safari - Chrome*/ ';
	wt += sname+":"+nl_after_sname+"-webkit-"+glow+";"
	
	//ie 10+
	wt += nl_before_sname;
	if (format=="css_view") wt += '/*IE 10+*/ ';
	wt += sname+":"+nl_after_sname+"-ms-"+glow+";"
	
	//opera
	wt += nl_before_sname;
	if (format=="css_view") wt += '/*Opera*/ ';
	wt += sname+":"+nl_after_sname+"-o-"+glow+";"
	
	//w3c
	wt += nl_before_sname;
	if (format=="css_view") wt += '/*W3C*/ ';
	wt += sname+":"+nl_after_sname+glow+";"
	
	//ie8 Down
	if ((qmv.persist_settings.gradient_ie8+'')=="true")
	{
		wt += nl_before_sname;
		if (format=="css_view") wt += '/*IE6-8 (horz. or vert. only)*/ ';
		wt += "filter:progid:DXImageTransform.Microsoft.gradient(startColorstr='"+ie8_start+"', endColorstr='"+ie8_end+"',GradientType="+ie8_type+");"
	}
		
	return wt;
}


function qmv_imgdialog_select_divstop(elm,index)
{

	var s = qmv.gradient;
	var g = s.gro;
	var opacity_c = s.stops_opacity_container;
	var color_c = s.stops_color_container;
	var opac_ch = opacity_c.children;
	var color_ch = color_c.children;
	
	if (elm)
	{
		s.sel_stop = qmv_imgdialog_get_sel_stop_from_div(elm);
		s.sel_div = elm;
	}
	else if (typeof index=="number")
	{
		if (g.stops.length) 
		{
			s.sel_stop = g.stops[0];
			s.sel_div = qmv_imgdialog_get_div_stop_from_sel(s.sel_stop);
		}
	}
	
	if (s.sel_div)
		s.sel_type = s.sel_div.getAttribute("stype");
	
	//remove the previous selection styles
	if (s.sel_pdiv)
	{
		s.sel_pdiv.style.borderColor = "#999";
		s.sel_pdiv.style.zIndex = '';
		if (s.sel_pdiv.getAttribute("stype")=="opacity")
			s.sel_pdiv.children[0].style.backgroundImage = 'url('+qmv.base+'images/grad_stop_arrow_down.png)';
		else
			s.sel_pdiv.children[0].style.backgroundImage = 'url('+qmv.base+'images/grad_stop_arrow_up.png)';
		
	}
	
	//apply the selection styles and values
	s.sel_div.style.borderColor = "#000";
	s.sel_div.style.zIndex = 1;
	var sv = s.sel_div.getAttribute("svalue",2);
	if (s.sel_type=="opacity")
	{
		s.sel_div.children[0].style.backgroundImage = 'url('+qmv.base+'images/grad_stop_arrow_down_sel.png)';
		s.inp_opacity.value = sv;
		s.lsel_opacity = sv;
		qmv_dialog_edge_part_slider_update_from_input(document.getElementById("qmvi_df_edge_stopopacity"),'stopopacity');
		
		s.inp_opacity_container.style.visibility = "inherit";
		s.inp_color_container.style.visibility = "hidden";
		
		
		if (opac_ch.length<=2)
			s.button_delete.disabled = true;
		else
			s.button_delete.disabled = false;
	}
	else
	{
		s.sel_div.children[0].style.backgroundImage = 'url('+qmv.base+'images/grad_stop_arrow_up_sel.png)';
		s.inp_color.value = sv;
		s.lsel_color = sv;
		qmvi_set_dialog_color(sv,document.getElementById("qmvi_df_edge_button_stopcolor"));
		
		s.inp_opacity_container.style.visibility = "hidden";
		s.inp_color_container.style.visibility = "inherit";
		
		if (color_ch.length<=2)
			s.button_delete.disabled = true;
		else
			s.button_delete.disabled = false;
	}
	
	
	s.inp_pos.value = s.sel_stop.distance;
	s.sel_pdiv = s.sel_div;
	
}


function qmv_imgdialog_get_sel_stop_from_div(a)
{
	var dist = a.getAttribute("sdist");
	var st = qmv.gradient.gro.stops;
	
	for (var i=0;i<st.length;i++)
	{
		if (st[i].distance==dist)
		{
			return st[i];
		}
	}
}


function qmv_imgdialog_get_div_stop_from_sel(st)
{

	var opacity_c = qmv.gradient.stops_opacity_container;
	var color_c = qmv.gradient.stops_color_container;
	var opac_ch = opacity_c.children;
	var color_ch = color_c.children;
	
	//check for opacity stop match
	for (var i=0;i<opac_ch.length;i++)
	{
		if (opac_ch[i].getAttribute("sdist")==st.distance)
		{
			return opac_ch[i];
		}
	}
	
	//check for color stop match
	for (var i=0;i<color_ch.length;i++)
	{
		if (color_ch[i].getAttribute("sdist")==st.distance)
		{
			return color_ch[i];	
		}
	}

}

function qmv_imgdialog_apply_bar_preview_gradients()
{
	var g = qmv.gradient.gro;
	var bar = qmv.gradient.gradient_bar;
	var prev = qmv.gradient.gradient_preview;
	
	//set the gradient on the stop bar
	var barg = qmv.gradient.value.replace(/\(.+?rgb/,"(left, rgb");
	bar.style.backgroundImage = barg;
	
	//set the gradient on the preview box
	if (qmv.gradient.ie8_preview.checked)
		prev.style.backgroundImage = qmv_imgdialog_set_gradient_css_from_stops(false,true);
	else
		prev.style.backgroundImage = qmv.gradient.value;

}


function qmv_imgdialog_init_gradient()
{

	var g = qmv.gradient.gro;
	var bar = qmv.gradient.gradient_bar;
	
	qmv_imgdialog_apply_bar_preview_gradients();
	
	//************initialize all stops based on the stops object*******************
	//Apply the stops -2 accounts for border
	var gstep = qmv.gradient.gstep =(bar.offsetWidth-1)/100;
	var ihc = '';
	var iho = '';
	var a_part = 'font-size:1px;width:11px;height:11px;';
	var b_part = 'border-width:1px;border-style:solid;border-color:#999;box-shadow:1px 1px 3px #999;';
	var c_part = 'onclick="qmv_imgdialog_gstop_handle_mouseclick(event)" onmousedown="qmv_imgdialog_gstop_handle_mousedown(event,this)" onmousemove="qmv_imgdialog_gstop_handle_mousemove(event,this)" onmouseup="qmv_imgdialog_gstop_handle_mouseup(event,this)"';
	
	for (var i=0;i<g.stops.length;i++)
	{
		var xpos = parseInt(g.stops[i].distance)*gstep;
		var stype = g.stops[i].type
		var d_part = 'sdist="'+g.stops[i].distance+'"';
		
		if (stype=='opacity' || stype=='dual')
		{
			iho += '<div stype="opacity" svalue="'+parseInt(g.stops[i].opacity*100)+'%" '+c_part+' '+d_part+' title="Opacity Stop Value: '+g.stops[i].opacity+'" oncontextmenu="qmv_imgdialog_gradient_context_show_opacitystop(event,this)" style="cursor:default;position:absolute;margin-left:-5px;background-color:#fff;left:'+xpos+'px;'+a_part+b_part+'">';
				iho += '<div style="font-size:1px;position:absolute;top:12px;width:11px;height:6px;background-image:url('+qmv.base+'images/grad_stop_arrow_down.png);"></div>';
				iho += '<div style="font-size:1px;width:9px;height:9px;border:1px outset #fff;background-color:#fff;background-image:url('+qmv.base+'images/stripe_bg.png);background-position:0px 0px;">';
					iho += '<div style="font-size:1px;width:9px;height:9px;background-color:#000;opacity:'+g.stops[i].opacity+';"></div>'
				iho += '</div>';
			iho += '</div>';
		}
		
		if (stype=='color' || stype=='dual')
		{
			ihc += '<div stype="color" svalue="'+g.stops[i].stop_color+'" '+c_part+' '+d_part+' title="Color Stop Value: '+g.stops[i].stop_color+'" oncontextmenu="qmv_imgdialog_gradient_context_show_colorstop(event,this)" ondblclick="qmv_imgdialog_gstop_color_handle_dblclick(event,this)" style="cursor:default;position:absolute;margin-left:-5px;background-color:'+g.stops[i].stop_color+';top:8px;left:'+xpos+'px;'+a_part+b_part+'">';
				ihc += '<div style="font-size:1px;position:absolute;top:-7px;width:11px;height:6px;background-image:url('+qmv.base+'images/grad_stop_arrow_up.png);"></div>';
				ihc += '<div style="font-size:1px;width:9px;height:9px;border:1px outset #fff;background-color:'+g.stops[i].stop_color+';"></div>'
			ihc += '</div>';
		}
	
	}
	
	
	var opacity_c = qmv.gradient.stops_opacity_container;
	var color_c = qmv.gradient.stops_color_container;
	opacity_c.gstep = gstep;
	color_c.gstep = gstep;
	opacity_c.innerHTML = iho;
	color_c.innerHTML = ihc;

}


function qmv_imgdialog_gstop_color_handle_dblclick(e,a)
{

	var co = document.getElementById("qmvi_df_edge_button_stopcolor");
	if (co) qmv_show_dialog_color_picker({},co);

}


function qmv_imgdialog_gstop_delete(e)
{

	var g = qmv.gradient
	var opacity_c = qmv.gradient.stops_opacity_container;
	var color_c = qmv.gradient.stops_color_container;
	var type = g.sel_div.getAttribute("stype");
	
	var pc = opacity_c;
	if (type=="color") pc = color_c;
	
	pc.removeChild(g.sel_div);
	
	qmv.gradient.gro.stops = qmv_imgdialog_get_stops_from_divstops();
	qmv_imgdialog_set_gradient_css_from_stops();
	qmv_imgdialog_apply_bar_preview_gradients();
	qmv_imgdialog_select_divstop(null,1);

}


function qmv_imgdialog_gstop_add(e,type)
{
	e = e||event;
	var opacity_c = qmv.gradient.stops_opacity_container;
	var color_c = qmv.gradient.stops_color_container;
	
	var nn;
	if (type=="color")
	{
		var ncolor = (qmv.gradient.lsel_color?qmv.gradient.lsel_color:"rgb(0,0,0)");
		nn=color_c.children[0].cloneNode(true);
		nn.children[1].style.backgroundColor = ncolor;
		nn.setAttribute("svalue",ncolor);
		nn.setAttribute("title","Color Stop Value: "+ncolor);
		
		color_c.appendChild(nn);
	}
	else
	{
		var nopac = ((qmv.gradient.lsel_opacity&&qmv.gradient.lsel_opacity!='100%')?qmv.gradient.lsel_opacity:"50%");
		nn=opacity_c.children[0].cloneNode(true);
		nn.children[1].children[0].style.opacity = parseInt(nopac)/100;
		nn.setAttribute("svalue",nopac);
		nn.setAttribute("title","Opacity Stop Value: "+nopac);
		
		opacity_c.appendChild(nn);
	
	}
	
	var xpos = e.clientX-qmv_get_offset(color_c)[0]-2;
	if (xpos<0) xpos=0;
	if (xpos>(100*color_c.gstep)) xpos = 100*color_c.gstep;
	nn.style.left = (xpos)+"px";
	nn.setAttribute("sdist",parseInt(xpos/color_c.gstep)+"%");
	
	
	qmv.gradient.gro.stops = qmv_imgdialog_get_stops_from_divstops();
	qmv_imgdialog_set_gradient_css_from_stops();
	qmv_imgdialog_apply_bar_preview_gradients();
	qmv_imgdialog_select_divstop(nn);

}


function qmv_imgdialog_update_divstop_from_inputs(type,skip_pos)
{
	
	var s = qmv.gradient;
	var st = s.sel_stop;
	var sdiv = s.sel_div;
	
	if (type=="inp_pos")
	{
		sdiv.setAttribute("sdist",s.inp_pos.value);
		if (!skip_pos)
			sdiv.style.left = (parseInt(s.inp_pos.value)*s.gstep)+"px";
		
	}
	else if (type=="inp_opacity")
	{
		sdiv.setAttribute("svalue",s.inp_opacity.value);
		s.lsel_opacity = s.inp_opacity.value;
		sdiv.setAttribute("title","Opacity Stop Value: "+s.inp_opacity.value);
		sdiv.children[1].children[0].style.opacity = parseInt(s.inp_opacity.value)/100;
	}
	else if (type=="inp_color")
	{
		var tcolor = qmv_colors.toRgb(s.inp_color.value);
		if (tcolor)	
		{
			sdiv.setAttribute("svalue",s.inp_color.value);
			s.lsel_color = s.inp_color.value;
			sdiv.setAttribute("title","Color Stop Value: "+s.inp_color.value);
			sdiv.children[1].style.backgroundColor = s.inp_color.value;
		}
	}

	qmv.gradient.gro.stops = qmv_imgdialog_get_stops_from_divstops();
	qmv_imgdialog_set_gradient_css_from_stops();
	qmv_imgdialog_apply_bar_preview_gradients();
	
	qmv.gradient_edited = true;
		
}


function qmv_imgdialog_set_gradient_css_from_stops(skip_sync,get_ie8)
{
	var g = qmv.gradient.gro;
	var stops = g.stops;
	
	var ty = g.type_pub;
	
	if (get_ie8)
	{
		var dv = g.type_value;
		if (!dv)
		{
			if (g.type=="bottom")
				ty="top";
			else if (g.type=="right")
				ty="left";
		}
		
		ty = "left";
		if ((dv<-45 && dv>-135) || (dv>45 && dv<135))
			ty = "top";
		
	}
	
	ih = qmv.css_prefix+'linear-gradient('+ty+',';
	for (var i=0;i<stops.length;i++)
	{
		if (get_ie8 && (i!=0 && i!=stops.length-1))
			continue;
			
		var ca = stops[i].color.match(/\d+/g);
		var op = (get_ie8?1:stops[i].opacity);
		var crgba = "rgba("+ca[0]+","+ca[1]+","+ca[2]+","+op+")";
		
		var st = stops[i].distance;
		if (get_ie8)
		{
			if (i==0) 
				st="0%";
			else
				st="100%";
		}
		
		ih += crgba+" "+st;
		if (i<stops.length-1)
			ih += ",";
	}
	ih += ")";
	
	if (get_ie8)
		return ih;
	
	qmv.gradient.value = ih;
	
	if (!skip_sync && qmv.gradient.inp_auto_sync.checked)
		qmv_imgdialog_gradient_apply_gradient_value(qmv.gradient.qmd,true);
	
}


function qmv_imgdialog_get_stops_from_divstops()
{

	var stops = [];
	var ns = {};
	
	var opac_ch = qmv.gradient.stops_opacity_container.children;
	var color_ch = qmv.gradient.stops_color_container.children;
	for (var i=0;i<opac_ch.length;i++)
	{
		var d = parseInt(opac_ch[i].getAttribute("sdist"));
		ns['o'+d]=opac_ch[i];
	}
	for (var i=0;i<color_ch.length;i++)
	{
		var d = parseInt(color_ch[i].getAttribute("sdist"));
		ns['c'+d]=color_ch[i];
	}
	
	//create the stops and set the known values
	for (var i=0;i<=100;i++)
	{
		var sto = ns['o'+i];
		var stc = ns['c'+i];

		
		if (sto || stc)
		{
			var s = {};
			s.distance = i+"%";
			
			if (sto && stc)
				s.type="dual";
			else if (sto)
				s.type="opacity";
			else
				s.type="color";
				
			if (sto)
				s.opacity = parseInt(sto.getAttribute("svalue",2))/100;
			else
				s.opacity = 1;
			
			if (stc)
			{
				var tcolor = qmv_colors.toRgb(stc.getAttribute("svalue",2));
				if (tcolor)
				{
					tcolor = tcolor.replace("rgb","rgba");
					tcolor = tcolor.replace(")",","+(s.opacity)+")");
					s.color = tcolor;
				}
			}
			else
				s.color = "rgba(0,0,0,1)";
			
			stops.push(s);
		}
	}
	
	//calculate the opacity for color stops and color for opacity stops
	for (var i=0;i<stops.length;i++)
	{
		if (stops[i].type!="dual")
		{
			
			var cur_dist = parseInt(stops[i].distance);
			var cur_rgb = stops[i].color.match(/\d+/g);
			var cur_opac = stops[i].opacity;
			
			var mname = "opacity";
			if (stops[i].type=="opacity") mname="color";
			
			//find and set the start opacity or color stop values
			var si=null;
			for (var j=i-1;j>=0;j--)
			{
				if (stops[j].type==mname || stops[j].type=="dual")
				{
					si = j;
					break;
				}
			}
			
			var t_s = ((typeof si=="number")?stops[si]:{none:true,distance:0,color:stops[i].color,opacity:stops[i].opacity});
			var start_dist = parseInt(t_s.distance);
			var start_rgb = t_s.color.match(/\d+/g);
			var start_opac = t_s.opacity;
			
			//find and set the next opacity or color stop values for
			si=null;
			for (var j=i+1;j<stops.length;j++)
			{
				if (stops[j].type==mname || stops[j].type=="dual")
				{
					si = j;
					break;
				}
			}
		
			var t_e = ((typeof si=="number")?stops[si]:{none:true,distance:100,color:stops[i].color,opacity:stops[i].opacity});
			var end_dist = parseInt(t_e.distance);
			var end_rgb = t_e.color.match(/\d+/g);
			var end_opac = t_e.opacity;
			
			if (t_e.none)
			{
				end_rgb = t_s.color.match(/\d+/g);
				end_opac = t_s.opacity;
			}
			
			if (t_s.none)
			{
				start_rgb = t_e.color.match(/\d+/g);
				start_opac = t_e.opacity;
			}
			
			var dr = (cur_dist-start_dist)/(end_dist-start_dist);
			
			
			if (stops[i].type=="color")
			{
				stops[i].opacity = (start_opac-(dr*(start_opac-end_opac))).toFixed(2);
				//alert(i+": "+start_opac+"-"+end_opac+"  =  "+stops[i].opacity);
			}
			else
			{
				var nrgb = [];
				for (var k=0;k<3;k++)
					nrgb.push(Math.round(start_rgb[k]-(dr*(start_rgb[k]-end_rgb[k]))));
				
				stops[i].color = "rgba("+nrgb[0]+","+nrgb[1]+","+nrgb[2]+","+cur_opac+")";
				
				
			}
		
		}
		
		
		
	}
	
	
	return stops;

	
}


String.prototype.padZero = function(len, c)
{
    var s= this, c= c || "0", len= len || 2;
    while(s.length < len) s= c + s;
    return s;
}

var qmv_colors={
    colornames:{
        aqua: '#00ffff', black: '#000000', blue: '#0000ff', fuchsia: '#ff00ff',
        gray: '#808080', green: '#008000', lime: '#00ff00', maroon: '#800000',
        navy: '#000080', olive: '#808000', purple: '#800080', red: '#ff0000',
        silver: '#c0c0c0', teal: '#008080', white: '#ffffff', yellow: '#ffff00'
    },
    toRgb: function(c){
        c= '0x'+qmv_colors.toHex(c).substring(1);
        c= [(c>> 16)&255, (c>> 8)&255, c&255];
        return 'rgb('+c.join(',')+')';
    },
    toHex: function(c){
        var tem, i= 0, c= c? c.toString().toLowerCase(): '';
        if(/^#[a-f0-9]{3,6}$/.test(c)){
            if(c.length< 7){
                var A= c.split('');
                c= A[0]+A[1]+A[1]+A[2]+A[2]+A[3]+A[3];
            }
            return c;
        }
        if(/^[a-z]+$/.test(c)){
            return qmv_colors.colornames[c] || '';
        }
        c= c.match(/\d+(\.\d+)?%?/g) || [];
        if(c.length<3) return '';
        c= c.slice(0, 3);
        while(i< 3){
            tem= c[i];
            if(tem.indexOf('%')!= -1){
                tem= Math.round(parseFloat(tem)*2.55);
            }
            else tem= parseInt(tem);
            if(tem< 0 || tem> 255) c.length= 0;
            else c[i++]= tem.toString(16).padZero(2);
        }
        if(c.length== 3) return '#'+c.join('').toLowerCase();
        return '';
    }
}


