function qmv_util_pubgen_convert_object_to_json_string(params)
{
	var rt = "";
	var go = false;
	
	for (var i in params)
	{
		go = true;
		if (typeof params[i]=="number" || typeof params[i]=="boolean")
			rt += i+":"+params[i];
		else if (typeof params[i]=="string")
			rt += i+":"+"'"+params[i]+"'";
		else if (params[i] && params[i].NFisArray)
		{
			var st = "";
			for (var j=0;j<params[i].length;j++)
			{
				if (params[i][j])
					st+="'"+params[i][j]+"',";
			}
			
			if (st.lastIndexOf(",")==st.length-1)
				st = st.substring(0,st.length-1);

			rt += i+":["+st+"]";
			
		}
		else
			go = false;
			
		if (go) rt += ",";
	}
	
	if (rt.lastIndexOf(",")==rt.length-1)
		rt = rt.substring(0,rt.length-1);
	
	return "{"+rt+"}";
}


function qmv_util_get_selection_text_start_end(el,sel) 
{

	//tells weather the selection is at the start and end of the parent element

    var atStart = false, atEnd = false;
    var selRange, testRange;

	if (sel.rangeCount) 
	{
		selRange = sel.getRangeAt(0);
		testRange = selRange.cloneRange();

		testRange.selectNodeContents(el);
		testRange.setEnd(selRange.startContainer, selRange.startOffset);
		atStart = (testRange.toString() == "");

		testRange.selectNodeContents(el);
		testRange.setStart(selRange.endContainer, selRange.endOffset);
		atEnd = (testRange.toString() == "");
	}
	
    return {start:atStart, end:atEnd};
	
}


