			var tfobj = new Object();
			tfobj.scaleX = document.getElementById("qmvi_df_edge_scalex").value;
			tfobj.scaleY = document.getElementById("qmvi_df_edge_scaley").value;
			tfobj.skewX = document.getElementById("qmvi_df_edge_skewx").value;
			tfobj.skewY = document.getElementById("qmvi_df_edge_skewy").value;
			tfobj.translateX = document.getElementById("qmvi_df_edge_translatex").value;
			tfobj.translateY = document.getElementById("qmvi_df_edge_translatey").value;
			tfobj.rotate = document.getElementById("qmvi_df_edge_rotate").value;
			
			if (tfobj.scaleX && tfobj.scaleX==tfobj.scaleY)
			{
				tfobj.scale=tfobj.scaleX
				tfobj.scaleX=null;
				tfobj.scaleY=null;
			}
			
			
			var t = '';
			for (var i in tfobj)
			{
				if (tfobj[i])
					t += i+"("+tfobj[i]+") ";
			
			}
		
			if (t) t=t.substring(0,t.length-1);
		
			qmv_tree_set_value(qmd.owner,t);
			
