function qmv_insert_spanitem(type,a,skip_select,after,skip_update,skip_undo)
{
	
	var is_multi = false;
	
	if (!a) a = qmv.cur_item;
	var ai = a;
	
	var ns = document.createElement("SPAN");
	var nsi = ns;
	
	if (a[qp] && a[qp].tagName=="DD" && a[qp][qp] && a[qp][qp].className.indexOf("qmmulti")+1)
	{
		is_multi = true;
		
		ai = a[qp];
		nsi = document.createElement("DD");
		ns = nsi.appendChild(ns);
		
	}
	
	
	if (type=="title")
	{
		if (!is_multi && qmv_is_container_horizontal(a[qp]))
		{
			qmv_show_dialog("alert",null,"Title items are typically templated for vertical menus, you may have to adjust the title styles to better match your horizontal layout.",500);			
			//return;
		}
		
		ns.className = "qmtitle";
		qmv_attach_title_events(ns);
		ns.innerHTML = "New Title";
	
		
		//if (qmv_is_container_horizontal(a[qp]))
			//ns.style.width = "200px";

		
		if (!after)
			ns = ai[qp].insertBefore(nsi,ai);
		else
			ns = qmv_lib_insert_after(nsi,ai);

		if (is_multi && ns && ns.firstChild) ns = ns.firstChild;	
		
		if (!skip_undo)
			qmvi_report_add_line("edits","undo","modify","add_insert","",ns);
		
		
		
		
	}
	if (type=="cbox")
	{
		

		//if (qmv_is_container_horizontal(a[qp]))
		//{

			//qmv_show_dialog("alert",null,"Content boxes can't be applied to horizontally oriented main menus. Choose a vertically oriented main or sub menu before inserting a new content box.",500);			
			//return;
		//}
		//dasf asdfasdfasdfdasfasdfeeeeeeeeeeeeeeeeeeeeeeee
		
		ns.className = "qmcbox";
		qmv_attach_cbox_events(ns);
		ns.innerHTML = "New Content Box";
	
		if (qmv_is_container_horizontal(a[qp]))
			ns.style.width = "150px";
		
		if (!after)
			ns = ai[qp].insertBefore(nsi,ai);
		else
			ns = qmv_lib_insert_after(nsi,ai);

		if (is_multi && ns && ns.firstChild) ns = ns.firstChild;
			
		if (!skip_undo)
			qmvi_report_add_line("edits","undo","modify","add_insert","",ns);
		

	}
	else if (type=="divider")
	{
		//asdfasdfasdfasd das asd fasd fasdfasdf sadfasdf
		
		if(!is_multi && qmv_is_container_horizontal(a[qp]) && !qmv.addons.tree_menu["on"+qmv.id])
		{

			/*
			var val = qmv_find_update_tree_value("individuals","#qm[i].qm-horizontal-c > .qmdivider","height",null,true,true);
			if (!val)
			{
				var update_inp = qmv_find_update_tree_value("individuals","#qm[i].qm-horizontal-c > .qmdivider","height",a.offsetHeight+"px",false,true);
				if (update_inp)
					qmv_evt_update_tree_value(update_inp);
			}

			var val = qmv_find_update_tree_value("individuals","#qm[i].qm-horizontal-c > .qmdivider","borderLeftWidth",null,true,true);
			if (!val)
			{
				var update_inp = qmv_find_update_tree_value("individuals","#qm[i].qm-horizontal-c > .qmdivider","borderLeftWidth","1px",false,true);
				if (update_inp)
					qmv_evt_update_tree_value(update_inp);
			}
			*/

			ns.className = "qmdivider qmdividery"
		}
		else
		{
			
			/*
			var val = qmv_find_update_tree_value("individuals","#qm[i] > .qmdivider","borderTopWidth",null,true,true);
			if (!val)
			{
				var update_inp = qmv_find_update_tree_value("individuals","#qm[i] > .qmdivider","borderTopWidth","1px",false,true);
				if (update_inp)
					qmv_evt_update_tree_value(update_inp);
			}	
			*/

			ns.className = "qmdivider qmdividerx"
		}

		qmv_attach_divider_events(ns);


		if (!after)
			ai[qp].insertBefore(nsi,ai);
		else
			qmv_lib_insert_after(nsi,ai);

		if (!skip_undo)
			qmvi_report_add_line("edits","undo","modify","add_insert","",ns);		
		

	}
	

	
	if (ns)
	{
		ns.qmmi = 1;
		ns.qmts = 0;
		ns.onmouseover = qmv_visual_design_menu_item_hover_handle;
		
	}	
	
	if (!skip_select)
		qm_oo(new Object(),ns,false);
	
	
	qm_sam_stretch(qmv.cur_sub);
	qmv_reselect_all_menu_items_from_root_for_big_update(true);
		
	
	if (!skip_update)
		qmv_update_all_addons();
	
	qmv_position_pointer();

	
}


function qmv_column_get_count(s)
{

	var c = 0;
	var ch = s.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		if (ch[i].tagName=="DL")
			c++;
	}

	return c;
	
}


function qmv_delete_column()
{

	var ci = qmv.cur_item;
	var pdiv = ci[qp];
	var new_cur;
	
	if (pdiv.tagName=="DD" && pdiv[qp] && pdiv[qp].className.indexOf("qmmulti")+1)
	{
		var mc = pdiv[qp];
		pdiv = pdiv[qp][qp];
		
		var c = 0;
		var ch = pdiv.childNodes;
		for (var i=0;i<ch.length;i++)
		{
			if (ch[i].tagName=="DL")
				c++;
		}
		
		if (c>1)
		{
			pdiv.removeChild(mc);
			for (var i=0;i<ch.length;i++)
			{
				if (ch[i].tagName=="DL")
				{
					var gnc = ch[i].getElementsByTagName("DD");
					if (gnc && gnc[0].firstChild)
					{
						new_cur = gnc[0].firstChild;
						break;
					}
				}
			}
			
			qmv_addinsert_renumber_columns(pdiv);
		
		}
		else
		{
			//convert the last column to a sub standard sub menu first
			var cc = mc.childNodes;
			for (var i=0;i<cc.length;i++)
			{
				if (cc[i].tagName=="DD")
				{
					if (cc[i].firstChild)
					{
						pdiv.appendChild(cc[i].removeChild(cc[i].firstChild));
						i--;
					}
				}
			}
			
			new_cur = qmv.cur_item;
			
			pdiv.removeChild(mc);
			pdiv.qmffsw = false;
			qmv_show_dialog("alert",null,"The last column has been removed.  Your items have been converted to standard sub menu items.",425);
			
		}
		
		
		if (new_cur)
			qm_oo(new Object(),new_cur,false);
				
		qm_sam_stretch(qmv.cur_sub);
		qmv_reselect_all_menu_items_from_root_for_big_update(true);
		
		qmv_update_all_addons();
		qmv_position_pointer();
		
		
	}
	else
		qmv_show_dialog("alert",null,"The selected item is not part of a column, first select a column item.",425);
	
	
}


function qmv_addinsert_column(type)
{

	
	
	var ci = qmv.cur_item;
	var pdiv = ci[qp];
	var is_multi = false;
	var new_cur;
	var curdl;
	
	
	if (pdiv.tagName=="DD" && pdiv[qp] && pdiv[qp].className.indexOf("qmmulti")+1)
	{
		is_multi=true;
		pdiv = pdiv[qp][qp];
		curdl = ci[qp][qp];
	}
	
	
	if (qm_a(pdiv))
	{
		qmv_show_dialog("alert",null,"Select a sub menu item before applying columns.",375);
		return;
	}
	else if (qmv.addons.tree_menu["on"+qmv.id])
	{
		qmv_show_dialog("alert",null,"Columns are not compatible with tree style menus. Switch to a standard drop down style menu to apply columns.",450);
		return;
	}
	else if (qmv.addons.scroll["on"+qmv.id])
	{
		qmv_show_dialog("alert",null,"Columns are not compatible with scroll style effects. Switch to a standard drop down style menu to apply columns.",450);
		return;
	}
	
	
	
	//convert existing menu itmes to multi
	if (!is_multi)
	{
				
		var nm = document.createElement("DL");
		nm.className = "qmmulti qmml0";
		if (pdiv.idiv)
			qm_arc("qmpmulti",pdiv.idiv,true);
		
				
		var ch = pdiv.childNodes;
		var lasta;
		
		
		for (var i=0;i<ch.length;i++)
		{
			if (ch[i].tagName=="A" || ((ch[i].tagName=="SPAN") && (ch[i].className.indexOf("qmtitle")+1 || ch[i].className.indexOf("qmdivider")+1 || ch[i].className.indexOf("qmcbox")+1)))
			{
				var ndd = document.createElement("DD");
				ndd.appendChild(pdiv.removeChild(ch[i]));
				lasta = nm.appendChild(ndd);
				i--;
			}
			else if (ch[i].tagName=="DIV")
			{
			
				lasta.appendChild(pdiv.removeChild(ch[i]));
				i--;
			}
			
		}
	
		curdl = pdiv.appendChild(nm);
		pdiv.qmffsw = 1;
		
		qmv_attach_column_container_events(curdl);
	}
	
		
	var ncontent = "single_item";
	if (type=="clone") ncontent = false;
	var nc = qmv_addinsert_get_new_column(ncontent);
	
	if (type=="clone")
	{
		var alldd = curdl.childNodes;
		for (var i=0;i<alldd.length;i++)
		{
			
			if (alldd[i].tagName=="DD")
			{
				var titem = nc.appendChild(alldd[i].cloneNode(true));
				
				//remove the sub if it exists
				var cchd;
				if ((cchd = alldd[i].getElementsByTagName("DIV")[0]) && cchd.idiv)
				{
					if ((cchd = titem.getElementsByTagName("DIV")[0]) && cchd[qp]==titem)
					{
						titem.removeChild(cchd);
						if (titem.firstChild && titem.firstChild.tagName=="A")
						{
							qm_arc("qmparent",titem.firstChild);
							qm_arc("qmactive",titem.firstChild);
						}
					}
				}
				
				var fc = titem.firstChild;
				if (fc)
				{
					
					a.cdiv = null;
					
					if (fc.className.indexOf("qmtitle")+1)
					{
						qmv_attach_title_events(fc);
					}
					else if (fc.className.indexOf("qmdivider")+1)
					{
						qmv_attach_divider_events(fc);
					}
					else if (fc.className.indexOf("qmcbox")+1)
					{
						qmv_attach_cbox_events(fc);
					}
					else
					{
						qm_modify_items_create_atag(fc,null,null,null);
						qmv_modify_add_item_atag_events(fc);
					}
					
					fc.qmmi=1;
					
				}
			}
		}
		
		nc.style.cssText = curdl.style.cssText;
	}	
	

	
	if (type=="insert" || type=="clone")
		pdiv.insertBefore(nc,curdl);
	else if (type=="add")
		pdiv.appendChild(nc);
	
	
	qmv_addinsert_renumber_columns(pdiv);
	new_cur = nc.firstChild.firstChild;
		
	if (nc && nc.tagName=="DL")
		qmv_attach_column_container_events(nc);
	
	
	if (new_cur)
		qm_oo(new Object(),new_cur,false);
	
	qm_sam_stretch(qmv.cur_sub);
	qmv_reselect_all_menu_items_from_root_for_big_update(true);
	qmv_update_all_addons();
	qmv_position_pointer();		
		
	qmv.changed = true;	
	
}

function qmv_addinsert_get_new_column(content)
{
	
	var nm = document.createElement("DL");
	nm.className = "qmmulti qmmlx";
	
	if (content=="single_item")
		nm.appendChild(qm_modify_items_create_atag(null,null,false,true));
	                
	
	return nm;
}


function qmv_addinsert_renumber_columns(pdiv)
{

	var rc = 0;
	var ch = pdiv.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		if (ch[i].tagName=="DL")
		{
			ch[i].className = ch[i].className.replace("qmmlx","qmml"+rc);
			for (var j=0;j<10;j++)
				ch[i].className = ch[i].className.replace("qmml"+j,"qmml"+rc);
						
			rc++;
		}
	}

}


function qmv_modify_items(type,inner,is_undo)
{
	
	
	var ci = qmv.cur_item;
	var cc = ci.parentNode;
	var is_multi = false;
	var mf = ci;
	
	
	if (cc.tagName=="DD" && cc[qp] && cc[qp].className.indexOf("qmmulti")+1)
	{
		is_multi=true;
		cc = cc[qp];
		mf = ci[qp];
	}
	
	var a,new_cur,skip_oo;
	
	if (type=="add" || type=="insert" || type=="insert-after")
	{

		
		a = qm_modify_items_create_atag(null,inner,false,is_multi);

		if (type=="add")
		{
			var lasta;
			var ch = cc.childNodes;
			for (var i=0;i<ch.length;i++)
			{
				if (ch[i].tagName=="A" || (is_multi && ch[i].tagName=="DD") || ((ch[i].tagName=="SPAN") && (ch[i].className.indexOf("qmtitle")+1 || ch[i].className.indexOf("qmdivider")+1 || ch[i].className.indexOf("qmcbox")+1)))
					lasta = ch[i];

			}
			
						
			if (lasta.cdiv) lasta = lasta.cdiv;
			qmv_lib_insert_after(a,lasta);
		}
		else if (type=="insert")
		{
			if (is_multi)
				cc.insertBefore(a,ci[qp]);
			else
				cc.insertBefore(a,ci);
					
		}
		else if (type=="insert-after")
		{
			if (is_multi)
				qmv_lib_insert_after(a,ci[qp]);
			else
				qmv_lib_insert_after(a,ci);

		}

		var mf2 = a;
	
		if (is_multi)
			mf2 = a.firstChild;
			
		
		new_cur = mf2;
		
		if (!is_undo)
			qmvi_report_add_line("edits","undo","modify","add_insert","",mf2);

			
	
	}
	else if (type=="delete")
	{
		
		
		var preserve_inner = ci.innerHTML;
		var skip = false;
		var count=0;
		
		var kids = cc.childNodes;
		for (var i=0;i<kids.length;i++)
		{
			if (kids[i].tagName=="A" || (is_multi && kids[i].tagName=="DD"))
				count++;

			if ((kids[i].tagName=="SPAN") && (kids[i].className.indexOf("qmtitle")+1 || kids[i].className.indexOf("qmdivider")+1 || kids[i].className.indexOf("qmcbox")+1))
				count++
		}
		
		var mod = "sub";
		
		
		if (count<2)
		{
			
			if (qm_a(cc))
			{
				qmv_show_dialog("alert",null,"The last main menu item can't be deleted.",450)
				return;
			}
			else
			{
				
				if (is_multi)
					new_cur = cc[qp].idiv;
				else
					new_cur = cc.idiv;
				
				
				if (is_multi)
				{
					
					var mdc = cc[qp];
					mdc.removeChild(cc);
					
					if (mdc.getElementsByTagName("DD").length==0)
						qmv_remove_sub_container(mdc);
					else
					{
						new_cur = mdc.getElementsByTagName("DD")[0].firstChild;
						qmv_addinsert_renumber_columns(mdc);
					}
					
				}			
				else
					qmv_remove_sub_container(cc);
					
				skip = true;

			}
		}
		

		if (!skip)
		{

			mod = "next";
			
			new_cur = qmv_lib_get_nextsibling_atag_or_span(mf,is_multi);
			if (!new_cur)
			{
				new_cur = qmv_lib_get_previoussibling_atag_or_span(mf,is_multi);
				mod = "prev";
			}
			
			
			if (ci.cdiv)
			{
				
				if (ci.cdiv.hasshadow)
					ci.cdiv.hasshadow[qp].removeChild(ci.cdiv.hasshadow);
				
				if (is_multi)	
					ci[qp].removeChild(ci.cdiv);
				else
					cc.removeChild(ci.cdiv);
					
				qm_li["qm"+qmv.id] = null;
				
			}
						
			if (qm_lh==mf)qm_lh=null;
			cc.removeChild(mf);
				
		}

		
		
		if (!is_undo)
		{
			var pitem = null;
			if (!qm_a(new_cur[qp]) || !(new_cur[qp].tagName=="DD" && qm_a(new_cur[qp][qp][qp])))
			{
				if (new_cur[qp] && new_cur[qp].tagName=="DD")
					pitem = new_cur[qp][qp][qp].idiv;
				else	
					pitem = new_cur[qp].idiv;
				
			}
					
			qmvi_report_add_line("edits","undo","modify","delete","",preserve_inner,ci.className,new_cur,mod,pitem);
		}


	}
	else if (type.indexOf("addsub")+1)
	{

		if (ci.className.indexOf("qmdivider")+1 || ci.className.indexOf("qmtitle")+1 || ci.className.indexOf("qmcbox")+1)
		{
			qmv_show_dialog("alert",null,"Sub menus cannot be applied to <b>title</b>, <b>content box</b>, <b>divider</b>, and other <b>non-stardard</b> items. Select a standard <b>anchor</b> item, then apply a child sub menu.",540);			
			return;
		}
		
		if (ci.cdiv)
		{
			qmv_show_dialog("alert",null,"The selected item already contains a sub menu.",450);
			return;
		}
	
		
		var d = document.createElement("DIV");
			
		var qty = 1;
		if (type.length>6)
		{
			var qq = type.substring(6);
			if (qq && (qq=="contentbox" || qq.indexOf("x")+1))
				qty = qq;
			else
				qty = parseInt(type.substring(6));

		}

		if (typeof qty == "string")
		{
			if (qty=="contentbox")
			{
				qmv_check_initialize_new_content_box_settings();
				inner = 'This is a new multi line content box.<br><br>Content boxes may contain multiple custom styled <a href="http://www.kirantechnologies.com">inline links</a>.<br><br>Content boxes may also contain images, table and div based layouts, or any HTML content you wish to include.<br><br><b>Hint:</b> Double click the content box for quick access to associated properties.';
				a = qm_modify_items_create_atag(null,inner,true,null,true);
				d.appendChild(a);
				
			}
			else if (qty.indexOf("x")+1)
			{
				var cols_rows = qty.split("x");
				cols_rows[0] = parseInt(cols_rows[0]);
				cols_rows[1] = parseInt(cols_rows[1]);
				
				for (var i=0;i<cols_rows[0];i++)
				{
					var n_dlist = qmv_addinsert_get_new_column(null);
					
					for (var j=0;j<cols_rows[1];j++)
						n_dlist.appendChild(qm_modify_items_create_atag(null,null,false,true,true));
									
					d.appendChild(n_dlist);
				}
			}
		} 
		else if (typeof qty == "number")
		{
			for (var i=0;i<qty;i++)
			{
				a = qm_modify_items_create_atag(null,inner,null,null,true);
				d.appendChild(a);
			}
		}

		qmv_attach_container_events(d);
		
		var nsub = qmv_lib_insert_after(d,ci);
		
		var ra = document.getElementById("qm"+qmv.id);
		nsub.sh = ra.sh;
		nsub.ch = ra.sh;

		nsub.rl = ra.rl;
		nsub.fl = ra.fl;
		nsub.ft = ra.ft;

		if (qmv.addons.tree_menu["on"+qmv.id])
			nsub.qmtree = 1;
				
		nsub.style.zIndex = (qm_get_level(cc)+1)+"0";
					
		nsub.idiv = ci;
		ci.cdiv = nsub;
		qm_arc("qmparent",ci,true);

		new_cur = ci;

		qm_la = null;
		qm_oo(new Object(),new_cur,false);


		if (qty=="contentbox")
		{
			
			var sps = nsub.getElementsByTagName("SPAN");
			for (var j=0;j<sps.length;j++)
			{
				if (sps[j].className.indexOf("qmcbox")+1)
					new_cur = sps[j];
					

			}

		}
		else
			new_cur = nsub.getElementsByTagName("A")[0];

		if (!is_undo)
			qmvi_report_add_line("edits","undo","modify","add_insert","",new_cur);

			
		qmv_applyclassnames_globally_from_modify(null,nsub);	
		
	}
	else if (type=="moveup" || type=="movedown" || type=="moveleft" || type=="moveright")
	{
		if (qmv.addons.tree_menu["on"+qmv.id])
			skip_oo = true;

		var move_column = false;
		var is_horizontal = qmv_is_container_horizontal(cc);
		
		var go_u = false;
		var go_d = false;
		
		if (is_horizontal && type=="moveleft")
			go_u = true;
		else if (is_horizontal && type=="moveright")
			go_d = true;
		else if (!is_horizontal && (type=="moveup" || (type=="moveleft" && is_multi)))
		{
			go_u = true;
			if (type=="moveleft" && is_multi) move_column = true;
		}	
		else if (!is_horizontal && (type=="movedown" || (type=="moveright" && is_multi)))
		{
			go_d = true;
			if (type=="moveright" && is_multi) move_column = true;
		}
			
		
		if (go_u || go_d)
		{
		
			if (go_u)
			{
				if (move_column && is_multi)
				{
					var ps = qmv_lib_get_previoussibling_column(cc);
					if (ps)
					{
						cc[qp].insertBefore(cc[qp].removeChild(cc),ps);
						qmv_addinsert_renumber_columns(cc[qp]);		
					}
					
					
				}
				else
				{
					var ps = qmv_lib_get_previoussibling_atag_or_span(mf,is_multi);
					if (ps)
					{
					
						if (is_multi)
						{
							ci = cc.removeChild(ci[qp]);
							cc.insertBefore(ci,ps[qp]);
							ci = ci.firstChild;
						}
						else
						{
							ci = cc.removeChild(ci);
							cc.insertBefore(ci,ps);
						}

						if (ci.cdiv)
						{
							var cd;
							if (is_multi)
								cd = ci.cdiv[qp].removeChild(ci.cdiv);
							else
								cd = cc.removeChild(ci.cdiv);
												
							qmv_lib_insert_after(cd,ci);

							if (qmad.br_ie7 && cd.style.visibility == "inherit")
							{
								cd.style.visibility = "hidden";
								cd.style.visibility = "inherit";
							}
							
						}
					
						new_cur = ci;

						if (!is_undo)
							qmvi_report_add_line("edits","undo","modify","moveup","",new_cur);
					}
				}
			}
			else if (go_d)
			{
				if (move_column && is_multi)
				{
					var ps = qmv_lib_get_nextsibling_column(cc);
					if (ps)
					{
					
						if (qmv_lib_get_nextsibling_column(ps))
							cc[qp].insertBefore(cc[qp].removeChild(cc),ps.nextSibling);
						else
							cc[qp].appendChild(cc[qp].removeChild(cc));
							
						qmv_addinsert_renumber_columns(cc[qp]);
					
					}
					
				}
				else
				{
					var ps = qmv_lib_get_nextsibling_atag_or_span(mf,is_multi);
					if (ps)
					{
					
						if (is_multi)
						{
							ci = cc.removeChild(ci[qp]);
							qmv_lib_insert_after(ci,ps[qp]);
							ci = ci.firstChild;	
						}
						else
						{
							if (ps.cdiv) ps = ps.cdiv;
							ci = cc.removeChild(ci);
							qmv_lib_insert_after(ci,ps);
						}

						if (ci.cdiv)
						{
							
							var cd;
							if (is_multi)
								cd = ci.cdiv[qp].removeChild(ci.cdiv);
							else
								cd = cc.removeChild(ci.cdiv);
							
							qmv_lib_insert_after(cd,ci);

							if (qmad.br_ie7 && cd.style.visibility == "inherit")
							{
								cd.style.visibility = "hidden";
								cd.style.visibility = "inherit";
							}

						}
						
						new_cur = ci;

						if (!is_undo)
							qmvi_report_add_line("edits","undo","modify","movedown","",new_cur);

					}
				}

			}

		}
		else
		{
		
			if (is_horizontal)
				qmv_show_dialog("alert",null,"To move horizontal layout items use the left / right options.",400);
			else
				qmv_show_dialog("alert",null,"To move vertical layout items use the up / down options.",400);
		
		
			return;
			
		}
		
	
	}
	else if (type=="copyitem")
	{
		
		qmv.copyitem = ci.cloneNode(true);
		qm_arc("qmitem-m",qmv.copyitem);
		qm_arc("qmitem-s",qmv.copyitem);
	
		

	}
	else if (type=="pasteitem")
	{

		if (qmv.copyitem)
		{		
			
			if (is_multi)
			{
				var oud = document.createElement("DD");
				oud.appendChild(qmv.copyitem);
				a = cc.insertBefore(oud,ci[qp]);
				a = a.firstChild;
			}
			else
				a = cc.insertBefore(qmv.copyitem,ci);

			if (qmv.copyitem.className.indexOf("qmtitle")+1)
				qmv_attach_title_events(a);
			else if (qmv.copyitem.className.indexOf("qmdivider")+1)
				qmv_attach_divider_events(a);
			else if (qmv.copyitem.className.indexOf("qmcbox")+1)
				qmv_attach_cbox_events(a);
			else
			{
				qm_modify_items_create_atag(a);
				
			}

			if (qm_a(qmv.cur_sub))
				a.className = "qmitem-m";
			else
				a.className = "qmitem-s";
			
			qm_arc("qmparent",a);
			qm_arc("qmactive",a);
			a.cdiv = null;		

			if (!is_multi)
			{
				if (qmv_lib_is_menu_vertical(qmv.id))
				{
					a.style.cssFloat = "none";
					a.style.styleFloat = "none";
				}
				else
				{
					a.style.cssFloat = "";
					a.style.styleFloat = "";
				}
			}

			qmv.copyitem = a.cloneNode(true);
			new_cur = a;

			if (!is_undo)
				qmvi_report_add_line("edits","undo","modify","add_insert","",new_cur);

		}
		else
		{
			qmv_show_dialog("alert",null,"Before pasting, you must first copy an item.",350);

		}

	}
		
	if (new_cur && !skip_oo)
	{
		qm_oo(new Object(),new_cur,false);
	
		if (qmv.cur_sub)
		{
			//try is blocking an error i could not figure out related to deleting all the items in a sub
			try
			{
				qm_sam_stretch(qmv.cur_sub);
				qmv_reselect_all_menu_items_from_root_for_big_update(true);
			}
			catch(e){}
			
		}
	
	}
	

	
	qmv_update_all_addons();
	
	if (qmv.addons.tree_menu["on"+qmv.id])
	{
		qmv.addons.tree_menu.last_close_type = null;
		qmv_update_tree_menu(false,null,null,null,null,true);
	}
	
	qmv_position_addon_tools();
	qmv_position_pointer();	
	
	if (qmv.vdesign_tab=="html")
		qmvi_vd_tab_update_content();

		
	qmv.changed = true;		
	
}


function qmv_check_initialize_new_content_box_settings()
{



	var val = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","width",null,true,true);
	if (!val)
	{
		var update_inp = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","width","200px",false,true);
		if (update_inp)
			qmv_evt_update_tree_value(update_inp);


		val = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","padding",null,true,true);
		if (!val)
		{
			var update_inp = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","padding","10px",false,true);
			if (update_inp)
				qmv_evt_update_tree_value(update_inp);
		}

		val = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","fontFamily",null,true,true);
		if (!val)
		{
			var update_inp = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","fontFamily","Arial",false,true);
			if (update_inp)
				qmv_evt_update_tree_value(update_inp);
		}

		val = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","fontSize",null,true,true);
		if (!val)
		{
			var update_inp = qmv_find_update_tree_value("individuals","body #qm[i] span.qmcbox","fontSize","12px",false,true);
			if (update_inp)
				qmv_evt_update_tree_value(update_inp);
		}

	}

}


function qm_modify_items_create_atag(a,inner,iscbox,is_multi,is_submenu)
{
	
	//create new items or content boxes only!!!
	
	if (!a)
	{
	
		if (!iscbox)
		{
			
			a = document.createElement("A");
			a.href = "javascript:void(0);";
				
			if (!is_submenu && qm_a(qmv.cur_sub))
				a.className = "qmitem-m";
			else
				a.className = "qmitem-s";
			
		}
		else
		{
			a = document.createElement("SPAN");
			a.className = "qmcbox";
		}
		
		if (inner)
			a.innerHTML = inner;
		else
			a.innerHTML = "New Item";
		
	}
	
	if (!iscbox)
		qmv_modify_add_item_atag_events(a);
	else
		qmv_attach_cbox_events(a);

	a.qmmi = 1;
	a.onmouseover = qmv_visual_design_menu_item_hover_handle;
	a.onclick = qm_oo;
	
	
	if (is_multi)
	{
		var d = document.createElement("DD");
		d.appendChild(a);
	
		return d;
	}
	else
		return a;

}

function qmv_modify_add_item_atag_events(a)
{

	a.ondblclick = function(e)
	{
			
		qmv_show_dialog("url",document.getElementById("qmv_editurl_field"));
		qm_kille(e);
	}

	a.oncontextmenu = function(e)
	{
		qmv_show_context(e,"menuitem",this);

	}


}


function qm_arc(name,b,add)
{

	var a = b[qc];
	if (add)
	{
		if (a.indexOf(name)==-1)
			b[qc] += (a?' ':'') + name;	
		
	}
	else
	{
		
		b[qc] = a.replace(" "+name,"");
		b[qc] = b[qc].replace(name,"");
	
	}
}


function qmv_reset_inline_style_on_all_subs(cname)
{
	
	var divs = document.getElementById("qm"+qmv.id).getElementsByTagName("DIV");
	for (var i=0;i<divs.length;i++)
	{

		if (!divs[i].idiv)
			continue;
				
		qmv_evt_update_inline_style("",divs[i],null,cname)
	
	}

}


function qmv_reset_inline_style_on_all_columns(cname)
{
	
	var dls = document.getElementById("qm"+qmv.id).getElementsByTagName("DL");
	for (var i=0;i<dls.length;i++)
	{
				
		if (dls[i].className && dls[i].className.indexOf("qmmulti")+1)
			qmv_evt_update_inline_style("",dls[i],null,cname)
		
	
	}

}

