function qmv_updatehandle_sopacity_show(a,isyes,bg,itembg,force)
{
	
	if (!isyes)
	{
				

		if (qmv.questionasked_sopacity && !force) return;

		
		//fix!: fix this code for both this addon and rounded corners, you could have a div in the content box that is found first

		var m = document.getElementById("qm"+qmv.id).getElementsByTagName("DIV");
		if (m[0])
		{

			var bg = qm_lib_get_computed_style(m[0],"background-color","backgroundColor")+"";

			if (qmad.br_modern && !(qmad.br_s3 || qmad.br_s4))
				bg = qmv_convert_color_to_hex(bg);

		
			var itembg = "";
			var ma = m[0].getElementsByTagName("A")[0];
			if (ma)
				itembg = qm_lib_get_computed_style(ma,"background-color","backgroundColor")+"";


			if (bg && bg.toLowerCase()!="transparent" && bg!="rgba(0, 0, 0, 0)")
			{

				qmv_show_dialog("question-yesno",null,"Opacity subs are additional containers which sit under the sub menu items.  For the best results, set sub container and item colors for the menu transparent.  Next, apply container color styles to the opacity add-on.<br><br>Would you like to automatically move and apply your current color values?",540,"qmv_updatehandle_sopacity_show(null,true,'"+bg+"','"+itembg+"')");	
				qmv.questionasked_round_corners = true;
		
			}
			else
			{
				if (force)
					qmv_show_dialog("alert",null,"The opacity container colors have already been blended to match.",500);


			}	
	
		}
	}
	else
	{
		
		var inp;
		inp = qmv_find_update_tree_value("css","#qm[i] .qmsub","backgroundColor","transparent",false,true);
		qmv_evt_update_tree_value(inp,null,null,null,null,null,true);
		
		inp = qmv_find_update_tree_value("css","#qm[i] .qmitem-s","backgroundColor","transparent",false,true);
		qmv_evt_update_tree_value(inp,null,null,null,null,null,true);

		if (document.getElementById("qmvtree_filter").cdiv.style.display=="block")
			qmv_filter_init2();

		var sval;

		if (bg || itembg)
		{
			sval = bg;
			if (!bg)
				sval = itembg;


			inp = qmv_find_update_tree_value("addon","sopacity","sopacity_bg_color",sval);
			qmv_evt_update_tree_value(inp);
		}

	
	}

}



