function qmv_update_image(hide,a,b,c,d,e,args)
{
	
	if (!hide && !qmv.addons.image["on"+qmv.id])
		return;
			
	if (qmv.persist_settings.bottom_bar_tab_state=="itemeditor" && qmv.loaded)
	{
	
		var qd = document.getElementById("qmvi_df_htmledit_design");
		var ze;
		if (qd && (qd = qd.contentWindow))
		{
			ze = qd.document.getElementById("z_edit_item");
			qm_image_switch(ze,'hide',false);
			if (ze.className.indexOf("qmactive")+1)
				qm_image_switch(ze,'show',true);
		}
		
		qd = document.getElementById("qmvi_dlg_df_htmledit_design");
		if (qd && (qd = qd.contentWindow))
		{
			ze = qd.document.getElementById("z_dlg_edit_item");
			qm_image_switch(ze,'hide',false);
			if (ze.className.indexOf("qmactive")+1)
				qm_image_switch(ze,'show',true);
		}
		
		qm_image_switch(qmv.cur_item,'hide',false);
		if (qmv.cur_item.className.indexOf("qmactive")+1)
			qm_image_switch(qmv.cur_item,'show',true);
		
	}
	
}

function qmv_update_hautofit(hide,a,b,c,d,e,args)
{

	if (!hide && !qmv.addons.hautofit["on"+qmv.id])
		return;
	
	
	
	var skip_htmledit_update = false;
	if (args && args!="null")
	{
		args=eval("("+args+")");
		skip_htmledit_update = args.skip_htmledit_panel;
	}
	
	var md = document.getElementById("qm"+qmv.id);
	
	if (!hide)
	{
		
		if (qmad["qm"+qmv.id].hautofit_main)
		{
			qmv_update_hautofit_undo(md);
			qm_hautofit_size_items(md);
		}
		else
			qmv_update_hautofit_undo(md);
			
		
		var divs = md.getElementsByTagName("DIV");
		for (var i=0;i<divs.length;i++)
		{
			if (qmad["qm"+qmv.id].hautofit_subs || divs[i].className.indexOf("qm-horizontal-auto-fit")+1)
			{
				if (divs[i].style.visibility=="inherit")
				{
					qmv_update_hautofit_undo(divs[i]);
					qm_hautofit_size_items(divs[i],true);
				}
			}
			else
			{
				qmv_update_hautofit_undo(divs[i]);
			
			}
			
		}	
		
	}
	else
	{
	
		qmv_update_hautofit_undo(md);
		
		var divs = md.getElementsByTagName("DIV");
		for (var i=0;i<divs.length;i++)
		{
			if (divs[i].qmvishautofit)
			{
				qmv_update_hautofit_undo(divs[i]);
			}
			
		}	
		
	}
	
	
	qmv_load_inline_styles_to_tree();
	
	if (qmv.loaded)
	{
		qmv_setbox_update_inline();
		qmv_htmledit_update_from_visual_change(skip_htmledit_update);
	}

}

function qmv_update_hautofit_undo(a)
{
		
	if (!a.qmvishautofit)
		return;
	else
		a.qmvishautofit = null;
	
	var ch = a.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		if (ch[i] && ch[i].tagName=="A")
		{
			var sw = "";
			if (ch[i].qmvsavewidth) sw = ch[i].qmvsavewidth;
			
			ch[i].style.width = sw;
		}
			
	}

}


function qmv_update_styleanim(hide,dtype)
{

	var cb = document.getElementById("qmvi_styleanim_checkbox_is_enabled");
	if(qmv.addons.styleanim["on"+qmv.id])
		cb.checked = true;
	else
		cb.checked = false;

	if (dtype=="styleanim_apply")
		qmvi_transition_panel_set_top_tab_bar_settings();
	else if (dtype)
	{
		qmvi_transition_panel_load_timeline();
	}
	
}

