function qmv_initialize_scroll()
{
	

	if (!qmv.addons.scroll["on"+qmv.id])
		return;
	

	if (qmad.scroll)
	{
					
		clearTimeout(qmad.scroll["timerqm"+qmv.id]);
		qmad.scroll["timerqm"+qmv.id] = null;				
	
	}


	var at = document.getElementById("qm"+qmv.id).childNodes;
	for (var i=0;i<at.length;i++)
	{
		
		if (at[i].tagName=="A" || (at[i].tagName=="DIV" && at[i].idiv) || (at[i].tagName=="SPAN" && (at[i].className.indexOf("qmcbox")+1 || at[i].className.indexOf("qmdivider")+1 || at[i].className.indexOf("qmtitle")+1)) || at[i].isscrollfade)
		{
			
			at[i].style.top = "";
			if (at[i].isscrollfade)
			{
				at[i][qp].removeChild(at[i]);
				i--;
			}
				
		}

	}


	qmv_update_scroll();
	
	
	

}

function qmv_update_scroll(hide,dtype,supress_msg,kill_styles_only,spec_id)
{
	

	if (!hide && !qmv.addons.scroll["on"+qmv.id])
		return;

	
	var tstyles = qmv_lib_get_qm_stylesheet(".qmisscrollstyles",true);
	if (!tstyles)tstyles = qmv_lib_get_qm_stylesheet(".qmvisscrollstyles",true);


	if (tstyles)
	{

		var rules;
		if (tstyles.rules)
			rules = tstyles.rules;
		else if (tstyles.cssRules)
			rules = tstyles.cssRules;


		if (!hide)
		{
			
			
			
			if (!qmv.addons.scroll.initialized)
			{

				qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id,"height:auto !important;overflow:visible !important;");
				qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" div","left:0px !important;top:0px !important;position:relative !important;visibility:inherit !important;margin-left:0px !important;margin-top:0px !important;width:auto !important;");
				qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" a","float:none !important;");


				var inp_h = qmv_find_update_tree_value("css","#qm[i]","height","",false,false,true);
				if (!inp_h.value || inp_h.value=="auto")
				{
					inp_h.value = "150px";			
					qmv_evt_update_tree_value(inp_h,null,null,null,true);
				}


				qmv_scroll_init_index_marks();
				qmv_update_scroll_ask_width_height();


				qmv.addons.scroll.initialized = true;
				qmv.addontoolpositioners += "qmv_scroll_position_marks();"

			}


		}
		else
		{

			qmv_position_addon_tools_remove_function("qmv_scroll_position_marks();");
			qmv.addons.scroll.initialized = false;	

			var tid = qmv.id;
			if (kill_styles_only)
				tid = spec_id;

			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+tid);
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+tid+" div");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+tid+" a");
			
			if (!kill_styles_only)
			{

				var rs = document.getElementById("qmvscrollmarks"+qmv.id);
				if (rs) rs[qp].removeChild(rs);


				var inp_h = qmv_find_update_tree_value("css","#qm[i]","height","",false,false,true);
				inp_h.value = "auto";				
				qmv_evt_update_tree_value(inp_h,null,null,null,true);


				var vval = qmv_lib_parse_value(qmv_find_update_tree_value("settings","create","isvertical",null,true),'bool');
				if (!vval)
				{
					var inp_w = qmv_find_update_tree_value("css","#qm[i]","width","",false,false,true);
					inp_w.value = "auto";
					qmv_evt_update_tree_value(inp_w,null,null,null,true);
				}
				
			}


			qmv_set_all_subs_to_default_position();	
			qmv.questionasked_scroll = false;	

		}

	}

}



function qmv_update_scroll_ask_width_height(a,isyes,force)
{
	
	var inp_w = qmv_find_update_tree_value("css","#qm[i]","width",null,false,false,true);
	var inp_h = qmv_find_update_tree_value("css","#qm[i]","height",null,false,false,true);

	if (!isyes)
	{
				

		if (qmv.questionasked_scroll && !force) return;
	
		
		var sw = "180px";
		var sh = "150px";

		if (inp_w.value && inp_w.value.toLowerCase()!="auto") sw = inp_w.value;
		if (inp_h.value && inp_h.value.toLowerCase()!="auto") sh = inp_h.value;
		
		var def = sw+"|"+sh;
		qmv_show_dialog("question-okcancel-input2",null,"Define dimensions for the scroll effect, the values will be applied to the CSS rules for the main container.  These values are further cusomizable under CSS Styles --&gt; Main --&gt; Container.|Width (default 'px' units or 'auto')|Height (default 'px' units)",310,"qmv_update_scroll_ask_width_height(qmd.owner,true)",null,null,def);	

			
	}
	else
	{
		var sv = document.getElementById("qmvi_ok_input1").value;
		inp_w.value = sv;
			
		var sv = document.getElementById("qmvi_ok_input2").value;
		inp_h.value = sv;


		qmv_evt_update_tree_value(inp_w,null,null,null,true);
		qmv_evt_update_tree_value(inp_h,null,null,null,true);
	
	}

}





function qmv_position_addon_tools_remove_function(s)
{
	var t = qmv.addontoolpositioners;
	var i = t.indexOf(s);
	
	if (i>-1) qmv.addontoolpositioners = t.substring(0,i)+t.substring(i+s.length);


}

function qmv_position_addon_tools()
{

	eval(qmv.addontoolpositioners);



}

function qmv_scroll_init_index_marks()
{

	

	var a = document.getElementById("qm"+qmv.id);

	var ms = document.createElement("SPAN");
	ms.id = "qmvscrollmarks"+qmv.id;

	ms.style.display = "block";
	ms.style.position = "absolute";
	ms.style.fontSize = "1px";
	ms.style.visibility = "hidden";
	ms.style.borderWidth = "0px 0px 0px 1px";
	ms.style.borderColor = "#ff0000"

	if (qmad.br_ie7)
		ms.style.borderStyle = "solid";
	else
		ms.style.borderStyle = "dotted";

	a.appendChild(ms);
	qmv_scroll_position_marks();

}


function qmv_scroll_position_marks()
{
	

	if (!qmv.addons.scroll["on"+qmv.id])
		return;

	var a = document.getElementById("qm"+qmv.id);
	var ms = document.getElementById("qmvscrollmarks"+qmv.id);

	var bt = 0;
	var b;

	b = qm_lib_get_computed_style(a,"border-bottom-width","borderBottomWidth");
	if (!isNaN(b = parseInt(b))) bt+=b;

	b = qm_lib_get_computed_style(a,"border-bottom-width","borderBottomWidth");
	if (!isNaN(b = parseInt(b))) bt+=b;


	var totalh = a.offsetHeight-bt;
	var totalw = 10;

	ms.style.height = totalh+"px";
	ms.style.width = totalw+"px";
	ms.style.top = "0px";
	ms.style.left = (a.offsetWidth+5)+"px";
	
		
	var h = qmv_find_update_tree_value("css","#qm[i]","height",null,true);
	if (!isNaN(h = parseInt(h)))
	{

		
	
		var ch = ms.childNodes;
		for (var i=0;i<ch.length;i++)
		{
			ms.removeChild(ch[i]);
			i--;

		}
		
		var mc = parseInt(totalh/h)+1;
		ms.style.height = (mc*h)+"px";

		for (var i=0;i<mc;i++)
		{
		
			var sp = document.createElement("SPAN");
			sp.style.width = (totalw-1)+"px";
			sp.style.fontSize = "1px";
			sp.style.display = "block";
			sp.style.position = "relative";
			
			if (i==0)
			{
				sp.style.borderStyle = "dotted";
				sp.style.borderWidth = "1px 0px 0px 0px";

				sp.style.height = (h-1)+"px";
				
			}
			else
			{
				sp.style.borderStyle = "none";
				sp.style.height = h+"px";
			
			}


			sp.style.borderColor = "#ff0000";

			

			ms.appendChild(sp);

			

			spc = document.createElement("SPAN");
			spc.style.fontSize = "1px";
			spc.style.display = "block";
			spc.style.position = "relative";
			spc.style.width = "0px";
			spc.style.height = "0px";
			spc.style.left = "0px";

			sp = document.createElement("SPAN");
			sp.style.width = 21+"px";
			sp.style.height = 21+"px";
			sp.style.backgroundImage = 'url('+qmv.base+'images/sizer_updown.gif)';
			sp.style.display = "block";
			sp.style.position = "absolute";
			sp.style.top = "-10px";
			

			sp.qmvattype = "updown-tick";

			if (sp.attachEvent)
			{
				sp.attachEvent("onmousedown",qmv_addontools_mouse_down);
				sp.attachEvent("onmousemove",qmv_addontools_mouse_move);
				sp.attachEvent("onmouseup",qmv_addontools_mouse_up);
			}
			else if (sp.addEventListener)
			{
				sp.addEventListener("mousedown",qmv_addontools_mouse_down,false);
				sp.addEventListener("mousemove",qmv_addontools_mouse_move,false);
				sp.addEventListener("mouseup",qmv_addontools_mouse_up,false);
			}
			



			spc.appendChild(sp);
			ms.appendChild(spc);			


		}


		ms.style.visibility = "visible";
	}
	else
		ms.style.visibility = "hidden";


	

}

function qmv_addontools_mouse_down(e)
{

	
	e = e || event;
	//if (e.button!=0) return;

	var targ = e.srcElement || e.target;
	if (!targ.qmvattype) return;

	qmv.addontools_mdown = true;
	qmv.addontools_prev_x = e.screenX;
	qmv.addontools_prev_y = e.screenY;
	qmv.addontools_orig_x = e.screenX;
	qmv.addontools_orig_y = e.screenY;
	qmv.addontools_obj = targ;
	qmv.addontools_type = targ.qmvattype;
	
	targ.style.cursor = "move";
	
	qm_kille(e);
	return false;
}


function qmv_addontools_mouse_move(e,src)
{

	e = e || event;
	

	if (qmv.addontools_mdown)
	{
		
		var m = qmv.addontools_obj;
	

		//var tx = qmv.addontools_orig_x-e.screenX;
		//var ty = qmv.addontools_orig_y-e.screenY;
		//if (qmv.addontools_moved || Math.abs(tx)>5 || Math.abs(ty)>5)
		//{
	
		
			var xdif = qmv.addontools_prev_x-e.screenX;
			var ydif = qmv.addontools_prev_y-e.screenY;
			

			m.style.top = parseInt(m.style.top)-ydif+"px";

			if (qmv.addontools_type!="updown-tick")			
				m.style.left = parseInt(m.style.left)-xdif+"px";

			
			qmv.addontools_prev_x = e.screenX;
			qmv.addontools_prev_y = e.screenY;

			qmv.addontools_moved = true;		
					
			if (qmad.br_ie)
				qmv.addontools_obj.setCapture(true);

			qm_kille(e);
			return false;


		//}		
	}

}


function qmv_addontools_mouse_up(e)
{

	e = e || event;
	var targ = e.srcElement || e.target;
	
	
	if (qmv.addontools_moved)
	{
		

		var m = qmv.addontools_obj;

		if (qmv.addontools_type=="updown-tick")
		{
			var dif = qmv.addontools_prev_y-qmv.addontools_orig_y;
			var h = parseInt(qmv_find_update_tree_value("css","#qm[i]","height",null,true));
			if (!isNaN(h)) 
			{
				var sv = (h+dif);
				if (sv<1) sv = 10;
				var inp = qmv_find_update_tree_value("css","#qm[i]","height",sv+"px",null,null,true);
				inp.value = sv+"px";
				qmv_evt_update_tree_value(inp);

			}
		}

	}



	qmv.addontools_moved = false;
	qmv.addontools_mdown = false;
	
	
	targ.style.cursor = "";

}







function qmv_update_tree_menu(hide,dtype,supress_msg,kill_styles_only,spec_id,cust_update)
{
	
	
	if (dtype=="bool" || dtype=="treecollapse")
	{
		var inac = qmv_find_update_tree_value("addon","tree_menu","tree_auto_collapse",null,false,false,true);
		var inmo = qmv_find_update_tree_value("addon","tree_menu","tree_mouseover",null,false,false,true);
				
		if ((inmo.value && inmo.value.toLowerCase()=="true") && (!inac.value || (inac.value && inac.value.toLowerCase()=="false")))
		{
			if (dtype=="bool")
			{
				inac.value = 'sync';
				qmv_evt_update_tree_value(inac);
			}
			else
			{
				inmo.value = 'false';
				qmv_evt_update_tree_value(inmo);
			
			}
			
		}
			
	}
		
	if (!hide && !qmv.addons.tree_menu["on"+qmv.id])
		return;


	var tstyles = qmv_lib_get_qm_stylesheet(".qmistreestylesqm"+qmv.id,true);
	if (!tstyles)tstyles = qmv_lib_get_qm_stylesheet(".qmvistreestyles",true);

	if (tstyles)
	{
		

		var rules;
		if (tstyles.rules)
			rules = tstyles.rules;
		else if (tstyles.cssRules)
			rules = tstyles.cssRules;

		if (!hide)
		{
			
			
			var az = "";
			if (qmad.br_ie) az = "zoom:1;";

			var dst = 'width:auto !important;left:0px !important;top:0px !important;overflow:hidden;'+az+'margin-left:0px !important;margin-top:0px !important;border-bottom-width:0px !important;border-top-width:0px !important;';
			var ac = qmv_find_update_tree_value("addon","tree_menu","tree_auto_collapse",null,true);
			
			if (!cust_update)
			{

				if (ac!=qmv.addons.tree_menu.last_close_type || !qmv.addons.tree_menu.initialized)
				{
			
					if (ac=="fixed-height")
					{

						qmv_lib_update_remove_rule(tstyles,rules,"#qm"+qmv.id+" div div");
						qmv_lib_update_remove_rule(tstyles,rules,"#qm"+qmv.id+" div");
						qmv_lib_update_remove_rule(tstyles,rules,"#qm"+qmv.id+" a");

						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id,"position:relative !important;");
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" .qmtreemshstd",dst);
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" .qmtreemshstda","float:none !important;white-space:normal !important;"+az);
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" div div","position:absolute !important;");
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" .qmtreemshshow","overflow:visible !important;");
					
					}
					else
					{
					
						qmv_lib_update_remove_rule(tstyles,rules,"#qm"+qmv.id+" div div");
				
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id,"position:relative !important;");
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" a","float:none !important;white-space:normal !important;"+az);
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" div",dst);
				
					

					}
	
				}

				if (ac!="fixed-height")
				{

					if (!isNaN(qmad["qm"+qmv.id].tree_sub_sub_indent))
						qmv_lib_update_add_rule_styles(tstyles,rules,"#qm"+qmv.id+" div div",'padding-left:'+qmad["qm"+qmv.id].tree_sub_sub_indent+'px;');
					else
						qmv_lib_update_remove_rule(tstyles,rules,"#qm"+qmv.id+" div div");
			
				}
			}

			
			if (qmad.tree)
			{

				qmad.tree.msh = null;
				qmad.tree.sync = null;
				qmad.tree.chain = null;
				qmad.tree.mo = null;
			}	
			

			if (ac!=qmv.addons.tree_menu.last_close_type || !qmv.addons.tree_menu.initialized)
			{
				var selt = false;
				var a = document.getElementById("qm"+qmv.id).getElementsByTagName("A");
				for (var i=0;i<a.length;i++)
				{
					var c;
					if (c = a[i].cdiv)
					{
						c.ismove = null;
						c.qmtree = null;
									
						if (c.style.visibility=="inherit")	
						{
							qm_arc("qmfh",c);
							qm_arc("qmtreemshstd",c);

							if (ac!="fixed-height")
							{
								qm_arc("qmtreemshshow",c);
								c.style.position = "relative";
							}
							else
							{
								
								if (qmv.addons.tree_menu.last_close_type=="false" || !qmv.addons.tree_menu.last_close_type)
								{
									
									var cc = qmv.cur_item[qp];
									if (qmv.cur_item.cdiv) cc = qmv.cur_item.cdiv;

									var sk = false;
									while (!qm_a(cc))
									{
										if (cc==c) sk = true;
										cc = cc[qp];							
									}
									
									
									if (sk)
									{

										if (qm_a(c[qp]))
										{	
											qm_arc("qmtreemshshow",c,true);
											c.style.position = "relative";
										}
										
									}
									else
									{
										qm_tree_finish_collapse(c);
									}

									
								}
								else
								{
									
									if (qm_a(c[qp]))
									{
										qm_arc("qmtreemshshow",c,true);
										c.style.position = "relative";
									}
									else
										c.style.position = "";
								}							
							}
							
						}
					
	
						if (ac=="fixed-height" && !qm_a(c[qp]))
						{
							qm_arc("qmfv",c);
							qm_arc("qmfh",c);
						}

						
					}
	
					qm_arc("qmtreemshstda",a[i]);
				}

				
				a = document.getElementById("qm"+qmv.id).getElementsByTagName("SPAN");
				for (var i=0;i<a.length;i++)
				{
					if (a[i].qmtreespanah)
					{
						a[i][qp].removeChild(a[i])
						i--;
					}
				}


				if (ac=="fixed-height")
					qmv_set_all_subs_to_default_position(true);
			
			}

			

			qm_tree_init(null,"qm"+qmv.id);

			qmv.addons.tree_menu.last_close_type = ac;	
			qmv.addons.tree_menu.initialized = true;


		}
		else
		{


			var ti = spec_id;
			if (!kill_styles_only) ti = qmv.id;
			

			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" .qmtreemshstd");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" .qmtreemshstda");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" .qmtreemshshow");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" div div");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" div");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti+" a");
			qmv_lib_update_remove_rule(tstyles,rules,"#qm"+ti);


			if (kill_styles_only)
			{

				qmv.addons.tree_menu.last_close_type = null;
				qmv.addons.tree_menu.initialized = false;
				return;
			}
			
									
			var a = document.getElementById("qm"+qmv.id).getElementsByTagName("A");
			for (var i=0;i<a.length;i++)
			{

				if (a[i].cdiv)
				{
					
					a[i].cdiv.qmtree = null;
					a[i].cdiv.ismove = null;
										
					qm_arc("qmfh",a[i].cdiv);
					qm_arc("qmfv",a[i].cdiv);
					
					
					a[i].cdiv.style.height = "";
					a[i].cdiv.style.position = "";
					a[i].cdiv.style.visibility = "";
					
				}

			}


			var cl = qmv.cur_item;
			if (cl.cdiv)
				cl = cl.cdiv;
			else
				cl = cl[qp];

			while (!qm_a(cl))
			{
				if (cl.tagName=="DIV")
					cl.style.visibility = "inherit";

				cl = cl[qp];
			}

			qmv_set_all_subs_to_default_position(true);
			qmv.addons.tree_menu.initialized = false;			

		}
		


		
		
		
	}

	

	if (hide) qmv.asked_tree_width = false;
	if (!qmv.asked_tree_width && !supress_msg)
	{

		

		var tinp = new Object();

		if (hide)
		{

			var vval = qmv_lib_parse_value(qmv_find_update_tree_value("settings","create","isvertical",null,true),'bool');
			if (!vval)
				qmv_input_code_ask_width();
		}
		else
		{
			
			var vval = qmv_find_update_tree_value("css","#qm[i]","width",null,true);
			if (!vval || vval=="auto")
				qmv_input_code_ask_width(true);
		}

		if (!hide)
			qmv.asked_tree_width = true;
	}
	

}


function qmv_delete_menu()
{

	if (qmv_lib_get_menu_count()>1)
	{

		var a;
		if (a = document.getElementById("qm"+qmv.id))
			qmv_show_dialog("question-okcancel",a,"The active menu system, and all asociated settings will be removed!<br><br>Do wish to continue?",450,"qmv_delete_menu_ok(qmv.id,true)");	
			
	
	}
	else
	{
		qmv_show_dialog("alert",a,"The last menu can't be removed.",250);
	}
}


function qmv_view_html_page(skip_prompt)
{
	

	qmv_addon_set_all_status();

	qmv_hide_dialog(false,false,true);
	qmv_hide_dialog(false,true,false);
	qmv_hide_dialog(true,false,false);


	if (!skip_prompt && !qmv.msg_shown_preview)
	{
		qmv_show_dialog("question-okcancel",a,"The visual interface will be closed while viewing the HTML page. To re-open the interface <font style='color:#dd3300'>double click</font> anywhere in the document.<br><br>Continue with HTML page view?",450,"qmv_view_html_page(true)");
		return;
	}


	if (qmv.interface_full)
	{
		
		qmv_set_interface_mode("inpage");
		qmv.was_full_on_preview = true;
	}
	else
	{

		qmv.was_full_on_preview = false;
	}



	qmv.msg_shown_preview = true;

	//qm_th = qmv.ms_hide_timer;
	document.ondblclick = qmv_design_menu;

	
	var a;
	for (var i=0;i<10;i++)
	{
		if (a = document.getElementById("qm"+i))
		{
			
			qmv_hide_pointer("qm"+i);
			qmv_preview_menu2(a);
			
		}

	}


	qmv.preview_mode = true;
	qmv.qmvi.style.visibility = "hidden";

	
	var i;
	for (i in qm_li)
	{
		if (qm_li[i])
			qmv_2bo(i);
	}
	
	

}

function qmv_preview_update(e,a)
{
	
	var piw = document.getElementById("qmvi_preview_iframe").contentWindow;

	piw.document.open();

	if (a=="qmvi_preview_javascript_disabled")
		piw.document.write(qmv_savegen(false,true,true));	
	else
		piw.document.write(qmv_savegen(false,true));
	
	piw.document.close();

}


function qmv_preview_init(wait)
{
	
	//this wait delay overcomes some odd bugs, one in particular with the horizontal auto fit items add on
	if (!wait)
	{
		setTimeout("qmv_preview_init(true)",100);
		return;
	}
	
		
	var piw = document.getElementById("qmvi_preview_iframe").contentWindow;
	piw.document.open();
	piw.document.write(qmv_savegen(false,true));
	piw.document.close();
	
	//fix mouse capturing for when the mouse slips over the iframe in the preview dialog
	//piw.addEventListener("mousemove",parent.qmv_evt_move_fixcapture,false);

}


