function qmv_preview_menu2(b)
{
	


	var clickall = false;
	if ((b.oc && b.oc.indexOf("all")+1) || (qmv.addons.tree_menu["on"+b.id.substring(2)])) clickall = true;

	
	if (b.oc!="all-always-open")
	{
		if (clickall || b.oc=="main")
			document.onclick = qm_bo;
		else
			document.onmouseover = qm_bo;
	}


	if (b.oc && (b.oc.indexOf("all")+1 || b.oc=="main"))
		qm_th = 0;

	if (b.oc=="main")
	{
		
		qm_ib += b.id;
		b.onclick=function(event){qm_ic = true;qm_oo(new Object(),qm_la,true);qm_kille(event)};
		document.onmouseover = function()
		{
			qm_hhovhide();
			qm_la=null;clearTimeout(qm_tt);qm_tt=null;
		};
	}

	

	var sid = b.id.substring(2);
	a = b.getElementsByTagName("A");
	for (var j=0;j<a.length;j++)
	{

		a[j].ondblclick = null;
		

		if (clickall || (b.oc=="lev2" && !qm_a(a[j][qp])))
		{

			a[j].onmouseover=function(event){qm_hhovshow(event,this);o=this;a=this;if (window.qmad && qmad.bhover) eval(qmad.bhover);clearTimeout(qm_tt);qm_tt=null;qm_la=null;};
			a[j].onclick = function(event)
			{
				qm_oo(event,this);
				qm_kille(event);
			}
		}
		else
		{

			a[j].onmouseover = qm_oo;
			a[j].onclick = qm_oo;

		}
		
		
		a[j].oncontextmenu = function(e){e=e||event;qm_kille(e);return false;};
		
		if (qmv.addons.keyboard["on"+sid])
		{

			a[j].onfocus = null;
			if (a[j].attachEvent)
				a[j].attachEvent("onkeydown",qm_kb_press);
			else if (a[j].addEventListener)
				a[j].addEventListener("keypress",qm_kb_press,true);
		
		}

		a[j].qmts = qmv.ms_show_timer[b.id];
	}

	
	
	a = b.getElementsByTagName("SPAN");
	for (var j=0;j<a.length;j++)
	{
		
		if (a[j].className.indexOf("qmdivider")+1)
		{
			a[j].oncontextmenu = function(e){e=e||event;qm_kille(e);return false;};

		}
		else if (a[j].className.indexOf("qmtitle")+1)
		{

			a[j].oncontextmenu = function(e){e=e||event;qm_kille(e);return false;};

		} 
		else if (a[j].getAttribute("isibulletcss"))
		{
			
			a[j].oncontextmenu = function(e){e=e||event;qm_kille(e);return false;};

		}
		else if (a[j].getAttribute("isibullet"))
		{
			a[j].oncontextmenu = function(e){e=e||event;qm_kille(e);return false;};
		
		}
	}	
}

function qmv_click_document_element(e)
{
	e = e || event;
	if (e.button==0)
		qmv_hide_pointer("qm"+qmv.id);
	
	qmv_hide_context();
	
}



function qmv_design_menu()
{

	qmv.preview_mode = false;
	qm_th = 0;  //set the hide timer to zero
	
	document.onmouseover=function(event)
	{
		qm_hhovhide(event,this);
		qm_kille(event);
	}
	
	qm_ib = '';
	
	document.onclick = function(e){qmv_click_document_element(e);}
	document.ondblclick = null;

	if (qmv.was_full_on_preview && !qmv.interface_full)
		qmv_set_interface_mode("full");
	
	qmv.qmvi.style.visibility = "visible";

	var a;
	var ac = false;
	for (var i=0;i<10;i++)
	{
		if (a = document.getElementById("qm"+i))
		{
			//oops the menu was not converted
			//if (a.tagName=="UL")
			//{
				//qm_create(i,false,250,250,false,false,false,false,true);
				//setTimeout("qmv_design_menu()",10);
				//break;
			//}
			
			a.style.visibility = "";
			qmv_design_menu2(a);
			
			if (!ac)
			{
				ac = true;
				qm_oo(new Object(),a.getElementsByTagName("A")[0]);
				
			}
			
		}

	}	
	
	//show the interface
	qmv.qmvi.style.visibility = "visible";
}


function qmv_pointer_sizer_down(e)
{
	
	e = e || event;
	
	qmv_hide_context();
	
	if (e.button==0)
	{
		var targ = e.srcElement || e.target;
		if (!targ.qmvattype) return;

		qmv.pointersizer_mdown = true;
		qmv.pointersizer_prev_x = e.screenX;
		qmv.pointersizer_prev_y = e.screenY;
		qmv.pointersizer_orig_x = e.screenX;
		qmv.pointersizer_orig_y = e.screenY;
		qmv.pointersizer_obj = targ;
		qmv.pointersizer_type = targ.qmvattype;
		
		if (qmv.pointersizer_type.indexOf("leftright")+1)
			targ.style.cursor = "ew-resize";
		else
			targ.style.cursor = "ns-resize";
	}
	
	qm_kille(e);
	return false;
}


function qmv_pointer_sizer_move(e,src)
{

	e = e || event;
	

	if (qmv.pointersizer_mdown)
	{
		
		var m = qmv.pointersizer_obj;
		
		var xdif = qmv.pointersizer_prev_x-e.screenX;
		var ydif = qmv.pointersizer_prev_y-e.screenY;

		if (qmv.pointersizer_type=="container_leftright")
			qmv_position_pointer(true,true,parseInt(m.style.left)-xdif,false,"lr");
		else if (qmv.pointersizer_type=="column_leftright")
			qmv_position_pointer(true,false,parseInt(m.style.left)-xdif,true,"lr");
		else if (qmv.pointersizer_type=="container_updown")
			qmv_position_pointer(true,true,parseInt(m.style.top)-ydif,false,"ud");
		else if (qmv.pointersizer_type=="column_updown")
			qmv_position_pointer(true,false,parseInt(m.style.top)-ydif,true,"ud");			
		
			
		qmv.pointersizer_prev_x = e.screenX;
		qmv.pointersizer_prev_y = e.screenY;

		qmv.pointersizer_moved = true;		
				
		if (qmad.br_ie)
			qmv.pointersizer_obj.setCapture(true);

		qm_kille(e);
		return false;


	}

}


function qmv_pointer_sizer_up(e)
{

	e = e || event;
	var targ = e.srcElement || e.target;
		
	if (qmv.pointersizer_moved)
	{
				
		var adj = 1;
		if (qmv.pointersizer_type.indexOf("leftright")+1)
			qmv.pointersizer_value = parseInt(qmv.pointersizer_obj.style.left);
		else
		{

			if (qmv.pointersizer_type.indexOf("column")+1)
			{
				qmv.pointersizer_value = parseInt(qmv.pointersizer_obj.style.top)+21;
				adj=2;
			}
			else
			{
				qmv.pointersizer_value = parseInt(qmv.pointersizer_obj.style.top);
				adj=2;
			}
		}
			
		var gcs_obj = qmv.cur_sub;	
		if (qmv.pointersizer_type.indexOf("column")+1)
			gcs_obj = qmv.cur_column;	
			
		
		
		if (gcs_obj)
		{
			adj += qmc_gcs(gcs_obj,"padding-left","paddingLeft");
			adj += qmc_gcs(gcs_obj,"padding-right","paddingRight");
			adj += qmc_gcs(gcs_obj,"border-left-width","borderLeftWidth");
			adj += qmc_gcs(gcs_obj,"border-right-width","borderRightWidth");
		}
		
		qmv.pointersizer_value -= adj;
		
		if (qmv.pointersizer_value>0)
		{
			if (qmv.pointersizer_type == "container_leftright")
				qmv_show_dialog("subwidth");
			else if (qmv.pointersizer_type == "column_leftright")
				qmv_show_dialog("columnwidth");
			else if (qmv.pointersizer_type == "container_updown")
				qmv_show_dialog("subheight");
			else if (qmv.pointersizer_type == "column_updown")
				qmv_show_dialog("columnheight");
		}
		

	}


	qmv.pointersizer_moved = false;
	qmv.pointersizer_mdown = false;
	
	targ.style.cursor = "";
	qm_kille(e);
}

function qmv_pointer_sizer_click(e)
{
	qm_kille(e);
	return false;
}

function qmv_pointer_sizer_doubleclick(e)
{
	
	qm_kille(e);
	return false;
}

function qmv_delete_pointer_objects(id)
{


	qmv.pointer[id] = null;
	qmv.c_pointer[id] = null;
	qmv.q_pointer[id] = null;
	
}


function qmv_create_pointer(a,is_container,is_column)
{

	var pfix = '';
	if (is_container)
		pfix = "c_";
	if (is_column)
		pfix = "q_";
		
	if (!qmv[pfix+"pointer"][a.id])
	{
		
		qmv[pfix+"pointer"][a.id] = new Object();
		var c = document.createElement("SPAN");
		c.style.display = "none";
		c.style.position = "absolute";
		c.style.zIndex = 999999999;
		c.style.fontSize = "1px";
		c.isqmv = 1;
		c.isselector=1;
		c.style.width = "1px";
		c.style.height = "1px";
		
		
		var scolor = '255,0,0,.8';
		var bw = 1;
		var st = "dashed";
		if (is_container || is_column)
		{
			if (is_column)
				scolor = '0,153,51,1';
			else
				scolor = '0,51,201,1';
				
			bw=1;
			st = "dashed";
		}
		
		var iss = "width:1px;height:1px;position:absolute;border-color:rgba("+scolor+");font-size:1px;border-style:"+st+";"
		var ihp = '';
		
		ihp += '<span top=1 style="border-width:'+bw+'px 0px 0px 0px;'+iss+'"></span>';
		ihp += '<span bottom=1 style="border-width:'+bw+'px 0px 0px 0px;'+iss+'"></span>';
		ihp += '<span left=1 style="border-width:0px 0px 0px '+bw+'px;'+iss+'"></span>';
		ihp += '<span right=1 style="border-width:0px 0px 0px '+bw+'px;'+iss+'"></span>';
		c.innerHTML = ihp;
		
		
		if (is_container || is_column)
		{
			
			//create the left right sizer
			var sp = document.createElement("SPAN");
			sp.style.width = 21+"px";
			sp.style.height = 11+"px";
			
			if (is_container)
			{
				sp.style.backgroundImage = 'url('+qmv.base+'images/sizer_leftright.gif)';
				sp.style.top = "-11px";
			}
			else if (is_column)	
			{
				sp.style.backgroundImage = 'url('+qmv.base+'images/sizer_g_leftright.gif)';
				sp.style.top = "0px";	
			}
				
			sp.style.display = "block";
			sp.style.position = "absolute";
			sp.setAttribute("sizer_leftright",1);
			
			if (is_container)
				sp.qmvattype = "container_leftright";
			else if (is_column)
				sp.qmvattype = "column_leftright";
			
			
			if (sp.attachEvent)
			{
				sp.attachEvent("onmousedown",qmv_pointer_sizer_down);
				sp.attachEvent("onmousemove",qmv_pointer_sizer_move);
				sp.attachEvent("onmouseup",qmv_pointer_sizer_up);
				sp.attachEvent("onclick",qmv_pointer_sizer_click);
				sp.attachEvent("ondblclick",qmv_pointer_sizer_doubleclick);
			}
			else if (sp.addEventListener)
			{
				sp.addEventListener("mousedown",qmv_pointer_sizer_down,false);
				sp.addEventListener("mousemove",qmv_pointer_sizer_move,false);
				sp.addEventListener("mouseup",qmv_pointer_sizer_up,false);
				sp.addEventListener("click",qmv_pointer_sizer_click,false);
				sp.addEventListener("dblclick",qmv_pointer_sizer_doubleclick,false);
			}
			
			
			c.appendChild(sp);
			
			
			//create the up down sizer
			sp = document.createElement("SPAN");
			sp.style.width = 11+"px";
			sp.style.height = 21+"px";
			
			if (is_container)
			{
				sp.style.backgroundImage = 'url('+qmv.base+'images/sizer_b_updown.gif)';
				sp.style.top = "-11px";
			}
			else if (is_column)	
			{
				sp.style.backgroundImage = 'url('+qmv.base+'images/sizer_g_updown.gif)';
				sp.style.top = "0px";	
			}
				
			sp.style.display = "block";
			sp.style.position = "absolute";
			sp.setAttribute("sizer_updown",1);
			
			if (is_container)
				sp.qmvattype = "container_updown";
			else if (is_column)
				sp.qmvattype = "column_updown";
			
			
			if (sp.attachEvent)
			{
				sp.attachEvent("onmousedown",qmv_pointer_sizer_down);
				sp.attachEvent("onmousemove",qmv_pointer_sizer_move);
				sp.attachEvent("onmouseup",qmv_pointer_sizer_up);
				sp.attachEvent("onclick",qmv_pointer_sizer_click);
				sp.attachEvent("ondblclick",qmv_pointer_sizer_doubleclick);
			}
			else if (sp.addEventListener)
			{
				sp.addEventListener("mousedown",qmv_pointer_sizer_down,false);
				sp.addEventListener("mousemove",qmv_pointer_sizer_move,false);
				sp.addEventListener("mouseup",qmv_pointer_sizer_up,false);
				sp.addEventListener("click",qmv_pointer_sizer_click,false);
				sp.addEventListener("dblclick",qmv_pointer_sizer_doubleclick,false);
			}
			
			
			c.appendChild(sp);
			
		}
		else
		{
			c.onclick = function(e)
			{
				
				
				e = e || event;
				if (e.button==0)
				{
					qm_oo(new Object(),qmv.cur_item)
					qm_kille(e);
				}
			};
			
			c.ondblclick = function(e)
			{
				
				if (qmv.cur_item && qmv.cur_item.tagName && qmv.cur_item.tagName!="A")
				{
					if (qmv.cur_item.className && qmv.cur_item.className.indexOf("qmdivider")+1)
						qmv_context_cmd(e,'divider_styles');
					
					qm_kille(e);
					return;
				}	

				qmv_show_dialog("url",document.getElementById("qmv_editurl_field"));
				qm_kille(e);
			}
			
			c.onmouseover = function(e)
			{
				
				//qm_image_switch(qmv.cur_item);
				
			}
				

			c.oncontextmenu = function(e)
			{
				e = e || event;
				qmv_show_context(e,"menuitem",qmv.cur_item);
			}
		}

		
		a.insertBefore(c,a.firstChild);
		qmv[pfix+"pointer"][a.id].a = c;
		
	}

}


function qmv_design_menu2(b)
{

	qmv_create_pointer(b);
	qmv_create_pointer(b,true);
	qmv_create_pointer(b,false,true);
	
	b.onclick = null;  //cancels the event placed here for onclick=main
		
	if (b.addEventListener)
		b.addEventListener("click",qmv_container_click,false);
	
	
	b.oncontextmenu = function(event)
	{
		
		var targ = event.srcElement || event.target;
		qmv_container_click_2(targ);
		qmv_show_context(event,"main_container",null,null,null,null,this);
		qm_kille(event);
		
	}
	
	var a = b.getElementsByTagName("A");
	for (var j=0;j<a.length;j++)
	{
		
		if (!a[j].qmmi) continue;
		
		a[j].oncontextmenu = function(e)
		{
			qmv_show_context(e,"menuitem",this);
			
			qm_kille(e);
			return false;
		}
				
		a[j].ondblclick = function(event)
		{
			qmv_show_dialog("url",document.getElementById("qmv_editurl_field"));
			qm_kille(event);
		}
	
		if (!isNaN(parseInt(a[j].qmts)))
			qmv.ms_show_timer[b.id] = a[j].qmts;
		else
			qmv.ms_show_timer[b.id] = 0;

		a[j].qmts = 0;
		
				
		a[j].onclick=function(event)
		{
			
			e = event || window.event;
			if (e.button==0)
				qm_oo(event,this);
				
		}

		a[j].onmouseover = qmv_visual_design_menu_item_hover_handle;	
		
		
		//removes the keyboard navigation add-on
		if (a[j].addEventListener)
			a[j].removeEventListener("keypress",qm_kb_press,true);
		
			
	
		//qmv_evt_add_hover_item_in_visual_event(a[j]);


	}


	a = b.getElementsByTagName("DIV");
	for (var j=0;j<a.length;j++)
	{

		if (qmad.br_ie)
		{

			a[j].onselectstart = function(e)
			{
				e = e || event;

				qm_kille(e);
				return false;
			}

		}
		
		if (qmad.br_ie)
			a[j].ondragstart = function(){event.returnValue=false;event.cancelBubble = true;return false;}
		
		if (a[j].idiv)
			qmv_attach_container_events(a[j]);	

	}


	a = b.getElementsByTagName("SPAN");
	for (var j=0;j<a.length;j++)
	{
		
		a[j].qmts = 0;
		a[j].onmouseover = qmv_visual_design_menu_item_hover_handle;
				
		if (a[j].className.indexOf("qmdivider")+1)
		{
			qmv_attach_divider_events(a[j]);
		}
		else if (a[j].className.indexOf("qmtitle")+1)
		{
			qmv_attach_title_events(a[j]);
		} 
		else if (a[j].className.indexOf("qmcbox")+1)
		{
			qmv_attach_cbox_events(a[j])
		} 
		else if (a[j].getAttribute("isibulletcss"))
		{
			qmv_add_bullet_css_events(a[j]);
		}
		else if (a[j].getAttribute("isibullet"))
		{
			qmv_add_bullet_events(a[j]);
		}	

	}
	
	
	a = b.getElementsByTagName("DL");
	for (var j=0;j<a.length;j++)
	{
		if (a[j].className && a[j].className.indexOf('qmml')+1)
		{
			
			qmv_attach_column_container_events(a[j]);
		}
		
	}
	
}




function qmv_visual_design_menu_item_hover_handle(event)
{
	
	var o=this;
	
	if (o.tagName!="A" && !o.qmmi) 
	{
		while(o && (o=o[qp]) && !qm_a(o))
		{if (o.qmmi) break;}
	}
	
		
	qm_hhovshow(event,o);
	clearTimeout(qm_tt);qm_tt=null;qm_la=null;qm_kille(event);
	
	qm_kille(event);
}

