function qmv_attach_column_container_events(a)
{
	a.onclick = function(event)
	{
		qmv_attach_column_container_events2(event);
		qmv_filter_update_automatically('column');
		
		qm_kille(event);
	}

	a.oncontextmenu = function(event)
	{
		qmv_attach_column_container_events2(event);
		qmv_show_context(event,"column_container",null,null,null,null,this);		
		qm_kille(event);
	}

}

function qmv_attach_column_container_events2(event)
{
	var targ = event.srcElement || event.target;
		
	
	if (qmv_get_set_selected_item_from_column(targ))
		qmv_hide_pointer("qm"+qmv.id,true,false,true);
	else
		qmv_position_pointer(true);
		
	qmv_hide_pointer("qm"+qmv.id,true,false,true);		

}

function qmv_attach_container_events(obj)
{
	
	if (obj.className.indexOf('qmsub')==-1)
	{
		if (obj.className)
			obj.className+= " qmsub";
		else
			obj.className = "qmsub";
	}
	
	obj.onmouseover=function(event)
	{
		
		if (window.qmad && qm_lh)
		{
			var ha = qm_lh;
			if (qmad.bhoverhide) eval(qmad.bhoverhide);
			qm_lh=null;
		}
		
		qm_kille(event);
	}
	
	obj.oncontextmenu = function(event)
	{
		
		var targ = event.srcElement || event.target;
		qmv_container_click_2(targ);
		
		qmv_show_context(event,"sub_container",null,null,null,null,this);
		
		qm_kille(event);
		
	}
	
	if (obj.attachEvent)
	{
		obj.attachEvent("onmousedown",qmv_container_mouse_down);
		obj.attachEvent("onmousemove",qmv_container_mouse_move);
		obj.attachEvent("onmouseup",qmv_container_mouse_up);
		obj.attachEvent("onclick",qmv_container_click);
	}
	else if (obj.addEventListener)
	{
		obj.addEventListener("mousedown",qmv_container_mouse_down,false);
		obj.addEventListener("mousemove",qmv_container_mouse_move,false);
		obj.addEventListener("mouseup",qmv_container_mouse_up,false);
		obj.addEventListener("click",qmv_container_click,false);
	}

}

function qmv_get_set_selected_item_from_container(a,b)
{
	
	var pa = qmv.cur_item;
	while (pa && !pa.idiv) pa = pa[qp];
	
	if (pa!=a)
	{
		var fa = qmv_container_get_first_item_or_parent(a,b);
		qm_oo(new Object(),fa);
	}
	
}

function qmv_get_set_selected_item_from_column(a)
{
	
	var pa = qmv.cur_item;
	
	
	while (pa && pa[qp] && !pa[qp].idiv) pa = pa[qp];
	
	//if the column is new switch it
	if (pa!=a)
	{
	
		var fa = qmv_container_get_first_item_or_parent(a,null,true);
		
		if (fa)
		{
			qm_oo(new Object(),fa);
			return true;
		}
		else
			return false;
		
	}
	
}



function qmv_container_click(e)
{
	
	var targ = e.srcElement || e.target;
	qmv_container_click_2(targ);
	
	qmv_filter_update_automatically('sub');
	
	qm_kille(e);

}

function qmv_container_click_2(targ)
{
	var item_clicked;
	while(targ.tagName!="DIV" && !targ.idiv)
	{
		if (targ.qmmi) item_clicked=true;
		targ=targ[qp];
	}
	
	if (!item_clicked && targ!=qmv.cur_sub)
		qmv_get_set_selected_item_from_container(targ,qmv.cur_sub);
	else
		qmv_position_pointer(true);
		
	qmv_hide_pointer("qm"+qmv.id,true);
}


function qmv_container_get_first_item_or_parent(a,b,get_column)
{

	
	if (b)
	{
		var ni = b.idiv;
		if (ni)
		{
			
			while (b=b[qp])
			{
				if (b.idiv)
				{	
					if (b==a)
						return ni;
					else
						break;
				}
				
				if (qm_a(b)) break;
		
			}
				
		}
		
	}
	
	
	var ch = a.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		if (ch[i])
		{
			
			if (ch[i].qmmi)
			{
				return ch[i];	
			}
			else if (ch[i].tagName=="DL")
			{
				var dds = ch[i].childNodes;
				for (var j=0;j<dds.length;j++)
				{
					if (dds[j] && dds[j].tagName=="DD")
					{
						var ddi=dds[j].childNodes;
						for (var k=0;i<ddi.length;k++)
						{
							if (ddi[k] && ddi[k].qmmi)
							{
								
								return ddi[k];
							}
						}
					}
				}
			}
			else if (ch[i].tagName=="DD")
			{
				
				var ddi=ch[i].childNodes;
				for (var k=0;k<ddi.length;k++)
				{
					if (ddi[k] && ddi[k].qmmi)
					{
						return ddi[k];
					}
				}
			
			}
		}
	}
	
}


function qmv_container_mouse_down(e)
{

	e = e || event;
	
	if (e.button==0)
	{
		qmv_hide_context();
		
		
		var targ = e.srcElement || e.target;
		qmv.container_rtarg = targ;
		qmv.container_itarg = null;		
			
		//while(targ.tagName!="DIV" && !targ.idiv)
		while(!targ.idiv)
		{
			if (targ.qmmi) qmv.container_itarg=targ;
			targ=targ[qp];
		}
		
		if(qmv.addons.tree_menu["on"+qmv.id])	
		{
			qm_kille(e);
			return false;
		}

		qmv.container_obj = targ;
				
		qmv.container_mdown = true;
		qmv.container_prev_x = e.screenX;
		qmv.container_prev_y = e.screenY;
		qmv.orig_x = e.screenX;
		qmv.orig_y = e.screenY;


		var n;
		if (n = targ.hasshadow)
		{
			n.origleft = n.style.left;
			n.origtop = n.style.top;
		}	
		
		targ.style.cursor = "move";

	}
	
	qm_kille(e);
	return false;
}


function qmv_container_mouse_move(e,src)
{

	e = e || event;
	
	var targ;
	if (!qmv.container_moved)
	{
		var targ = e.srcElement || e.target;
		if (src)
			targ = src;
		else
			while(targ.tagName!="DIV" && !targ.idiv) targ=targ[qp];
	}
	else
		targ = qmv.container_obj;


	if (qmv.container_mdown)
	{
	
		var m = qmv.container_obj;
	
		var tx = qmv.orig_x-e.screenX;
		var ty = qmv.orig_y-e.screenY;
		if (qmv.container_moved || Math.abs(tx)>5 || Math.abs(ty)>5)
		{
	
			qmv_hide_pointer("qm"+qmv.id);
		
			var xdif = qmv.container_prev_x-e.screenX;
			var ydif = qmv.container_prev_y-e.screenY;
				
			var ml =qm_lib_get_computed_style(m,"margin-left","marginLeft");
			if (ml) ml = parseInt(ml);
			if (!ml || isNaN(ml)) ml = 0;

			var mt = qm_lib_get_computed_style(m,"margin-top","marginTop");
			if (mt) mt = parseInt(mt);
			if (!mt || isNaN(mt)) mt = 0;

						
			m.style.marginLeft = (ml-xdif)+"px";
			m.style.marginTop = (mt-ydif)+"px";
			
			var n;
			
			if (n = targ.hasshadow)
			{
				n.style.top = (n.offsetTop-ydif)+"px";
				n.style.left = (n.offsetLeft-xdif)+"px";
			}

			qmv.container_prev_x = e.screenX;
			qmv.container_prev_y = e.screenY;

			qmv.container_moved = true;		
		
			qm_kille(e);
			return false;

		}
		
		if (qmv.container_obj.setCapture)
			qmv.container_obj.setCapture(true);
		
	}
}


function qmv_container_mouse_up(e)
{

	e = e || event;
	var targ = e.srcElement || e.target;
	var item_clicked;
	
	
	while(targ.tagName!="DIV" && !targ.idiv)
	{
		if (targ.qmmi) item_clicked=true;
		targ=targ[qp];
	}
	
	
	if (qmv.container_moved)
	{
		
		var m = qmv.container_obj;
		
		if (m!=qmv.cur_sub)
		{
			if (qmv.container_itarg)
			{
				qm_oo(new Object(),qmv.container_itarg);
			}
			else
			{
				if (!item_clicked)
				{
					
					var fc = qmv_container_get_first_item_or_parent(m,qmv.cur_sub);
					if (fc)
						qm_oo(new Object(),fc);
				
				}
			}	
		}
		
		qmv.container_pos = qmv_get_combined_edge_value(m.style.marginTop,m.style.marginRight,m.style.marginBottom,m.style.marginLeft)
				
		qmv_show_dialog("subposition");
		qmv.container_rtarg = null;
		
		qmv_position_pointer(true);
	
	}

	
	if (qmv.container_obj && qmv.container_obj.releaseCapture)
		qmv.container_obj.releaseCapture(true);
	
	qmv.container_moved = false;
	qmv.container_mdown = false;
	targ.style.cursor = "";

}

function qmv_get_combined_edge_value(top,right,bottom,left)
{

	var ml = 0;
	if (left)
	{
		ml = parseInt(left);
		if (isNaN(ml)) ml = 0;
	}


	var mt = 0;
	if (top)
	{
		mt = parseInt(top);
		if (isNaN(mt)) mt = 0;
	}


	var mr = "0px";
	if (right) mr = right;

	var mb = "0px";
	if (bottom) mr = left;

	return mt+"px "+mr+" "+mb+" "+ml+"px";

}

