function qmv_edgemulti_synchronize(e,obj)
{

	var a = obj.getAttribute("inputid");
	if (a && (a=document.getElementById(a)))
	{

		var ca = new Object();
		ca.top = document.getElementById("qmvi_df_edge_top");
		ca.bottom = document.getElementById("qmvi_df_edge_bottom");
		ca.left = document.getElementById("qmvi_df_edge_left");
		ca.right = document.getElementById("qmvi_df_edge_right");

		for (var i in ca)
		{
			if (ca[i]!=a)
			{
				ca[i].value = a.value;
				var dtype = ca[i].getAttribute("dtype");
				if (dtype=="color")
					qmvi_set_dialog_color(a.value,document.getElementById("qmvi_df_edge_button_"+i));
			}
				
		}
	
	}
}

function qmv_colormulti_update_value(e,inp)
{

	if (inp.value)
	{
	
		var ca = new Object();
		ca.top = document.getElementById("qmvi_df_edge_top");
		ca.bottom = document.getElementById("qmvi_df_edge_bottom");
		ca.left = document.getElementById("qmvi_df_edge_left");
		ca.right = document.getElementById("qmvi_df_edge_right");

			
		var found,fvalue,fc=0;
		for (var i in ca)
		{
			if (ca[i].value)
			{
				fc++;
				found = i;
				fvalue = ca[i].value;
			}
		}
		
		if (fc==1)
		{
			for (var i in ca)
			{
				if (i!=found)
				{
					ca[i].value=fvalue;
					qmvi_set_dialog_color(fvalue,document.getElementById("qmvi_df_edge_button_"+i));
				}
			}
		}
	}

}

