function qmv_transform_init(qmd)
{

	var tfobj = new Object();
	tfobj.scaleX = document.getElementById("qmvi_df_edge_scalex");
	tfobj.scaleY = document.getElementById("qmvi_df_edge_scaley");
	tfobj.skewX = document.getElementById("qmvi_df_edge_skewx");
	tfobj.skewY = document.getElementById("qmvi_df_edge_skewy");
	tfobj.translateX = document.getElementById("qmvi_df_edge_translatex");
	tfobj.translateY = document.getElementById("qmvi_df_edge_translatey");
	tfobj.rotate = document.getElementById("qmvi_df_edge_rotate");

	var val = qmd.owner.value;
	if (val)
	{
		val = val.split(" ");
		for (var i=0;i<val.length;i++)
		{
			if (val[i])
			{
				var sp = val[i].split("(");
				if (sp.length>1)
				{
					if (sp[1])
					{
						sp[1] = sp[1].replace(/\)/g,"");
						
						if (sp[0]=="scale")
						{
							tfobj[sp[0]+"X"].value = sp[1];
							tfobj[sp[0]+"Y"].value = sp[1];
						}
						else if (tfobj[sp[0]])
							tfobj[sp[0]].value = sp[1];
					}
					
				}
			}
		}
	
	}

}


function qmv_boxshadow_init(qmd,type)
{

	qmv.boxshadow_presets = new Object();
	qmv.boxshadow_presets.type = type;
	var s = qmv.boxshadow_presets;
		
	var xoffset = document.getElementById("qmvi_df_edge_xoffset");
	var yoffset = document.getElementById("qmvi_df_edge_yoffset");
	var blurdistance = document.getElementById("qmvi_df_edge_blurdistance");
	var color = document.getElementById("qmvi_df_edge_color");
	
	s.val_xoffset = xoffset;
	s.val_yoffset = yoffset;
	s.val_blurdistance = blurdistance;
	s.val_color = color;
	

	//set the presets...
	if (type=="boxshadow")
	{
		s.preset1 = "4px 4px 2px #666666";
		s.preset2 = "-4px 4px 2px #666666";
		s.preset3 = "4px 4px 10px #666666";
		s.preset4 = "-4px 4px 10px #666666";
		s.preset5 = "0px 0px 5px #666666";
		s.preset6 = "0px 0px 15px #666666";
		s.preset7 = "0px 0px 20px #444444";
	}
	else
	{
		s.preset1 = "2px 2px 2px #666666";
		s.preset2 = "-2px 2px 2px #666666";
		s.preset3 = "2px 2px 5px #666666";
		s.preset4 = "-2px 2px 5px #666666";
		s.preset5 = "0px 0px 3px #666666";
		s.preset6 = "0px 0px 7px #666666";
		s.preset7 = "0px 0px 12px #444444";
	}
	
	var vals = qmv_lib_parse_boxshadow_values(qmd.owner.value);
	s.custom = qmd.owner.value;
	
	xoffset.value = vals.xoffset;
	yoffset.value = vals.yoffset;
	blurdistance.value = vals.blurdistance;
	color.value = vals.color;
	
	if (vals.color)  qmvi_set_dialog_color(vals.color,document.getElementById("qmvi_df_edge_button_color"));
	
	if (xoffset.value || yoffset.value || blurdistance.value || color.value)
		qmv_boxshadow_update_preview_box();
	else
	{
		var bpre = document.getElementById("qmvi_boxshadowdialog_preset");
		bpre.value = "preset3";
		bpre.onchange();
	}

}


