function qmv_pubgen_all_external(force_external,quick_publish_inline,is_account_locked_save,spec_id)
{

	
	var wt = "";

	if (!quick_publish_inline)
	{
		
		wt += qmv_pubgen_css(false,true,null,null,parseInt(spec_id),null,true);
		wt += qmv_pubgen_ie8_gradient_filter_undo();
		wt = wt.replace(/\'/g,"\\'");
		wt = '/*Compressed CSS Styles*/\r\n'+"document.write('"+wt+"');";

		wt += "\r\n";
		wt += "\r\n";

		wt += qmv_pubgen_javascript(true,null,spec_id,true);


		wt += "/*Compressed Menu Structure*/\r\n";
		wt += qmv_pubgen_structure(force_external,null,null,null,spec_id,false,false,false,true);


	}
	else
	{
		
		
		wt += qmv_pubgen_css(false,false,false,false,parseInt(spec_id),false,true);
		wt += qmv_pubgen_ie8_gradient_filter_undo();
		wt += qmv_pubgen_javascript(false,false,false,true);

		if (is_account_locked_save)
			wt += '<!--qm_endsect1-->';



		wt += qmv_pubgen_structure(null,null,null,true,qmv.id+"l",false,false,false,true);	
				
		
	}

	return wt;

}


function qmv_pubgen_ie8_gradient_filter_undo()
{
	var ih = '';
	if (qmv.publish_ie8_gradient_fix && qmv.publish_ie8_gradient_fix.length>0)
	{
		ih += '<!--[if gte IE 9]><style type="text/css">';
		
		for (var i=0;i<qmv.publish_ie8_gradient_fix.length;i++)
		{
			var r = qmv.publish_ie8_gradient_fix[i];
			ih += r+'{filter:none;}';
		}
		
		ih += '</style><![endif]-->';
	}
	
	return ih;
}



function qmv_pubgen_get_body_top()
{
	var rt = "\r\n";
	var wt = "";
	
	wt += '<!--[START-QMBT]-->'+rt;
	wt += '<body style="margin:40px;background-color:'+qmvi_change_design_bg_color(true)+';">'+rt;
	wt += '<!--[END-QMBT]-->';
	
	return wt;
}


function qmv_savegen(is_component,is_preview,css_only)
{
	
	var wt = "";
	var rt = "\r\n";
	
	wt += '<!DOCTYPE html>';
	wt += rt;
	wt += '<html><head><meta http-equiv="X-UA-Compatible" content="IE=Edge"/><meta http-equiv="Content-Type" content="text/html; charset=utf-8"/><title>NodeFire Save Document</title>';
	
	//set the top and left to their default positions
	if (is_preview)
	{
		wt += '<style type="text/css">body .qmmc {top:auto !important;left:auto !important;}</style>';
		wt += '<scr'+'ipt type="text/javascript">qm_single="prhrdwei";</scr'+'ipt>';
	}
	
	
	wt += rt;
	wt += rt;
	wt += '<!-- *** NodeFire copyright (c) 2012, OpenCube Inc. All Rights Reserved. - www.kirantechnologies.com';
	wt += rt;
	wt += rt;

	if (is_component)
	{

		wt += '\t-Manually edit this menus settings using a plain text editor.  To visually edit click the link above the menu'
		wt += rt;
		wt += '\t while viewing this page in your browser.'

	}
	else
	{
		if (parent && parent.is_chrome)
		{
			wt += '\t-NodeFire may be manually customized by editing this document, or open this web page / menu'
			wt += rt;
			wt += '\t with the NodeFire Visual Interface (File - Open).'
		}
		else
		{


			wt += '\t-NodeFire may be manually customized by editing this document, or open this web page using'
			wt += rt;
			wt += '\t a browser of your choosing to access the visual interface.'

		}
	}

	wt += rt;
	wt += rt;
	wt += '-->';	

	wt += rt;
	wt += rt;
	wt += rt;

	wt += '<!--[START-QMH1'+qmv.id+'-INSERT]-->';
	wt += rt;
	
	wt += qmv_pubgen_css(false,undefined,undefined,undefined,undefined,is_preview);
	wt += qmv_pubgen_ie8_gradient_filter_undo();
	if (!css_only)
	{
		if (is_preview)
			wt += qmv_pubgen_javascript(false,true);
		else
			wt += qmv_pubgen_javascript(false);
	}

	wt += rt;
	wt += '<!--[END-QMH1'+qmv.id+'-INSERT]-->';
	
	wt += '</head>'
	wt += rt;
	wt += rt;
	wt += qmv_pubgen_get_body_top();
	wt += rt;

	if (!is_preview && !(parent && parent.is_chrome))
	{
		wt += rt;
		wt += '<!--Open Visual Interface Button-->'+rt;
		wt += '<a style="font-size:13px;color:#444444;font-family:arial;text-decoration:none;display:block;margin-bottom:25px;" id="qmv_open_visual_interface" href="javascript:if (qm_s3){window.name=\'qm_open\';window.location = window.location.href;}else{var qmnw = window.open(window.location.href,\'qm_open\',\'scrollbars=no,location=no,status=yes,menu=no,toolbar=no,resizable=yes\');if (window.focus) {qmnw.focus()}}"><span style="color:#dd3300;">[+]</span> Open Visual Interface</a>'+rt;
		wt += rt;
	}

	wt += rt;
	wt += rt;
	wt += rt;
	wt += '<!--[START-QM'+qmv.id+'-INSERT]-->';
	wt += rt;
	wt += qmv_pubgen_structure(false,true,rt+rt+rt+rt+"<br><br><br><br><br><br><br>"+rt+rt+rt+rt,true,null,css_only,is_preview);
	wt += rt;
	wt += '<!--[END-QM'+qmv.id+'-INSERT]-->';
	wt += rt;
	wt += rt;
	wt += rt;


	if (is_preview)
	{
		
		var sp = '\r\n';
		wt += '<script type="text/javascript">';
	
		if (qmv.is_chrome)
			wt += 'var NFLB_CHROME=1;';
			
		wt+='if (document.attachEvent)';
		wt+='document.attachEvent("oncontextmenu",qmvp_kill_rightclick);';
		wt+='else if (document.addEventListener)'
		wt+='document.addEventListener("contextmenu",qmvp_kill_rightclick,true);';

		wt+='if (window.attachEvent)'+sp;
		wt+='window.attachEvent("onload",qmvp_kill_links);'+sp;
		wt+='else if (window.addEventListener)'+sp
		wt+='window.addEventListener("load",qmvp_kill_links,true);'+sp;


		wt += 'function qmvp_kill_rightclick(e)'+sp;		
		wt += '{'+sp;

			wt += 'e.cancelBubble = true;'+sp;
			wt += 'if (e.stopPropagation)'+sp;
			wt += 'e.stopPropagation();'+sp;
			wt += 'if (e.preventDefault)'+sp;
			wt += 'e.preventDefault();'+sp;
			wt += 'e.returnValue = false;'+sp;
			wt+='return false'+sp;

		wt += '}'+sp;

		
		wt += 'function qmvp_kill_links(e)'+sp;		
		wt += '{'+sp;
		
			wt+='var ats = document.getElementsByTagName("A");'+sp;
			wt+='for (var i=0;i<ats.length;i++)'+sp;
			wt+='{'+sp;
	
				wt += 'if (!ats[i].getAttribute("rel"))'+sp;
				wt+='{'+sp;
					wt+='if (ats[i].attachEvent)'+sp;
					wt+='ats[i].attachEvent("onclick",qmvp_kill_links2);'+sp;
					wt+='else if (ats[i].addEventListener)'+sp;
					wt+='ats[i].addEventListener("click",qmvp_kill_links2,true);'+sp;

					wt += 'if (ats[i].getAttribute("href") && (ats[i].getAttribute("href").toLowerCase()=="javascript:void(0);" || ats[i].getAttribute("href").toLowerCase()=="javascript:void(0)"))'+sp;
						wt += 'ats[i].setAttribute("slink","");'+sp;
					wt += 'else '+sp;
						wt += 'ats[i].setAttribute("slink",ats[i].getAttribute("href",2));'+sp;

					wt += 'ats[i].setAttribute("href","javascript:void(0);");'+sp;
					wt += 'ats[i].setAttribute("target","");'+sp;
				wt+='}'+sp;
			wt+='}'+sp;
		wt += '}'+sp;
		

		wt += 'function qmvp_kill_links2(e,msg)'+sp;		
		wt += '{'+sp;
		
		
			wt += 'e=e || window.event;'+sp;
			wt += 'var ta = e.srcElement || e.target;'+sp;
			wt += 'while (ta && ta.tagName!="A"){ta=ta.parentNode;}';
			
			wt += 'if(ta.className.indexOf("qmparent")+1)'+sp;
				wt += 'return;'+sp;			
	
			wt += 'var sl = "";'+sp;
			wt += 'if (msg) sl = msg;'+sp;
			wt += 'else sl = ta.getAttribute("slink");'+sp;

			
			wt += 'if (sl)'+sp;
				wt += 'alert("Links are disabled during preview.  Save or publish your menu to test your links.\\r\\n\\r\\nLink: "+sl+"");'+sp;
				
			
			wt += 'e.cancelBubble = true;'+sp;
			wt += 'if (e.stopPropagation)'+sp;
			wt += 'e.stopPropagation();'+sp;
			wt += 'if (e.preventDefault)'+sp;
			wt += 'e.preventDefault();'+sp;
			wt += 'e.returnValue = false;'+sp;
			wt+='return false'+sp;


		wt += '}'+sp;
		
		
		wt += '</script>'+sp;

	}
	

	

	wt += '</body>';
	wt += rt;
	wt += '</html>';

	return wt;


}


