function qmv_input_code_ask_width(vert,width)
{

	

	if (vert)
	{
		
		if (!width)
		{
			var def = qmv_find_update_tree_value("css","#qm[i]","width",null,true);
			if (def=="" || (def && def.toLowerCase().indexOf("auto")+1)) def = "200px";

			qmv_show_dialog("question-okdismiss-input",vert,"<b>Specify Main Container Width</b><br><br>Without a width defined the main menu will stretch to 100% of its containers size. This value is further cusomizable under CSS Styles --&gt; Main --&gt; Container.<br><br>Main Container Width",300,"qmv_input_code_ask_width(qmd.owner,true)",null,null,def);	

		}
		else
		{
			var val = document.getElementById("qmvi_ok_input").value;
			if (val)
			{		
				var update_inp = qmv_find_update_tree_value("css","#qm[i]","width",val,false,true);
				if (update_inp)
					qmv_evt_update_tree_value(update_inp);
			}
		}

	}
	else
	{
		if (!width)
		{
			var def = qmv_find_update_tree_value("css","#qm[i]","width",null,true);
			if (def)
			{
				qmv_show_dialog("question-yesno",vert,"A width is defined for the main container which may cause the items to wrap when aligned horizontally. This setting is accessible under CSS Styles --> Main --> Container.<br><br><b>Would you like to remove the width now?</b>",450,"qmv_input_code_ask_width(qmd.owner,true)");	
			}

		}
		else
		{
			var update_inp = qmv_find_update_tree_value("css","#qm[i]","width","",false,true);
			if (update_inp)
				qmv_evt_update_tree_value(update_inp);	
		
		}

	}
		

}




