function qmv_evt_apply_plus(e,a,cname)
{


	if (!cname)
		cname = a.getAttribute("cname");

	if (cname=="insert_title")
	{
		qmv_insert_spanitem("title");
		
	}
	if (cname=="insert_title_after")
	{
		qmv_insert_spanitem("title",null,null,true);
		
	}
	else if (cname=="insert_divider")
	{
		qmv_insert_spanitem("divider");
	}
	else if (cname=="insert_divider_after")
	{
		qmv_insert_spanitem("divider",null,null,true);
	}
	else if (cname=="insert_cbox")
	{
		qmv_insert_spanitem("cbox");
	}
	else if (cname=="insert_cbox_after")
	{

		qmv_insert_spanitem("cbox",null,null,true);

	}	
	else if (cname=="insert_divider_global")
	{

		qmv_show_dialog("applydividers");

	}
	else if (cname=="classnames_apply_remove_globally")
	{
		qmv_show_dialog("applyclassnames");
	
	}
	else if (cname=="apply_striping_individually")
	{
		qm_arc("qmstripe",qmv.cur_item,true);

	}
	else if (cname=="remove_striping_individually")
	{

		qm_arc("qmstripe",qmv.cur_item);
	}
	else if (cname=="apply_striping_globally")
	{
		qmv_show_dialog("applystripes");

	}
	else if (cname=="ritem_mitem_styles")
	{
		qmv_ritem_underlying_styles(null,"main");
	}
	else if (cname=="ritem_sitem_styles")
	{
		qmv_ritem_underlying_styles(null,"sub");
	}
	else if (cname=="ritem_remove_mborders")
	{
		qmv_ritem_remove_main_styles("main");
	}
	else if (cname=="ritem_remove_sborders")
	{

		qmv_ritem_remove_main_styles("sub");

	}
	else if (cname=="ritem_individual")
	{


		if (!qmv.addons.ritem["on"+qmv.id])
			qmv_context_cmd(e,"addon_ritem");
		
		qm_arc("qmrounditem",qmv.cur_item,true);
		qmv_update_all_addons();

	}
	else if (cname=="ritem_individual_remove")
	{
		qm_arc("qmrounditem",qmv.cur_item);
		qmv_update_all_addons();

		qmv_ritem_remove_warning();
		

	}
	else if (cname=="rcorner_blend")
	{
		if (!qmv.addons.round_corners["on"+qmv.id])
			qmv_show_dialog("alert",null,"Rounded sub corners must first be applied to your menu before the colors can be blended.",400);		
		else
			qmv_updatehandle_round_corner_show(null,null,null,null,null,true);
	}
	else if (cname=="custom_rule")
	{
		qmv_add_custom_css_rule(true)
	}	
	else if (cname=="apply_custom_class")
	{
		qmv_context_cmd(new Object(),"apply_custom_class");
		
	}	
	else if (cname=="pstate_add")
	{

		if (qmv.cur_item.tagName!="A")
		{

			qmv_show_dialog("alert", null, "Persistent states may be applied to menu links only, titles and dividers can't be set persistent.<br><br>First click on a menu item which acts as a link, then apply the test persistent state.",375);

		}
		else
		{
			qm_arc("qmpersistent",qmv.cur_item,true);

			var cb = document.getElementById("qmv_iadd_sopen_auto");
			if (!cb.checked)
			{
				cb.checked = true;
				qmv_evt_addremove_addon(new Object(),cb);
			}

		}

	}
	else if (cname=="pstate_remove")
	{

		qm_arc("qmpersistent",qmv.cur_item);

	}
	else if (cname=="pstate_remove_all")
	{

		var at = document.getElementById("qm"+qmv.id).getElementsByTagName("A");
		for (var i=0;i<at.length;i++)
			qm_arc("qmpersistent",at[i]);

	}
	else if (cname=="pstate_help")
	{

		qmv_show_dialog("help-persistent-state",null,"help-persistent_state.html");
	}
	else if (cname=="pstate_main_styles")
	{

		var a = qmv_find_rule_atag("#qm[i] .qmitem-m.qmpersistent")
		qmv_display_setbox(a,null,null,true,2);

		
	}
	else if (cname=="pstate_sub_styles")
	{

		var a = qmv_find_rule_atag("#qm[i] .qmitem-s.qmpersistent")
		qmv_display_setbox(a,null,null,true,2);
		
	}
	else if (cname=="hoverfill_trans")
	{

		qmv_updatehandle_hoverfill_show(true);
		
	}	
	else if (cname=="set_main_width")
	{
		
		qmv_input_code_ask_width(true);
		
	}
	else if (cname=="set_lev2_item_styles")
	{
		
		qmv_add_edit_show_custom_rule_styles("div#qm[i] .qmsub .qmsub a, ul#qm[i] .qmsub .qmsub a",true);
		
	}
	else if (cname=="set_lev2_container_styles")
	{
		
		qmv_add_edit_show_custom_rule_styles("div#qm[i] .qmsub .qmsub, ul#qm[i] .qmsub .qmsub",true);
		
	}
	else if (cname=="set_scroll_dimensions")
	{
		qmv_update_scroll_ask_width_height(null,null,true);
	}
	else if (cname=="showload_apply" || cname=="fixedwidth_apply")
	{

		var is_multi = false;
		if (qmv.cur_item[qp] && qmv.cur_item[qp].tagName=="DD" && qmv.cur_item[qp][qp] && qmv.cur_item[qp][qp][qp] && qmv.cur_item[qp][qp][qp].idiv)
			is_multi = true;
	
		if ((qmv.cur_item[qp] && qmv.cur_item[qp].idiv) || is_multi)
		{
			var apobj = qmv.cur_item[qp].idiv;
			if (is_multi)
				apobj = qmv.cur_item[qp][qp][qp].idiv;
		
			if (cname=="showload_apply")
			{
				qm_arc("qm-startopen",apobj,true);
				qmv_show_dialog("alert",null,"<b>Setting Applied:</b>  The selected sub menu will display by default when the menu first loads.<br><br>Note:  Multiple subs may not display by default with certain menu types.",450);		
			}
			else if  (cname=="fixedwidth_apply")
			{
				if (apobj = apobj.cdiv)
				{
					qm_arc("qm-fixedwidth",apobj,true);
					qmv_show_dialog("alert",null,"<b>Setting Applied:</b>  The selected sub menu will be sized according to the width you specify using inline or standard CSS settings.",450);	
				}
			}
				
			
			//qmv_load_item_extras_to_tree();

		}
		else
			qmv_show_dialog("alert",null,"The setting was not applied, first select a sub menu where you wish to apply the setting.",400);		
		

	}
	else if (cname=="showload_remove" || cname=="fixedwidth_remove")
	{
		var is_multi = false;
		if (qmv.cur_item[qp] && qmv.cur_item[qp].tagName=="DD" && qmv.cur_item[qp][qp] && qmv.cur_item[qp][qp][qp] && qmv.cur_item[qp][qp][qp].idiv)
			is_multi = true;
	
	
		if (((qmv.cur_sub && qmv.cur_sub.idiv) || is_multi) && (qmv.cur_sub.idiv.className.indexOf("qm-startopen")+1 || qmv.cur_sub.className.indexOf("qm-fixedwidth")+1))
		{
			var apobj = qmv.cur_item[qp].idiv;
			if (is_multi)
				apobj = qmv.cur_item[qp][qp][qp].idiv;
			
			if (cname=="showload_remove")
			{			
				qm_arc("qm-startopen",apobj);
				qmv_show_dialog("alert",null,"<b>Setting Removed:</b>  The selected sub menu will <b>not</b> be visible by default.",400);	
			}
			else if  (cname=="fixedwidth_remove")
			{
				if (apobj = apobj.cdiv)
				{
					qm_arc("qm-fixedwidth",apobj);
					qmv_show_dialog("alert",null,"<b>Setting Removed:</b>  The selected sub menu may have its width automatically calculated depending on the menu features used.",450);	
				}
			}
			//qmv_load_item_extras_to_tree();
		}
		else
			qmv_show_dialog("alert",null,"<b>Warning!</b> The setting was not found or has already been removed.",450);		


	}
	else if (cname=="mpsubs_apply" || cname=="mpsubs_remove")
	{

		var is_multi = false;
		if (qmv.cur_item[qp] && qmv.cur_item[qp].tagName=="DD" && qmv.cur_item[qp][qp] && qmv.cur_item[qp][qp][qp] && qmv.cur_item[qp][qp][qp].idiv)
			is_multi = true;
	
		if ((qmv.cur_item[qp] && qmv.cur_item[qp].idiv) || is_multi)
		{
			var apobj = qmv.cur_item[qp];
			if (is_multi)
				apobj = qmv.cur_item[qp][qp][qp];
		
			
			if (cname=="mpsubs_apply")
			{
				qm_arc("qm-match-parent-height",apobj,true);
				qm_mpsubheight_a(apobj);
				qmv_position_pointer(true);
							
				qmv_show_dialog("alert",null,"<b>Setting Applied:</b>  The selected sub menu will automatically match it's parent sub or main container height.",450);	
			
				var cb = document.getElementById("qmv_iadd_mpsub");
				if (!cb.checked)
				{
					cb.checked = true;
					qmv_evt_addremove_addon(new Object(),cb);
				}
			}
			else
			{
				
				qm_arc("qm-match-parent-height",apobj);
				apobj.style.height = "";
				qmv_position_pointer(true);
				
				qmv_show_dialog("alert",null,"<b>Setting Removed:</b>  The selected sub menu match height status was removed.",400);	
				
			}
			

		}
		else
		{
			if (cname=="mpsubs_apply")
				qmv_show_dialog("alert",null,"The setting was not applied, first select a menu item within the sub menu you wish to apply the match height to.",450);
			else
				qmv_show_dialog("alert",null,"The setting was not removed, first select a menu item within the sub menu you wish to remove the match height from.",450);
		}

	}
	else if (cname=="hautofit_apply" || cname=="hautofit_remove")
	{
	
		if (qmv.cur_sub.ch || qm_a(qmv.cur_sub) || cname=="mpsubs_remove")
		{
			if (cname=="hautofit_apply")
			{
			
				var cb = document.getElementById("qmv_iadd_hautofit");
				if (!cb.checked)
				{
					cb.checked = true;
					qmv_evt_addremove_addon(new Object(),cb);
				}
			
				if (!qm_a(qmv.cur_sub))
				{
					qm_arc("qm-horizontal-auto-fit",qmv.cur_sub,true);
					qmv_update_hautofit(false);
				}
				else
				{
					//it is the main
					var inp = qmv_find_update_tree_value("addon","hautofit","hautofit_main",true,false);
					qmv_evt_update_tree_value(inp);
				}
				
				
			}
			else
			{
				
				if (!qm_a(qmv.cur_sub))
				{
					
					if (qmad["qm"+qmv.id].hautofit_subs)
					{	
						qm_arc("qm-horizontal-auto-fit",qmv.cur_sub);
					
						var inp = qmv_find_update_tree_value("addon","hautofit","hautofit_subs",false,false);
						qmv_evt_update_tree_value(inp);	
					}
					else
					{
						
						qm_arc("qm-horizontal-auto-fit",qmv.cur_sub);
						qmv_update_hautofit(false);
						
					}
				}
				else
				{
					var inp = qmv_find_update_tree_value("addon","hautofit","hautofit_main",false,false);
					qmv_evt_update_tree_value(inp);
					
				}
				
			}
			
			qmv_position_pointer();
			
		}
		else
		{
			
			qmv_show_dialog("alert",null,"This setting can only be applied to horizontally oriented main or sub menu items.",450);
			
		}

	}
	else if (cname=="sopen_addon")
	{
		
		var a = document.getElementById("qmv_iadd_sopen");
		qmv_display_setbox(null,a);

	}
	
}


function qmv_evt_apply_skin(e,a)
{

	var cname = a.getAttribute("cname");	
	var rule = "";

	var da = a;
	while (da.tagName!="DIV")
		da = da[qp];

	rule = da.getAttribute("rule");
	var mset = new Array();

	if (rule=="color")
	{

		var sk = qmv.skins.color_rules = new Object();
		var cobj = {m_bg:'#eeeeee',s_bg:'#cccccc',border:'#999999',text:'#111111'};
		
		if (cname=="light_grays")
			cobj = {m_bg:'#f3f3f3',s_bg:'#e3e3e3',border:'#bbbbbb',text:'#555555'};
		else if (cname=="medium_grays")
			cobj = {m_bg:'#e6e6e6',s_bg:'#cccccc',border:'#999999',text:'#111111'};
		else if (cname=="dark_grays")
			cobj = {m_bg:'#dddddd',s_bg:'#bbbbbb',border:'#555555',text:'#000000'};
		else if (cname=="black_white")
			cobj = {m_bg:'#ffffff',s_bg:'#000000',border:'#000000',text:'#000000',s_text:'#ffffff',m_text_active:'#ffffff'};
		else if (cname=="red_brick")
			cobj = {m_bg:'#dddddd',s_bg:'#BD3A3E',border:'#752427',text:'#000000'};
		else if (cname=="blue_tones")
			cobj = {m_bg:'#DFF0FC',s_bg:'#72BCF0',border:'#333333',text:'#000000'};	
		else if (cname=="blue_yellow")
			cobj = {m_bg:'#F5EAB4',s_bg:'#77C0FC',border:'#333333',text:'#000000'};		
		else if (cname=="blue_green")
			cobj = {m_bg:'#B4EA9B',s_bg:'#77C0FC',border:'#333333',text:'#000000'};		
		else if (cname=="forest_green")
			cobj = {m_bg:'#CBD8C6',s_bg:'#6D8F60',border:'#333333',text:'#000000'};	
		else if (cname=="earth_tones")
			cobj = {m_bg:'#F3F2ED',s_bg:'#DCDACD',border:'#333333',text:'#5D4C2D'};
		else if (cname=="sunset_orange")
			cobj = {m_bg:'#FDD3A7',s_bg:'#FCB76E',border:'#333333',text:'#7E4203'};				
				
		
		//set vals
		mset.push("css|#qm[i] .qmitem-m|backgroundColor|"+cobj.m_bg);
		mset.push("css|#qm[i].qmmc .qmitem-m.qmactive|backgroundColor|"+cobj.s_bg);
		mset.push("css|#qm[i] .qmsub|backgroundColor|"+cobj.s_bg);
		mset.push("css|#qm[i] .qmsub|borderColor|"+cobj.border);
		mset.push("css|#qm[i] .qmitem-m|borderColor|"+cobj.border);
		mset.push("css|#qm[i] .qmitem-m|color|"+cobj.text);
		
		if (cobj.s_text) mset.push("css|#qm[i] .qmitem-s|color|"+cobj.s_text);
		else mset.push("css|#qm[i] .qmitem-s|color|"+cobj.text);
		
		//turn off vals
		mset.push("css|#qm[i] .qmitem-m:hover|color|");
		mset.push("css|#qm[i] .qmitem-s:hover|color|");
		
		if (cobj.m_text_active) mset.push("css|#qm[i].qmmc .qmitem-m.qmactive|color|"+cobj.m_text_active);
		else mset.push("css|#qm[i].qmmc .qmitem-m.qmactive|color|");
		
		mset.push("css|#qm[i].qmmc .qmitem-m.qmactive|borderColor|");
		mset.push("css|#qm[i].qmmc .qmitem-s.qmactive|color|");
			
		

	}
	else if (rule=="spacing")
	{
		qmv.skins.spacing_rules = new Object();
		qmv.skins.spacing = new Object();

		qmv.skins.spacing_rules.h4_main_gaps = new Array("css|#qm[i] .qmitem-m|margin");
		qmv.skins.spacing.h4_main_gaps = new Array("0px 4px 0px 0px");

		qmv.skins.spacing_rules.h0_main_gaps = new Array("css|#qm[i] .qmitem-m|margin");
		qmv.skins.spacing.h0_main_gaps = new Array("0px");
		
		qmv.skins.spacing_rules.v4_main_gaps = new Array("css|#qm[i] .qmitem-m|margin");
		qmv.skins.spacing.v4_main_gaps = new Array("0px 0x 4px 0px");
		
		qmv.skins.spacing_rules.v0_main_gaps = new Array("css|#qm[i] .qmitem-m|margin");
		qmv.skins.spacing.v0_main_gaps = new Array("0px");

		qmv.skins.spacing_rules.small_sub_pad = new Array("css|#qm[i] .qmsub|padding");
		qmv.skins.spacing.small_sub_pad = new Array("2px");

		qmv.skins.spacing_rules.medium_sub_pad = new Array("css|#qm[i] .qmsub|padding");
		qmv.skins.spacing.medium_sub_pad = new Array("5px");

		qmv.skins.spacing_rules.large_sub_pad = new Array("css|#qm[i] .qmsub|padding");
		qmv.skins.spacing.large_sub_pad = new Array("10px");

	}
	
	var si = true;
	if (cname.indexOf("main_gaps")+1) si = false;

	for (var i=0;i<mset.length;i++)
	{
		var sp = mset[i].split("|");
		if (sp.length>2)
		{
			var inp = qmv_find_update_tree_value(sp[0],sp[1],sp[2],sp[3],false,true);

			var su = true;
			if (i==mset.length-1) su = true;
						
			qmv_evt_update_tree_value(inp,null,true,su,si,false,true);
		}
	}

	if (document.getElementById("qmvtree_filter").cdiv.style.display=="block")
		qmv_filter_init2();
	
	if (document.getElementById("qmvi_msg_dialog").style.visibility!="visible")
	{
		if (!qmv.msg_skin_settings_shown)
		{
			qmv_show_dialog("alert",null,"<b>Your skin settings have been applied!</b><br><br>All skin settings are individually customizable in the 'Global CSS Styles' and 'Scripted Add-On' sections of the left tree.",460);	
			qmv.msg_skin_settings_shown = true;
		}
	}

}



function qmv_shortcut_init(a)
{

	
	
	a.innerHTML = "";
	var tcolor = new Array();
	var tbuild = new Array();
		
	//combine colors and count them	
	for (var i=0;i<qmv.color_recent.length;i++)
	{

		var con = false;
		for (var j=0;j<tbuild.length;j++)
		{
			if (tbuild[j].inp.value.toLowerCase()==qmv.color_recent[i].value)
			{
				
				if (tbuild[j].sdtype=="colormulti" && qmv.color_recent[i].inp.getAttribute("dtype")=="color")
				{
					var sc = tbuild[j].count;
					tbuild[j].inp = qmv.color_recent[i].inp;
					tbuild[j].sdtype = "color";
					tbuild[j].count = sc;
				}
				tbuild[j].count++;
					
				con = true;
			}
		}
		
		if (con) continue;

		var tb = new Object()
		tb.inp = qmv.color_recent[i].inp;
		tb.count = 1;
		tb.sdtype = tb.inp.getAttribute("dtype");
		tbuild.push(tb);
		
	}
	

	for (var i=0;i<tbuild.length;i++)
	{

		//qp==parentNode
		var ipp = tbuild[i].inp[qp];
		while (ipp.tagName!="A")
			ipp = ipp[qp];

		//clone and copy the node to ip		
		var ni = ipp.cloneNode(true);
			
		qm_arc("qmvtreelasta",ni);
		qm_arc("qmvtreefirsta",ni);

		if (i==tbuild.length-1)		
			qm_arc("qmvtreelasta",ni,true);

		if (i==0)
			qm_arc("qmvtreefirsta",ni,true);

			
			
		//add the description to the cloned node
		var tds = ni.getElementsByTagName("TD");
		for (var j=0;j<tds.length;j++)
		{
			if (tds[j].getAttribute("filtercol1"))
			{
				tds[j].style.width = "120px";
				tds[j].innerHTML = "Style Quantity:&nbsp;"+"(<span style='color:#dd3300;'>"+tbuild[i].count+"</span>)&nbsp;";
			
			}
		
		}


		var inp_orig = tbuild[i].inp;

		var inp = ni.getElementsByTagName("INPUT")[0];
		inp.origrule = inp_orig.origrule;
		inp.rule = inp_orig.rule;
		
		
			
		inp.iseditcolor = 1;
		inp.prev_value = inp_orig.prev_value;
			
		//append ni, the new cloned color change inputs
		a.appendChild(ni);
		

	}

	
	
}



function qmv_filter_init()
{

	if (!qmv.filter)
	{

		qmv.filter = new Object();
		qmv.filter.settings = new Object();
		

		qmv.filter.settings.value = "addedit";
		qmv.filter.settings.group = "main";
		qmv.filter.settings.section = "item";
		qmv.filter.settings.style = "color";

		document.getElementById("qmvf_value0").checked = true;
		document.getElementById("qmvf_value1").checked = true;
		document.getElementById("qmvf_group0").checked = true;
		document.getElementById("qmvf_section1").checked = true;
		document.getElementById("qmvf_style0").checked = true;


	}

	
	if (document.getElementById("qmvtree_filter").cdiv.style.display!="block")
		qmv_filter_init2();
		
		
}

function qmv_filter_init2()
{

	qmv_filter_init_results_object();
	qmv_filter_get_results();
	qmv_filter_build_results();

}


function qmv_filter_update_automatically(type)
{

	var sw = {};
	sw.level = document.getElementById("qmvi_filter_auto_indicator_level");
	sw.apply = document.getElementById("qmvi_filter_auto_indicator_apply");

	var changed = false;
		
	if (sw.level.getAttribute("qmvison"))
	{
		var is_main = qm_a(qm_get_pdiv(qmv.cur_item));
		var level0 = document.getElementById("qmvf_group0");
		var level1 = document.getElementById("qmvf_group1");
		
		if (is_main)
		{
			if (!level0.checked)
			{
				level0.checked = true;
				changed = true;
			}
		}
		else if (!level1.checked)
		{
			level1.checked = true;
			changed = true;
		}
	}
	
	if (sw.apply.getAttribute("qmvison"))
	{
		var apply0 = document.getElementById("qmvf_section0");
		var apply1 = document.getElementById("qmvf_section1");
		var apply2 = document.getElementById("qmvf_section2");
		
		if (type=="item")
		{
			if (!apply1.checked)
			{
				apply1.checked = true;
				changed = true;
			}
		
		}
		else if (type=="sub")
		{
			if (!apply0.checked)
			{
				apply0.checked = true;
				changed = true;
			}
		
		}
		else if (type=="column")
		{
			if (!apply2.checked)
			{
				apply2.checked = true;
				changed = true;
			}
		
		}
		
	}
		
	
	if (changed)
		qmv_filter_change();
}


function qmv_filter_change_auto_option(type,val)
{
	
	var sw = {};
	sw.level = document.getElementById("qmvi_filter_auto_indicator_level");
	sw.apply = document.getElementById("qmvi_filter_auto_indicator_apply");
		
	if (val=="on")
	{
		sw[type].src = qmv.base+"images/qmv_tree_auto_on1.gif";
		sw[type].setAttribute("qmvison",1);
	}
	else
	{
		sw[type].src = qmv.base+"images/qmv_tree_auto_off1.gif";
		sw[type].removeAttribute("qmvison");
	}
		
}


function qmv_filter_change()
{

	qmv.filter.settings.value = "";
	if (document.getElementById("qmvf_value0").checked)
		qmv.filter.settings.value += "add";
	if (document.getElementById("qmvf_value1").checked)
		qmv.filter.settings.value += "edit";


	if (!qmv.filter.settings.value)
		qmv_show_dialog("alert",null,"You must check '<span style='color:#0033aa'>add</span>' or '<span style='color:#0033aa'>edit</span>' for the filter to display results.",400,null,null,null,null,true);		


	if (document.getElementById("qmvf_group0").checked)
		qmv.filter.settings.group = "main";
	else
		qmv.filter.settings.group = "sub";


	if (document.getElementById("qmvf_section0").checked)
		qmv.filter.settings.section = "container";
	else if (document.getElementById("qmvf_section1").checked)
		qmv.filter.settings.section = "item";
	else if (document.getElementById("qmvf_section2").checked)
		qmv.filter.settings.section = "column";


	if (document.getElementById("qmvf_style0").checked)
		qmv.filter.settings.style = "color";
	else if (document.getElementById("qmvf_style1").checked)
		qmv.filter.settings.style = "font";
	else if (document.getElementById("qmvf_style2").checked)
		qmv.filter.settings.style = "border";
	else if (document.getElementById("qmvf_style3").checked)
		qmv.filter.settings.style = "other";
	else if (document.getElementById("qmvf_style4").checked)
		qmv.filter.settings.style = "image";		
	else if (document.getElementById("qmvf_style5").checked)
		qmv.filter.settings.style = "spacing";		
	else if (document.getElementById("qmvf_style6").checked)
		qmv.filter.settings.style = "css3";		
	else if (document.getElementById("qmvf_style7").checked)
		qmv.filter.settings.style = "all";	
	
		
	qmv_filter_init_results_object();

	qmv_filter_get_results();
	qmv_filter_build_results();

}

function qmv_filter_init_results_object()
{

	qmv.filter.results = new Array();
	qmv.filter.results_title = new Array();
	qmv.filter.results_title_action = new Array();

}

function qmv_filter_get_results(obj,title)
{

	var fr = qmv.filter.results;
	var fr_title = qmv.filter.results_title;
	var fs = qmv.filter.settings;

	if (!obj)
	{
		obj = document.getElementById("qmvtree_css_styles");
	}

	var isfont = obj.getAttribute("isfont");

	

	var a = obj.childNodes;
	for (var i=0;i<a.length;i++)
	{
		
		if (a[i].tagName=="A")
		{
			var inp = a[i].getElementsByTagName("INPUT")[0];
			if (inp)
			{

				if ((fs.value.indexOf("edit")+1 && inp.value) || (fs.value.indexOf("add")+1 && !inp.value))
				{

					var cname=inp.getAttribute("cname");
					var dtype=inp.getAttribute("dtype");

					var go = false;

					if (fs.style=="font" && isfont)
						go = true;

					if ((fs.style=="color" && (dtype=="color" || dtype=="colormulti" || cname=="opacity")) || (fs.style=="border" && (cname.indexOf("border")+1 || cname.indexOf("box")+1)))
						go = true;
					
					if (fs.style=="image" && (cname=="backgroundImage" || cname=="backgroundRepeat" || cname=="backgroundPosition"))
						go = true;	
						
					if (fs.style=="spacing" && (cname=="margin" || cname=="padding" || cname=="textAlign" || cname=="width" || cname=="height"))
						go = true;	
					
					if (fs.style=="css3" && (cname=="textShadow" || cname=="boxShadow" || cname=="borderRadius" || cname==(qmv.css_prefix2+"Transform")))
						go = true;	
					
					if (fs.style=="other" && !go && !isfont && dtype!="color" && cname.indexOf("border")==-1 && cname.indexOf("background")==-1 && cname!="boxShadow" && cname!="margin" && cname!="padding" && cname!="opacity" && cname!=(qmv.css_prefix2+"Transform"))
						go = true;

					if (fs.style=="all")
						go = true;
						
					if (go)
					{
						var t = false;
						if (title)
								t = title;
						

						fr_title.push(t);
						fr.push(a[i]);
					}

				}
			}
			
			var b;
			if (b = a[i].cdiv)
			{
				var group;
				if ((group = b.getAttribute("group")) && group!=fs.group)
					continue;

				var section;
				if ((section = b.getAttribute("section")) && section!=fs.section)
					continue;
				
				var t
				if (!(t = b.getAttribute("ftitle")))
					t = false;

				qmv_filter_get_results(a[i].cdiv,t)

			}

		}


	}


}


function qmv_filter_build_results()
{
	var ta = "";

	var fr = qmv.filter.results;
	var fr_title = qmv.filter.results_title;


	var a = document.getElementById("qmvtree_filter_results");
	document.getElementById("qmvtree_filter_results_qty").innerHTML = "(<span style='color:#dd3300'>"+fr.length+"</span>)";

	
	if (!fr.length)
	{
		a.innerHTML = '<a href="#">This filter has zero results.</a>';
		return;
	}

	a.innerHTML = "";
	for (var i=0;i<fr.length;i++)
	{
		
				
		var ni = fr[i].cloneNode(true);
		qm_arc("qmvtreelasta",ni);
		qm_arc("qmvtreefirsta",ni);

		var tds = ni.getElementsByTagName("TD");
		for (var j=0;j<tds.length;j++)
		{
			if (tds[j].getAttribute("filtercol1"))
			{	
				tds[j].style.width = "120px";
	
				if (fr_title[i] && ta.indexOf(fr_title[i])==-1)
				{
					
					var st = document.createElement("SPAN");
					st.style.display = "block";
					st.style.className = "qmvi-common";
					st.style.color = "#555555";
					st.style.MozUserSelect = "none";
					st.style.fontSize = "13px";
					
					st.style.cursor = "help";
					st.setAttribute("styletitle",fr_title[i]);
					st.onclick=function(event){qmv_style_effect_settings_help(event,this)};
					
					
					if (!ta)
						st.style.marginTop = "4px";
					else
						st.style.marginTop = "8px";

					st.style.marginBottom = "4px";
					st.innerHTML = "["+fr_title[i]+"]";
					a.appendChild(st);
				
					ta = fr_title[i];
					
				}
			}


		}


		var inp_orig = fr[i].getElementsByTagName("INPUT")[0];
		var inp = ni.getElementsByTagName("INPUT")[0];

		inp.origrule = inp_orig.origrule;
		inp.rule = inp_orig.rule;
		inp.prev_value = inp_orig.prev_value;
		inp.isfilter = 1;

		a.appendChild(ni);
	
	}


	var hp = document.createElement("SPAN");
	hp.style.display = "block";
	hp.style.fontSize = "1px";
	hp.style.height = "5px";
	a.appendChild(hp);	

	
}


function qmv_info_item_extra_hover_active_help()
{

	qmv_show_dialog("alert",null,"To use hover and active effects create a custom image for each.  Append '_hover' or '_active' to the file name and save them to the same folder as the static image.  If your static image is '<span style='color:#dd3300'>main1.gif</span> the hover and actives would be...<br><br><span style='color:#dd3300'>main1_hover.gif<br>main1_active.gif</span><br><br>Hovers and actives are optional and are activated by setting the value of this field to true.",600);

}




var qmc_si, qmc_li, qmc_lo, qmc_tt, qmc_th, qmc_ts;
var qp = "parentNode";
var qc = "className";

var qmc_t = navigator.userAgent;
var qmc_o = qmc_t.indexOf("Opera")+1;
var qmc_s = qmc_t.indexOf("afari")+1;
var qmc_s2 = qmc_s && window.XMLHttpRequest;
var qmc_n = qmc_t.indexOf("Netscape")+1;
var qmc_v = parseFloat(navigator.vendorSub);





function qmc_create(sd,v,ts,th,oc,rl,sh,fl,nf,l)
{

	var w = "onmouseover";
	if (oc) 
	{
		w = "onclick";
		th = 0;
		ts = 0;
	}

	if (!l)
	{
		
		l=1;
		qmc_th = th;
		

		sd = document.getElementById("qm"+sd);
		sd[w]=function(e){qmc_kille(e);};
		
		
		sd.style.zoom = 1;
		if (sh) qmc_arc("qmsh",sd,true);	
		if (!v) sd.ch = 1;
		
				
	}
	else if (sh)
		sd.ch = 1;
		
	
	
	if (sh) sd.sh = 1;
	if (fl) sd.fl = 1;
	if (rl) sd.rl = 1;
	
	sd.style.zIndex = l+""+1;
	

	var lsp;
	var sp = sd.childNodes;
	
	for (var i=0;i<sp.length;i++)
	{
		
		var b=sp[i];	
		if (b.tagName=="A")
		{
			
			lsp = b;	
			b[w] = qmc_oo;
			b.qmts = ts;
			
			if (l==1 && v)
			{
				
				b.style.styleFloat = "none";
				b.style.cssFloat = "none";
				
			}
			
		}	
		
		if (b.tagName=="DIV")
		{
			
			
			qmc_arc("qmparent",lsp,true);
			lsp.cdiv = b;
			b.idiv = lsp;

			if (qmc_n && qmc_v<8 && !b.style.width)
				b.style.width = b.offsetWidth+"px";

			
						
			new qmc_create(b,null,ts,th,oc,rl,sh,fl,nf,l+1);	

		}
			
	}

}




function qmc_bo(e)
{

	
	
	clearTimeout(qmc_tt);
	qmc_tt = null;
	
	if (qmc_li && !qmc_tt)
		qmc_tt = setTimeout("qmc_2bo()",qmc_th);	
	

}


function qmc_2bo()
{
	var a;
	if ((a = qmc_li))	
	{
		do
		{
			qmc_uo(a);
		}while ((a = a[qp]) && !qmc_a(a))
	}

	qmc_li = null;
}


function qmc_a(a)
{
	
	if (a[qc].indexOf("qmmc")+1)
		return 1;

}

function qmc_uo(a,go)
{
	
	
	if (!go && a.qmtree) return;

	if (window.qmad && qmad.bhide) eval(qmad.bhide);
	a.style.visibility = "";
	qmc_arc("qmactive",a.idiv);
	

	
	

}




function qmc_oo(e,o,nt)
{

	
	if (!o) o=this;
		
	if ((!o || !o[qp]) || (o.tagName=="A" && o[qp].id=="qm98"))
	{
		if (!qmv.context_clicked) return;
	}
	
	o.blur();
	
	if (window.qmwait) {qmc_kille(e); return;}

	clearTimeout(qmc_tt);
	qmc_tt = null;
	
	
	if (!nt && o.qmts)
	{
		
		qmc_si = o;
		qmc_tt = setTimeout("qmc_oo(new Object(),qmc_si,true)",o.qmts);
		return;
	}

	
	
	var a = o;
	if (a[qp].isrun) {qmc_kille(e); return;}
	

	var go = true;
	while ((a = a[qp]) && !qmc_a(a))
	{
		if (a==qmc_li)
			go = false;
	}
		

	if (qmc_li && go)
	{
		a = o;
		if ((!a.cdiv) || (a.cdiv && a.cdiv!=qmc_li))
			qmc_uo(qmc_li);
		

		a = qmc_li;
		while ((a = a[qp]) && !qmc_a(a))
		{
			
			if (a!=o[qp])
				qmc_uo(a);
			else
				break;
					
		}
	}

		
	var b = o;
	var c = o.cdiv;
	if (b.cdiv)
	{
	
				
		var aw = b.offsetWidth;
		var ah = b.offsetHeight;
		var ax = b.offsetLeft;
		var ay = b.offsetTop;

	
				
		if (c[qp].ch)
		{
			aw = 0;
			if (c.fl) ax =0;
		}
		else
		{
			if (c.rl)
			{
				ax = ax-c.offsetWidth;
				aw=0;
			}

			ah=0;
		}		

	
		if (qmc_o)
		{
			
			ax-=b[qp].clientLeft;
			ay-=b[qp].clientTop;
		}

		if (qmc_s2)
		{
			ax-=qmc_gcs(b[qp],"border-left-width","borderLeftWidth");
			ay-=qmc_gcs(b[qp],"border-top-width","borderTopWidth");
		}	

	
		if (!c.ismove)
		{
			c.style.left = (ax+aw)+"px";
			c.style.top = (ay+ah)+"px";
		}
		
		
		qmc_arc("qmactive",o,true);
		
		qmv_apsubs(c);
		if (window.qmad && qmad.bvis) eval(qmad.bvis);

		c.style.visibility ="inherit";

		qmc_li = c;

	}
	else if (!qmc_a(b[qp]))
		qmc_li = b[qp];
	else
		qmc_li = null;
		
	
	qmc_kille(e);

	
}


function qmc_gcs(obj,sname,jname)
{
	var v;
	if (document.defaultView && document.defaultView.getComputedStyle)
		v = document.defaultView.getComputedStyle(obj, null).getPropertyValue(sname);
	else if (obj.currentStyle)
		v = obj.currentStyle[jname];		

	if (v && !isNaN(v = parseInt(v)))
		return v;
	else
		return 0;
	

}



function qmc_arc(name,b,add)
{

	var a = b[qc];
	if (add)
	{
		if (a.indexOf(name)==-1)
			b[qc] += (a?' ':'') + name;	
		
	}
	else
	{
		
		b[qc] = a.replace(" "+name,"");
		b[qc] = b[qc].replace(name,"");
	
	}
}


	
function qmc_kille(e)
{

	if (!e) e = event;

	e.cancelBubble = true;
	
	if (e.stopPropagation && !(qmc_s && e.type=="click"))
		 e.stopPropagation();

}


function qmv_hide_context()
{

	var a = document.getElementById("qmvi_context");
	a.style.visibility = "hidden";
	
	var mc = document.getElementById("qm99");
	mc.qmcursel = null;
	mc.qmcurselsub = null;

	qmc_2bo();
	qmv.context_clicked = false;
	
	//hide the main menu bar highlighted item
	qmv_hide_main_menu_bar_on_state(a);
}




