function qmv_context_get_section_lightbox()
{
	ih = '';
	
	ih += '<a href="javascript:void(0)" onclick="qm_kille(event)">LightBox</a>';
	ih += '<div>';
		ih += '<a href="javascript:void(0)" onclick="qmv_context_cmd(event,\'lightbox_template\');">Choose Global Template</a>';
		ih += qmv_show_context_build_divider();
		ih += '<a href="javascript:void(0)" onclick="qmv_context_cmd(event,\'edit_item_lightbox\');">Add / Edit Item Properties</a>';
		if (qmv.cur_item.getAttribute("rel"))
			ih += '<a href="javascript:void(0)" onclick="qmv_context_cmd(event,\'test_item_lightbox\');">'+qmv_build_context_menu_keyboard_short_text("Ctrl+Enter")+'Test Link</a>';
			
		ih += qmv_show_context_build_divider();
		ih += '<a href="javascript:void(0)" onclick="qmv_context_cmd(event,\'remove_item_lightbox\');">Remove From Item</a>';
	ih += '</div>';
	
	return ih;
}

