function qmv_applyclassnames_handle_type_change(e,a)
{

	qmv_applyclassnames_load_saved_global_settings();

}


function qmv_applyclassnames_load_saved_global_settings()
{

	var p = document.getElementById("qm"+qmv.id).p;
	var tlist = document.getElementById("qmvi_global_classnames_type");
	var gbox = document.getElementById("qmvi_global_classnames_auto");
	var level = document.getElementById("qmvi_global_classnames_level_select");
	var awhere = document.getElementsByName("qmvi_global_classnames_subs");
		
	var alltypes = ["cnGlobalApplySubsLev1","cnGlobalApplySubsLev2","cnGlobalApplySubsLev3","cnGlobalApplySubsLev1Plus","cnGlobalApplySubsLev2Plus","cnGlobalApplySubsLev3Plus","cnGlobalApplySubsAll","cnGlobalApplySubsRemove"];

	var match = false;
	for (var i=0;i<alltypes.length;i++)
	{
		var pr = p[alltypes[i]];
		if (pr && pr.length)
		{
			for (var j=0;j<pr.length;j++)
			{
				if (pr[j]==tlist.value)
				{
					gbox.checked = true;
					
					if (alltypes[i].indexOf("cnGlobalApplySubsLev")+1)
					{
						awhere[0].checked = true;
						level.value = alltypes[i].substring("20");
					}
					else if (alltypes[i]=="cnGlobalApplySubsAll")
						awhere[1].checked = true;
					
					
					match=true;
				}
			
			}
	
		}
	}
	
	if (!match)
	{
		gbox.checked = false;
		awhere[1].checked = true;
	}
	
}


function qmv_applyclassnames_init()
{
	
	qmv_applyclassnames_load_saved_global_settings();
	
}


function qmv_applyclassnames_apply()
{
		
	var alltypes = ["cnGlobalApplySubsLev1","cnGlobalApplySubsLev2","cnGlobalApplySubsLev3","cnGlobalApplySubsLev1Plus","cnGlobalApplySubsLev2Plus","cnGlobalApplySubsLev3Plus","cnGlobalApplySubsAll","cnGlobalApplySubsRemove"];
	
	var cname = document.getElementById("qmvi_global_classnames_type").value;
	var level = document.getElementById("qmvi_global_classnames_level_select");
	var aw = document.getElementsByName("qmvi_global_classnames_subs");
		
	var type;
	if (aw[0].checked)
	{
		if (level.value)
			type="cnGlobalApplySubsLev"+level.value;
		else
			type="cnGlobalApplySubsLev1";
	}
	if (aw[1].checked)
		type="cnGlobalApplySubsAll";
	else if (aw[2].checked)
		type="cnGlobalApplySubsRemove";
		
	var saveglobal = document.getElementById("qmvi_global_classnames_auto").checked;
	
	for (var i=0;i<alltypes.length;i++)
	{
		if (type==alltypes[i] && type!="cnGlobalApplySubsRemove")
			qmv_save_global_classnames(type,cname,saveglobal);
		else
			qmv_save_global_classnames(alltypes[i],cname);
	}
	
	qmv_applyclassname_single_name(cname,type);
	
	qmv_reselect_all_menu_items_from_root_for_big_update(true);
	qmv_update_all_addons();
	qmv_position_pointer();
}


function qmv_save_global_classnames(type,cname,is_add)
{

	var p = document.getElementById("qm"+qmv.id).p;
	
	if (!p[type])
	{
		p[type] = new Array();
		p[type].isArray = 1;
	}
		
	if (is_add)
	{
		for (var i=0;i<p[type].length;i++)
		{
			if (p[type][i]==cname)
				return p[type];
		}
		
		p[type].push(cname);
	
	}
	else
	{
		for (var i=0;i<p[type].length;i++)
		{
			if (p[type][i]==cname)
			{
				p[type].splice(i,1);
				i--;
			}
		}
	
	}
	
	if (!p[type].length)
		p[type] = null;
		
	return p[type];	
}


function qmv_applyclassname_single_name(cname,type)
{
	
	if (type.indexOf("cnGlobalApplySubsLev")+1)
	{
		type = type.substring(17).toLowerCase();
		if (!type)
			type = "lev1";
	}
	else if (type=="cnGlobalApplySubsRemove")
		type = "remove";
	else
		type = "allsubs"
		
	qmv_applyclassnames_globally2([cname],cname,type);
}


function qmv_applyclassnames_globally_from_modify(spec_cname,spec_sub)
{

	var p = document.getElementById("qm"+qmv.id).p;

	var cn;
	if (cn = p.cnGlobalApplySubsLev1)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev1',spec_sub);
		
	if (cn = p.cnGlobalApplySubsLev2)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev2',spec_sub);

	if (cn = p.cnGlobalApplySubsLev3)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev3',spec_sub);

	if (cn = p.cnGlobalApplySubsLev1Plus)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev1plus',spec_sub);
		
	if (cn = p.cnGlobalApplySubsLev2Plus)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev2plus',spec_sub);

	if (cn = p.cnGlobalApplySubsLev3Plus)
		qmv_applyclassnames_globally2(cn,spec_cname,'lev3plus',spec_sub);		
		
	if (cn = p.cnGlobalApplySubsAll)
		qmv_applyclassnames_globally2(cn,spec_cname,null,spec_sub);

	if (cn = p.cnGlobalApplySubsRemove)
		qmv_applyclassnames_globally2(cn,spec_cname,'remove',spec_sub);
		
}

function qmv_applyclassnames_globally2(cn,spec_cname,filter,spec_sub)
{

	for (var i=0;i<cn.length;i++)
	{
		if (spec_cname && spec_cname!=cn[i])
			continue;
			
		if (spec_sub)
		{
			qmv_applyclassnames_globally3(filter,cn[i],spec_sub);
			
		}
		else
		{
			var d = document.getElementById("qm"+qmv.id).getElementsByTagName("DIV");
			for (var j=0;j<d.length;j++)
			{
				if (d[j].idiv)
					qmv_applyclassnames_globally3(filter,cn[i],d[j]);
					
			}
			
		}
	
	}

}


function qmv_applyclassnames_globally3(filter,cn,sub)
{

	
	//lev1, lev2, lev3, lev1plus, lev2plus, lev3plus
	if (filter.indexOf("lev")+1)
	{
	
		var lev = qm_get_level(sub);
		var fl = parseInt(filter.substring(3));
		var is_plus = filter.indexOf("plus")+1;
		if (filter==("lev"+lev) || (is_plus && lev>=fl))
		{
			qm_arc(cn,sub,true);
		}
		else
			qm_arc(cn,sub);
			
	}
	else if (filter=="remove")
	{
		if (cn=="qm-horizontal-c")
			sub.style.minWidth = "";
			
		qm_arc(cn,sub);
	}
	else
	{
		qm_arc(cn,sub,true);
	}

}


function qmv_gld_init(qmd,defval)
{

	var sub = document.getElementById("qmvi_gld_sub");
	var main = document.getElementById("qmvi_gld_main");
	var above = document.getElementById("qmvi_gld_above");
	var below = document.getElementById("qmvi_gld_below");
	var none = document.getElementById("qmvi_gld_none");

	if (defval!="remove")
	{
		if (qmv.globaldividers_sub)
			sub.checked = true;
		else
			sub.checked = false;

		if (qmv.globaldividers_main)
			main.checked = true;
		else
			main.checked = false;

		if (qmv.globaldividers_above)
			above.checked = true;
		else
			above.checked = false;

		if (qmv.globaldividers_below)
			below.checked = true;
		else
			below.checked = false;

		if (qmv.globaldividers_none)
			none.checked = true;
		else
			none.checked = false;
	}
	else
	{

		sub.checked = false;
		main.checked = false;
		above.checked = false;
		below.checked = false;
		none.checked = true;	
	}

}


function qmv_gld_apply_dividers()
{

	qmv_hide_pointer("qm"+qmv.id);

	var sub = document.getElementById("qmvi_gld_sub").checked;
	var main = document.getElementById("qmvi_gld_main").checked;
	var above = document.getElementById("qmvi_gld_above").checked;
	var below = document.getElementById("qmvi_gld_below").checked;
	var none = document.getElementById("qmvi_gld_none").checked;	

	qmv.globaldividers_sub = sub;
	qmv.globaldividers_main = main;
	qmv.globaldividers_above = above;
	qmv.globaldividers_below = below;
	qmv.globaldividers_none = none;


	var m = document.getElementById("qm"+qmv.id);

	if (qmv.cur_item.className.indexOf("qmdivider")+1)
		qm_oo(new Object(),m.getElementsByTagName("A")[0],false);

	var sp = m.getElementsByTagName("SPAN");
	for (var i=0;i<sp.length;i++)
	{

		if (sp[i].className.indexOf("qmdivider")+1)
		{
			sp[i].parentNode.removeChild(sp[i]);
			i--;
		}

	}
	
	
	qmv_gld_apply_dividers2(m,sub,main,above,below);

	

	if (main || sub)
		qmv_context_cmd(new Object(),'divider_styles');



	qmv_set_all_subs_to_default_position();
	qmv_update_all_addons();
	if (qmv.addons.tree_menu["on"+qmv.id])
	{
		qmv.addons.tree_menu.last_close_type = null;
		qmv_update_tree_menu(false,null,null,null,null,true);
	}
	qmv_position_addon_tools();
	qmv_position_pointer();

}


function qmv_gld_apply_dividers2(m,sub,main,above,below,is_sub)
{

	var ch = m.childNodes
	var is_first = true;
	var cura;

	for (var i=0;i<ch.length;i++)
	{

		if (ch[i].tagName=="A")
		{
			cura = ch[i];
			i+=qmv_gld_apply_dividers3(ch[i],main,sub,above,below,is_sub,is_first);
			is_first = false;
		}
		else if (ch[i].tagName=="DL")
		{	
			is_first = true;
			var dlch = ch[i].childNodes;
			for (var j=0;j<dlch.length;j++)
			{
				if (dlch[j].tagName=="DD")
				{
					var da = dlch[j].childNodes;
					for (var k=0;k<da.length;k++)
					{
						if (da[k].tagName=="DIV" && da[k].idiv)
						{
							new qmv_gld_apply_dividers2(dlch[j],sub,main,above,below,true);
						}
						else if (da[k].tagName=="A")
						{
							cura = da[k];
							j+=qmv_gld_apply_dividers3(da[k],main,sub,above,below,is_sub,is_first);
							is_first = false;
						}
						
					
					}
					
				}
			
			}
		
		}

		if (ch[i].tagName=="DIV")
		{
			new qmv_gld_apply_dividers2(ch[i],sub,main,above,below,true);
		}

	}

	if (below && cura)
	{
		
		if ((!is_sub && main) || (is_sub && sub))
			qmv_insert_spanitem("divider",cura,true,true,true);

	}

}


function qmv_gld_apply_dividers3(a,main,sub,above,below,is_sub,is_first)
{
	
	if (!is_sub)
	{
		if (main)
		{
			if ((above && is_first) || !is_first)
			{
				qmv_insert_spanitem("divider",a,true,null,true);
				return 1;
			}
		}
	}			
	else
	{
		if (sub)
		{
			if ((above && is_first) || !is_first)
			{
				qmv_insert_spanitem("divider",a,true,null,true);
				return 1;
			}
		}
	}

	return 0;
	
}



