function qmv_specs_get_addon_html()
{

	var rt= "";
	var tally = 0;
		

	var adds = new Object();

	var j;
	var got_one = false;
	for (var q=0;q<10;q++)
	{
		
		for (j in qmv.addons)
		{
			if (qmv.addons[j]["on"+q])
			{
				got_one = true;
				adds[j] = 1;
			}
		}
	}


	
	if (got_one)
	{
		var modules = qmv_pubgen_javascript_addons_get_api_modules(adds);
		for (j in modules)
		{
			
			var ao;
			if (ao = qmv.nfCode[j])
			{
				var s = qmv_lib_get_kilobytes(ao.code.length,true);
				tally += parseFloat(s);
	
				rt += '<tr>';

				rt += '<td style="vertical-align:top;color:#444444;width:100%;font-size:13px;">[API] '+ao.desc+':</td>'
				rt += '<td><div style="font-size:1px;width:15px;"></div></td>'
				rt += '<td style="color:#222222;width:50px;text-align:right;vertical-align:top;padding-bottom:2px;white-space:nowrap;font-size:13px;" nowrap>'+s+'</td>'

				rt += '</tr>';
	
			}
		
		}
		
		for (j in adds)
		{
			
			var ao;
			if (ao = qmv.addons[j])
			{
				var s = qmv_lib_get_kilobytes(ao.code.length,true);
				
				if (parseFloat(s)==0)
					continue;
				
				tally += parseFloat(s);
	
				rt += '<tr>';

				rt += '<td style="vertical-align:top;color:#444444;width:100%;font-size:13px;">[Addon] '+ao.desc+':</td>'
				rt += '<td><div style="font-size:1px;width:15px;"></div></td>'
				rt += '<td style="color:#222222;width:50px;text-align:right;vertical-align:top;padding-bottom:2px;white-space:nowrap;font-size:13px;" nowrap>'+s+'</td>'

				rt += '</tr>';
	
			}
				
		}

	}
	


	
	


	return new Array(rt,tally);


}


function qmv_lib_get_kilobytes(num,limited)
{
	
	bytes = num+"";
	if (bytes.length>3)
	{
		p1 = bytes.substring(0,bytes.length-3);
		p2 = bytes.substring(bytes.length-3);

		bytes = p1+","+p2;
	}
	else
		p2 = num;

	
	num = Math.round((num/1024)*10)/10;
	
	if ((num+"").indexOf(".")==-1)
		num = num+"."+0;


	if (limited)
		return num+" KB";
	else
		return num+" KB  &nbsp;("+bytes+" bytes)";

}




