function qmv_import_structure_from_saved_menu()
{

	var r = parent.xqmv_file_open_get_document();

	if (r && r[1])
	{
		var a = document.createElement("DIV");
		a.innerHTML = r[1];		
		var ul = a.getElementsByTagName("UL")[0];
		
		qmv_import_menu_convert(ul,true);
		
	}
	
}


function qmv_import_dialog_structure_where_changed(event,a)
{
	var au = document.getElementById("qmvi_import_copypaste_orientation_auto");
	
	if (au)
	{
		if (a.id=="qmvi_import_copypaste_where_add")
			au.checked = true;
			
		var ch = au[qp][qp].childNodes;
		for(var i=0;i<=7;i++)
		{
			
			if (a.id=="qmvi_import_copypaste_where_add")
			{
				ch[i].style.display = "none";
			}
			else
			{
				ch[i].style.display = "";
			}
		}
	
	}

}


function qmv_import_menu_apply_where(new_menu,type)
{
	
	if (type=="replace")
	{

		var m = document.getElementById("qm"+qmv.id);
		var create = qmv_pubgen_structure_build_menu_settings(qmv.id,m,null,true);
		
		new_menu.id = "qm"+qmv.id;
			
		m[qp].insertBefore(new_menu,m);
		m[qp].removeChild(m);
		
		var tbi = qmad.binit;
		qmad.binit = "";
		eval(create);
		qmad.binit = tbi;
		
		qmv_delete_pointer_objects("qm"+qmv.id);
		
		qmv.ibcss_ss = false;
		qmv.addons.tree_menu.initialized = false;
		qmv.addons.scroll.initialized = false;
		
		document.onmouseover=function(event)
		{
			qm_hhovhide(event,this);
			qm_kille(event);
		}
		
		qmv_design_menu2(new_menu);
		
		qmv.id=-1;
		qmv.cur_item=null;
		qmv.cur_sub=null;
		qmv.cur_container=null;
			
		qm_oo(new Object(),new_menu.getElementsByTagName("A")[0]);
		
	}
	else //add as a new menu
	{
		qmv_add_new_menu(new_menu);
	}
	
}


function qmv_import_menu()
{

	var mc = document.getElementById("qmvi_import_stucture_content");
	if (mc.value)
	{

		var a = document.createElement("DIV");
		a.innerHTML = mc.value;		
		var list = a.getElementsByTagName("UL")[0] || a.getElementsByTagName("OL")[0] || a.getElementsByTagName("DL")[0];
	
		qmv_import_menu_convert(list);
			
	}
	else
	{
		qmv_show_dialog("alert",null,"First paste the structure you wish to import (<b>ul/li</b> -or- <b>ol/li</b> -or- <b>dl/dd</b>).",480);
		return false;		
	}


	return true;

}


function qmv_import_menu_convert(list,from_save_file)
{
	
	if (list)
	{
		var menu;
		if (list.className.indexOf("qmmc")+1 && list.innerHTML.indexOf("qmitem-m")+1)
		{
			//it's a NodeFire menu structrue, build as usual
			menu = qm_pure(list);
		}
		else if (list.tagName=="UL" || list.tagName=="OL" || list.tagName=="DL")
		{
			//it's a 3rd party menu - convert it
			menu = qmv_import_convert_3rdparty(list);
		}
		else
		{
			qmv_show_dialog("alert",null,"The document / content does not contain a valid menu structure.",400);
			return false;
		}
		
		
		if (menu.className.indexOf("qmmc")==-1)
			menu.className = "qmmc";
		
		var o_auto = document.getElementById("qmvi_import_copypaste_orientation_auto")
		if ((o_auto && o_auto.checked) || from_save_file)
		{
			var curm = document.getElementById("qm"+qmv.id);
			menu.className = curm.className;
		}
		else
		{
			var o_ish = document.getElementById("qmvi_import_copypaste_orientation_horizontal");
			if (o_ish && o_ish.checked)
				qm_arc("qm-horizontal-c",menu,true);
			else
				qm_arc("qm-horizontal-c",menu);
		}
		
		var type = "replace"
		if (!from_save_file)
		{
			if (document.getElementById("qmvi_import_copypaste_where_add").checked)
				type = "add";
		}
		
		
		qmv_import_menu_apply_where(menu,type)
		
		
	}
	else
	{

		qmv_show_dialog("alert",null,"The document / content does not contain a valid menu structure.",400);
		return false;	
	
	}

}


function qmv_import_convert_3rdparty(list)
{
			
	var nd = document.createElement("DIV");
	qmv_import_convert_3rdparty2(list,nd);

	nd = list[qp].insertBefore(nd,list);
	list[qp].removeChild(list);
	list = nd;
	
	return list;
}


function qmv_import_convert_3rdparty2(list,bm,l)
{

	if (!l)
	{		
		bm.className = list.className;
		bm.id = list.id;
	}

	var ch = list.childNodes;
	for (var i=0;i<ch.length;i++)
	{
			
		var ctn = ch[i].tagName;
		if ((ctn=="LI" || ctn=="DD" || ctn=="DT") && ch[i].className!="qmclear")
		{
			
			var cur_a;
			var sh = ch[i].childNodes;
			for (var j=0;j<sh.length;j++)
			{
				if (sh[j])
				{
					
					if (sh[j].tagName=="A")
					{
						cur_a = bm.appendChild(sh[j]);
						
					}
					else if (sh[j].nodeType==3 && sh[j].nodeValue)
					{
						var ischar = sh[j].nodeValue.match(/[0-9a-zA-Z]/g);
						if (ischar)
						{
							var newa = document.createElement("A");
							newa.innerHTML = sh[j].nodeValue;
							newa.setAttribute("href","javascript:void(0)");
							cur_a = bm.appendChild(newa);
						}
					}
				
					if (cur_a)
					{
						if (!l)
							cur_a.className = "qmitem-m";
						else
							cur_a.className = "qmitem-s";
					}
					
				}
			}
						
			
			var hu;
			if (hu = ch[i].getElementsByTagName(list.tagName)[0])
			{
				
				if (cur_a)
					qm_arc("qmparent",cur_a,true);
				
				var na = document.createElement("DIV");
				na.className = "qmsub";
				na = bm.appendChild(na);
				new  qmv_import_convert_3rdparty2(hu,na,true)

			}	
			

		}		


	}


}



