function qmv_custom_rule_build(get_display,uobj,qmd)
{
	

	var brule = "";
	var brule_p = "";
	var brule_h = "";
	
	var group = "items";
	var add = "";
	var type_pure = true;
	var type_hybrid = true;
	var target = 'static';
	var sub_level = 0;
	var class_name = "";

	if (document.getElementById("qmvccc_menu_group_container").checked)
		group = "container";
	else if (document.getElementById("qmvccc_menu_group_title").checked)
		group = "title";
	else if (document.getElementById("qmvccc_menu_group_divider").checked)
		group = "divider";
	else if (document.getElementById("qmvccc_menu_group_contentbox").checked)
		group = "contentbox";
		
	if (document.getElementById("qmvccc_menu_add_a").checked)
		add = " a";
	else if (document.getElementById("qmvccc_menu_add_span").checked)
		add = " span";
	else if (document.getElementById("qmvccc_menu_add_div").checked)
		add = " div";
	else if (document.getElementById("qmvccc_menu_add_img").checked)
		add = " img";		

	if (!document.getElementById("qmvccc_menu_type_pure").checked)
		 type_pure = false;
	
	if (!document.getElementById("qmvccc_menu_type_hybrid").checked)
		 type_hybrid = false;
	
	if (document.getElementById("qmvccc_menu_type_both").checked)
	{
		 type_pure = true;
		 type_hybrid = true;
	}

	
	if (group=="container" && add)
	{
		document.getElementById("qmvccc_menu_add_none").checked = true;
		add="";
		
		qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>Menu group containers can't be combined with item content selectors.",320);
		//document.getElementById("qmvccc_menu_add_a")[qp][qp].style.visibility = "hidden";
		//document.getElementById("qmvccc_menu_add_div")[qp][qp].style.visibility = "hidden";
		//document.getElementById("qmvccc_menu_add_span")[qp][qp].style.visibility = "hidden";
		
		
	}
	else
	{
		//document.getElementById("qmvccc_menu_add_a")[qp][qp].style.visibility = "inherit";
		//document.getElementById("qmvccc_menu_add_div")[qp][qp].style.visibility = "inherit";
		//document.getElementById("qmvccc_menu_add_span")[qp][qp].style.visibility = "inherit";
	
	}

	var o_custname = document.getElementById("qmvccc_custom_class_name");
	o_custname.value = o_custname.value.replace(/ /g,"");
	class_name = o_custname.value;
	
	sub_level = document.getElementById("qmvccc_sub_level").value;
	target = document.getElementById("qmvccc_target").value;
	

	
	
	brule_h += "div#qm"+qmv.id;
	var ig = "";
	for (var i=0;i<=sub_level;i++)
	{
		
		if (i==sub_level)
		{
			if (group=="items")
			{
				if (i==0)
					ig+=" .qmitem-m";
				else
					ig+=" .qmitem-s";
			}
			else if (group=="title")
				ig+=" .qmtitle";
			else if (group=="divider")
				ig+=" .qmdivider";
			else if (group=="contentbox")
				ig+=" .qmcbox";
		}
		else
			ig+=" .qmsub";



	}
	brule_h += ig;


	if (class_name)
	{
		class_name = class_name.replace(".","");
		document.getElementById("qmvccc_custom_class_name").value = class_name;

		class_name = " .qmc_"+class_name;
		brule_h+=class_name;
	}
	
	if (target!="static")
		brule_h += target;
		
	brule_h += add;


	brule_p = brule_h.replace(/div/g,"ul");
	brule_p = brule_p.replace(/ulider/g,"divider");
	

	if (type_hybrid)
		brule += brule_h;

	if (type_pure && type_hybrid)
		brule += ", ";

	if (type_pure)
		brule += brule_p;		


	if (get_display)
		return brule;

	

	var c=0;
	while (qmv["style_rules"+c])
	{
		var rules = qmv["style_rules"+c];
		for (var i=0;i<rules.length;i++)
		{
			var st = rules[i].selectorText.toLowerCase();
			if (st==brule)
			{	
				var fa = brule.split(',')[0];
				fa = fa.replace("#qm"+qmv.id,"#qm[i]");
				qmv_show_dialog("question-yesno",null,"This rule already exists. Duplicate rules can't be added, instead use the existing rule to customize your styles.<br><br><b>Edit existing rule styles?</b>",400,"qmv_custom_rule_build_edit_existing('"+fa+"','"+qmd.id+"')");
				
				return;
			}
			
		}
		c++;
	}
	
	

	if (!uobj) //if its a new rul
	{
		
		var n = document.getElementById("qmvtree_custom_rules");
		var sr = brule_h.replace("qm"+qmv.id,"qm[i]");

		var or = brule.replace("qm"+qmv.id,"qm[i]");
		or = or.replace("qm"+qmv.id,"qm[i]");

		var anc = qmv_tree_create_new_node("container",n,sr,"Rule <span title='"+brule+"' class='qmvtree-rule'>["+qmv_rule_truncate(brule,20)+"]</span>",or);
		qmv_update_tree_after_load(n);
		
		qmv_css_addrule_to_sheet(qmv.style_rules_sheet0,brule,'');
		qmv_load_styles_to_tree_node(null,brule,true,n.getElementsByTagName("DIV"),true);

		qmv_display_setbox(anc);
		return brule;
		
		
	}
	else //if we are updating / changing an existing rule
	{

		
		var sr = uobj.getAttribute('orule');
		sr = sr.replace(/qm\[i\]/g,"qm"+qmv.id);
		
		var c=0;
		while (qmv["style_rules"+c])
		{
		
			var revals = '';
			var rules = qmv["style_rules"+c];
			for (var i=0;i<rules.length;i++)
			{
				
				var st = rules[i].selectorText.toLowerCase();
				if (st==sr)
				{
					revals+=rules[i].style.cssText;
					qmv_lib_update_remove_rule(qmv["style_rules_sheet"+c],qmv["style_rules"+c],st,null,true);
						break;
				}
			
			}
			
			qmv_lib_update_add_rule_styles(qmv["style_rules_sheet"+c],qmv["style_rules"+c],brule,revals,false,true);
			
			c++;
		}
			

		var ssr = brule_h.replace("qm"+qmv.id,"qm[i]");
		
		var oor = brule.replace("qm"+qmv.id,"qm[i]");
		oor = oor.replace("qm"+qmv.id,"qm[i]");
		
		
		uobj.setAttribute("rule",ssr);
		uobj.setAttribute("orule",oor);
		var spans = uobj.idiv.getElementsByTagName("SPAN");
		for (var i=0;i<spans.length;i++)
		{
			if (spans[i].className.indexOf("qmvtree-rule")+1)
			{
				spans[i].setAttribute("title",brule);
				spans[i].innerHTML = "["+qmv_rule_truncate(brule,20)+"]";
			}

		}
		
		var dd = uobj.getElementsByTagName("DIV");
		for (var i=0;i<dd.length;i++)
		{
			dd[i].setAttribute("rule",ssr);
			dd[i].setAttribute("orule",oor);
		}

		var inps = uobj.getElementsByTagName("INPUT");
		for (var i=0;i<inps.length;i++)
		{
			inps[i].rule = brule_h;
		}

		qmv_display_setbox(uobj.idiv);

		qm_sam_stretch(qmv.cur_sub);
		qmv_reselect_all_menu_items_from_root_for_big_update(true);
				
		qmv_update_all_addons();
		qmv_position_pointer();
		
		qmv_htmledit_update_from_visual_change();	
		
		return brule;

	}

}


function qmv_custom_rule_build_edit_existing(fa,dlg_id)
{
	
	var a = qmv_find_rule_atag(fa);
	if (a)
		qmv_display_setbox(a);
		
	qmv_hide_dialog(null,null,null,null,null,null,null,null,document.getElementById(dlg_id));
	
}



function qmv_apply_pre_defined_rule(e,a)
{

	var rule = a.value.replace("qm[i]","qm"+qmv.id);
	rule = rule+", "+rule.replace(/div/g,"ul");
	
	
	if (rule)
		qmv_custom_rule_parse_rule(rule);


}


function qmv_custom_rule_parse_rule(rule)
{
	

	var o_item = document.getElementById("qmvccc_menu_group_items");
	var o_container = document.getElementById("qmvccc_menu_group_container");
	var o_title = document.getElementById("qmvccc_menu_group_title");
	var o_divider = document.getElementById("qmvccc_menu_group_divider");
	var o_contentbox = document.getElementById("qmvccc_menu_group_contentbox");

	var o_both = document.getElementById("qmvccc_menu_type_both");
	var o_pure = document.getElementById("qmvccc_menu_type_pure");
	var o_hybrid = document.getElementById("qmvccc_menu_type_hybrid");

	var o_level = document.getElementById("qmvccc_sub_level");
	var o_target = document.getElementById("qmvccc_target");
	var o_custname = document.getElementById("qmvccc_custom_class_name");
	
	var o_add_a = document.getElementById("qmvccc_menu_add_a");
	var o_add_span = document.getElementById("qmvccc_menu_add_span");
	var o_add_div = document.getElementById("qmvccc_menu_add_div");
	var o_add_img = document.getElementById("qmvccc_menu_add_img");
	var o_addnone = document.getElementById("qmvccc_menu_add_none");

	var o_pre = document.getElementById("qmvccc_pre_defined");
	
	

	if ((rule.indexOf("div#qm")+1) && (rule.indexOf("ul#qm")+1))
		o_both.checked = true;
	else		
	{
		if (rule.indexOf("div#qm")+1)
			o_hybrid.checked = true;

		if (rule.indexOf("ul#qm")+1)
			o_pure.checked = true;
	}

	var wrule = rule.split(",")[0];

	var ops = o_pre.getElementsByTagName("OPTION");
	for (var i=0;i<ops.length;i++)
	{
		var tpr = ops[i].value;
		if (tpr==wrule)
			ops[i].selected = true;
		
	}

	o_container.checked = true;
	o_addnone.checked = true;
	var subs = 0;
	var got_cust_name;

	var pt = wrule.split(" ");
	for (var i=1;i<pt.length;i++)
	{
		pt[i].replace(/ /g,'');
		if (pt[i])
		{
		
			if (pt[i].indexOf(".qmsub")==0)
			{
				subs++;
				o_container.checked = true;
			}
			else if (pt[i].indexOf(".qmitem")==0)
				o_item.checked = true;
			else if (pt[i].indexOf(".qmtitle")==0)
				o_title.checked = true;
			else if (pt[i].indexOf(".qmdivider")==0)
				o_divider.checked = true;
			else if (pt[i].indexOf(".qmcbox")==0)
				o_contentbox.checked = true;
			else if (pt[i].indexOf("a")==0)
				o_add_a.checked = true;
			else if (pt[i].indexOf("span")==0)
				o_add_span.checked = true;
			else if (pt[i].indexOf("div")==0)
				o_add_div.checked = true;
			else if (pt[i].indexOf("img")==0)
				o_add_img.checked = true;
			
			var cp = 0;
			if ((cp = pt[i].indexOf(".qmc_"))>-1)
			{

				pt[i] = pt[i].substring(cp+5);

				if (pt[i].indexOf(":")+1)
					pt[i] = pt[i].substring(0,pt[i].indexOf(":"))

				if (pt[i].indexOf(".")+1)
					pt[i] = pt[i].substring(0,pt[i].indexOf("."))


				got_cust_name = true;
				o_custname.value = pt[i];
			}
			

		}
	}

	if (!got_cust_name)
		o_custname.value = "";
	
	o_level.value = subs;
	
	var match = false;
	var ch = document.getElementById("qmvccc_target");
	if (ch && (ch=ch.childNodes))
	{
		for (var i=0;i<ch.length;i++)
		{
			var gv = ch[i].getAttribute("value");
			if (wrule.indexOf(gv)+1)
			{
				match = true;
				o_target.value = gv;
			
			}
	
		}
	
	}
	
	if (!match) o_target.value = "static";		
	qmv_display_rule_result();
	
	
}



function qmv_display_rule_result()
{

	var rs = qmv_custom_rule_build(true);
	if (!rs) rs = "";

	document.getElementById("qmvccc_rule_result").innerHTML = rs+" {}";

}


function qmv_rule_truncate(t,len,reverse)
{
	if (reverse)
	{
		if (t.length>len)
		{	
			return "..."+t.substring(t.length-len,t.length-1);
		}
	}
	else
	{
		if (t.length>len)
			return t.substring(0,len-3)+"...";
	}

	return t;

}


function qmv_custom_rule_edit(e,a)
{
	e = e || event;

	if (a[qp].mirror) a = a[qp].mirror.getElementsByTagName("SPAN")[0];

	var or = a[qp].cdiv.getAttribute("orule");
	qmv_show_dialog("custom_rule",a[qp].cdiv,null,null,null,null,null,or)


	qm_kille(e);
	return false;
}


function qmv_custom_rule_delete(e,a,obj)
{
	var close_setbox;

	var atag;
	if (obj)
		atag = obj;
	else
	{
		if (a[qp].mirror)
		{
			a = a[qp].mirror.getElementsByTagName("SPAN")[0];
			close_setbox = true;
		}

		atag = a[qp];
	}

	var rule = atag.cdiv.getAttribute('rule');
	rule = rule.replace("qm[i]","qm"+qmv.id);
	


	var c=0;
	while (qmv["style_rules"+c])
	{
		if (qmv_lib_update_remove_rule(qmv["style_rules_sheet"+c],qmv["style_rules"+c],rule))
			break;

		c++;
	}


	var inps = atag.cdiv.getElementsByTagName("INPUT");
	for (var i=0;i<inps.length;i++)
	{
		inps[i][qp].removeChild(inps[i]);

	}

	atag.cdiv[qp].removeChild(atag.cdiv);
	atag[qp].removeChild(atag);
	
	

	qmv_update_tree_after_load(document.getElementById("qmvtree_custom_rules"));


	qmv_set_all_subs_to_default_position(true);
	qmv_update_all_addons();
	qmv_position_pointer();

	if (close_setbox)
		qmv_hide_dialog(false,false,true);


}


function qmv_update_tree_after_load(n)
{

	var tbi = qmad.binit;
	qmad.binit = "";
	
	qmc_create(n,false,0,0,false,null,null,null,null,2);
	qmad.binit = tbi;
	
	if (qmv.loaded)
	{
		qm_vtree_init_items(n,true,"standard");
		qmv_ibullets_init_items(n);
	}

}


function qmv_warn_pure()
{


	qmv_show_dialog("alert",null,"<b>Important Information!</b><br><br>Pure CSS styles are only visible when running a pure css menu type without JavaScript. Save and view your menu with JavaScript disabled in the browser to see your style settings for this rule.",500);
	

}

function qmv_custom_class_get_list()
{

	

	var rar = new Object();
	var count = 0;

	var c=0;
	while (qmv["style_rules"+c])
	{


		//var rules = qmv.style_rules;
		var rules = qmv["style_rules"+c];

		for (var i=0;i<rules.length;i++)
		{
		
			var st = rules[i].selectorText.toLowerCase();
			var loc;
			if (((loc = st.indexOf(".qmc_"))+1) && (!qmad.br_ie || (st.indexOf("ul#qm")==-1)))
			{	
			

				rar["a"+count] = new Object();
				rar["a"+count].rule = st;

				var cn = st.substring(loc+5);
				if ((loc = cn.indexOf(" "))+1)
					cn = cn.substring(0,loc)

				if ((loc = cn.indexOf(":"))+1)
					cn = cn.substring(0,loc)

				if ((loc = cn.indexOf("."))+1)
					cn = cn.substring(0,loc)

				if ((loc = cn.indexOf(","))+1)
					cn = cn.substring(0,loc)


				rar["a"+count].showclass = cn;
				rar["a"+count].classname = "qmc_"+cn;
				rar["a"+count].display = cn+" ["+st+"]";
				rar["a"+count].rule = st;

				count++;
				
			}
		}

		c++;
	}
	
	return rar;

}


function qmv_custom_classes_set_selected_item(match)
{

	var sl = document.getElementById("qmvacc_classes");
	var ch = sl.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		var tval = ch[i].getAttribute("rule",2);
		if (match==tval)
			ch[i].selected = true;
		else
			ch[i].selected = false;
		
	}
	
}


function qmv_custom_classes_initialize_list()
{
	var sl = document.getElementById("qmvacc_classes");
	
	var ch = sl.childNodes;
	for (var i=0;i<ch.length;i++)
	{
		sl.removeChild(ch[i]);
		i--;
	
	}
	
	var tobj = qmv_custom_class_get_list();
	var go = false;
	for (var i in tobj)
	{
		if (tobj[i])
		{
			var adds = document.createElement("OPTION");
			adds.setAttribute("rule",tobj[i].rule);
			adds.setAttribute("value",tobj[i].classname);
			adds.innerHTML = tobj[i].display;
			sl.appendChild(adds);
			if (!go)
				adds.selected = true;
			
			go = true;
			
		}
	}	

	if (!go)
	{
		var adds = document.createElement("OPTION");
		adds.innerHTML = "No Custom Classes Are Defined";
		sl.appendChild(adds);
	}


}


function qmv_custom_class_list_change(e,no_select)
{
	
	var ebutton = document.getElementById("qmvacc_edit");
	var a = document.getElementById("qmvacc_classes");
	
	if (!a.value)
		ebutton.style.visibility = "hidden";
	else
		ebutton.style.visibility = "inherit";


	var is_ai = document.getElementById("qmvacc_apply_allitems").checked;
	var is_ad = document.getElementById("qmvacc_apply_alldividers").checked;
	var is_at = document.getElementById("qmvacc_apply_alltitles").checked;
	var is_spec_item = document.getElementById("qmvacc_apply_item").checked;
	var is_spec_sub = document.getElementById("qmvacc_apply_container").checked;
	var is_spec_column = document.getElementById("qmvacc_apply_column").checked;

	
	var sobjs = new Object();
	var mc = 0;
	if (is_ai || is_ad || is_at)
	{
		
		var ch;
		if (qmv.cur_column)
			ch = qmv.cur_column.childNodes;
		else
			ch = qmv.cur_sub.childNodes;
			
		for (var i=0;i<ch.length;i++)
		{
			var ti = ch[i];
			if (qmv.cur_column)
			{
				var tch = ch[i].childNodes;
				for (var j=0;j<tch.length;j++)
				{
					if (tch[j].qmmi)
					{
						ti = tch[j];
						break;
					}
				}
			}
				
			if (ti && ti.tagName)
			{
				if ((is_ai && ti.tagName=="A") || (is_ad && ti.tagName=="SPAN" && ti.className.indexOf("qmdivider")+1) || (is_at && ti.tagName=="SPAN" && ti.className.indexOf("qmtitle")+1))
				{
					
					sobjs["a"+i] = new Object();
					sobjs["a"+i] = ti;
					mc++
				}

			}
		
		}

	}
	else if (is_spec_item || is_spec_sub || is_spec_column)
	{
		sobjs.a0 = new Object();
		mc = 1;
		if (is_spec_item)
			sobjs.a0=qmv.cur_item;
		else if (is_spec_sub)
			sobjs.a0=qmv.cur_sub;
		else if (is_spec_column)
			sobjs.a0=qmv.cur_column;
			
	}

	var apmsg = "[applied]&nbsp;&nbsp;&nbsp;";
	var ops = a.getElementsByTagName("OPTION");
	for (var i=0;i<ops.length;i++)
	{
		
		var val;
		if (val = ops[i].getAttribute("value"))
		{
			var j;
			var match;
			var nin = ops[i].innerHTML;

			var jc = 0;
			for (j in sobjs)
			{
				if (sobjs[j] && sobjs[j].className.indexOf(val)+1)
				{
					jc ++;
					if (mc==jc)
					{
						if (!no_select)
							ops[i].selected = true;

						if (nin.indexOf(apmsg)==-1)
							ops[i].innerHTML = apmsg+ops[i].innerHTML;

						match = true;
					}
					
				}
				
				if (match)
					break;
				
			}

			if (!match)
			{
				if (nin.indexOf(apmsg)+1)
					ops[i].innerHTML = nin.substring(apmsg.length);
			}

		}

	}	
	

}


