function qmv_apply_custom_class(is_delete)
{

	var o_item = document.getElementById("qmvacc_apply_item").checked;
	var o_container = document.getElementById("qmvacc_apply_container").checked;
	var o_column = document.getElementById("qmvacc_apply_column").checked;
	var o_allitems = document.getElementById("qmvacc_apply_allitems").checked;
	var o_alldividers = document.getElementById("qmvacc_apply_alldividers").checked;
	var o_alltitles = document.getElementById("qmvacc_apply_alltitles").checked;

	
	var go = false;

	var cls = "";
	var ops = document.getElementById("qmvacc_classes").options;
	for (var k=0;k<ops.length;k++)
	{
		
		if (ops[k].selected) 
		{
			cls = ops[k].value;
		
			if (o_item)
			{
				if (is_delete)
					qm_arc(cls,qmv.cur_item);
				else
					qm_arc(cls,qmv.cur_item,true);
				
				qmvi_report_add_line("edits","undo","custom_class","","",qmv.cur_item,null,null,cls,is_delete);

			}	
			else if (o_container)
			{
				if (!qm_a(qmv.cur_sub))
				{
					if (is_delete)	
						qm_arc(cls,qmv.cur_sub);
					else
						qm_arc(cls,qmv.cur_sub,true);

					qmvi_report_add_line("edits","undo","custom_class","","",qmv.cur_sub,null,null,cls,is_delete);
				}
				else
					qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>This setting can not be applied to the main container, instead choose a sub menu container.",400);

			}
			else if (o_column)
			{
				if (qmv.cur_column)
				{
					if (is_delete)	
						qm_arc(cls,qmv.cur_column);
					else
						qm_arc(cls,qmv.cur_column,true);

					qmvi_report_add_line("edits","undo","custom_class","","",qmv.cur_column,null,null,cls,is_delete);
				}
				else
					qmv_show_dialog("alert",null,"<b>Setting Not Applied!</b><br><br>A column is not currently selected.",300);

			}
			else
			{
				
				var ch;
				if (qmv.cur_column)
					ch = qmv.cur_column.childNodes;
				else
					ch = qmv.cur_sub.childNodes;
				
				for (var i=0;i<ch.length;i++)
				{
					if (ch[i] && ch[i].tagName)
					{
					
						var ti = ch[i];
						if (qmv.cur_column)
						{
							var tch = ch[i].childNodes;
							for (var j=0;j<tch.length;j++)
							{
								if (tch[j].qmmi)
								{
									ti = tch[j];
									break;
								}
							}
						}
					
						if ((o_allitems && ti.tagName=="A") || (o_alldividers && ti.tagName=="SPAN" && ti.className.indexOf("qmdivider")+1) || (o_alltitles && ti.tagName=="SPAN" && ti.className.indexOf("qmtitle")+1))
						{
							if (is_delete)	
								qm_arc(cls,ti);
							else
								qm_arc(cls,ti,true);

							qmvi_report_add_line("edits","undo","custom_class","","",ti,null,null,cls,is_delete);
						}
					}
				}	

			}


			go = true;


		}

	}


	if (go)
	{
		//lasdkfj asldkfj ;lasfkjlasdfkj las fj
		qmv_custom_class_list_change(new Object());

		qm_sam_stretch(qmv.cur_sub);
		qmv_reselect_all_menu_items_from_root_for_big_update(true);
		
		qmv_update_all_addons();
		qmv_position_pointer();	
		
		qmv_htmledit_update_from_visual_change();	

		return true;
	}
	else
	{

		qmv_show_dialog("alert",null,"First select a custom class name from the list to apply.",400);


	}



}



function qmv_apply_class_action(type)
{


	if (type=="add_new")
	{
		qmv_add_custom_css_rule(true);
		qmv_custom_rule_parse_rule("div#qm[i] .qmc_mystatic, ul#qm[i] .qmc_mystatic");
	}
	if (type=="edit_rules" || type=="edit_styles")
	{
		var er = document.getElementById("qmvacc_classes");
		var srule = "";

		var ops = er.getElementsByTagName("OPTION");
		for (var i=0;i<ops.length;i++)
		{
			if (ops[i].getAttribute("value")==er.value)
				srule=ops[i].getAttribute("rule");

		}
	

		var n = document.getElementById("qmvtree_custom_rules").getElementsByTagName("DIV");
		for (var i=0;i<n.length;i++)
		{
			
			var rr = n[i].getAttribute("orule");
			
			if (rr)
			{

				rr = rr.replace("qm[i]","qm"+qmv.id);
				rr = rr.replace("qm[i]","qm"+qmv.id);

				if (rr.indexOf(srule)+1)
				{
					if (type=="edit_rules")
					{					
						var or = n[i].getAttribute("orule");
						qmv_show_dialog("custom_rule",n[i],null,null,null,null,null,or,null,true)
						
					}
					else
					{
						qmv_display_setbox(n[i].idiv);
						
					}
					
					break;

				}

			}

		}


	}


}


