function qmvi_styleanim_advanced_init_dialog(qmd,owner)
{

	var cb = document.getElementById("qmv_styleanim_dialog_checkbox_option_reset");
	if (cb)
	{
		
		var advanced_cb = document.getElementById("qmv_styleanim_advanced_dialog_checkbox_option_reset");
		if (cb.checked)
			advanced_cb.checked = true;
		else
			advanced_cb.checked = false;
	}

	cb = document.getElementById("qmv_styleanim_dialog_checkbox_option_applytype");
	if (cb)
	{
		
		var applytype_cb = document.getElementById("qmv_styleanim_advanced_dialog_checkbox_option_applytype");
		if (cb.checked)
			applytype_cb.checked = true;
		else
			applytype_cb.checked = false;
	}	
}


function qmvi_styleanim_init_dialog(qmd,owner)
{
	var type = '';

	var apply_styles = document.getElementById("qmvi_styleanim_styles_apply");
	var choose_styles = document.getElementById("qmvi_styleanim_styles_choose");
	
	qmv.sanimp.stylelist = new Object();
	qmv.sanimp.appliedlist = new Object();
	qmv.sanimp.stylevals = new Object();
	
	
	qmv.sanimp.stylelist[qmv.css_prefix2+"Transform"] = "CSS3 Transform";
	qmv.sanimp.stylelist.space1 = "----------";
	qmv.sanimp.stylelist.opacity = "Opacity";
	qmv.sanimp.stylelist.backgroundColor = "Background Color";
	qmv.sanimp.stylelist.borderColor = "Border Color";
	
	if (qmv.sanimp.group!="subs")
		qmv.sanimp.stylelist.color = "Font Color";
		
	qmv.sanimp.stylelist.space2 = "----------";
	//qmv.sanimp.stylelist.clip = "Clipping Rectangle";
	qmv.sanimp.stylelist.top = "Top Position";
	qmv.sanimp.stylelist.left = "Left Position";
	qmv.sanimp.stylelist.width = "Width";
	qmv.sanimp.stylelist.height = "Height";
	qmv.sanimp.stylelist.space3 = "----------";
	qmv.sanimp.stylelist.boxShadow = "Box Shadow";
	qmv.sanimp.stylelist.borderRadius = "Border Radius";
	qmv.sanimp.stylelist.borderWidth = "Border Width";
	qmv.sanimp.stylelist.space4 = "----------";
	qmv.sanimp.stylelist.padding = "Padding";
	qmv.sanimp.stylelist.margin = "Margin";
	
	if (qmv.sanimp.group!="subs")
		qmv.sanimp.stylelist.fontSize = "Font Size";
	
	
	qmv.sanimp.stylevals[qmv.css_prefix2+"Transform"] = {start:"scale(0) rotate(0deg)",end:"scale(1) rotate(360deg)"};
	qmv.sanimp.stylevals.opacity = {start:"0",end:"1"};
	qmv.sanimp.stylevals.color = {start:"#ffffff",end:"#000000"};
	qmv.sanimp.stylevals.backgroundColor = {start:"#ffffff",end:"#000000"};
	qmv.sanimp.stylevals.borderColor = {start:"#ffffff",end:"#000000"};
	qmv.sanimp.stylevals.top = {start:"100px",end:"0px"};
	qmv.sanimp.stylevals.left = {start:"100px",end:"0px"};
	qmv.sanimp.stylevals.width = {start:"0px",end:"200px"};
	qmv.sanimp.stylevals.height = {start:"0px",end:"200px"};
	qmv.sanimp.stylevals.boxShadow = {start:"0px 0px 0px #666666",end:"0px 0px 40px #666666"};
	qmv.sanimp.stylevals.borderRadius = {start:"0px 0px 0px 0px",end:"12px 12px 12px 12px"};
	qmv.sanimp.stylevals.borderWidth = {start:"1px 1px 1px 1px",end:"10px 1px 10px 1px"};
	qmv.sanimp.stylevals.padding = {start:"0px 0px 0px 0px",end:"15px 15px 15px 15px"};
	qmv.sanimp.stylevals.margin = {start:"-100px 0px 0px 0px",end:"0px 0px 0px 0px"};
	qmv.sanimp.stylevals.fontSize = {start:"1px",end:"13px"};
	
	//reverse default values for hide types
	if (qmv.sanimp.type=="hide")
	{
	
		for (var i in qmv.sanimp.stylevals)
		{
			var tstart = qmv.sanimp.stylevals[i].start;
			var tend = qmv.sanimp.stylevals[i].end;
			qmv.sanimp.stylevals[i] = {start:tend,end:tstart};
		}
		
	}
		
	var def;
		
	if (owner)
	{
		if (owner.qm_styleanim_isclip)
			type = 'editclip';
		else if (owner.qm_styleanim_isnew)
			type = 'new';
	
	}
	
	var frinp = document.getElementById("qmvi_df_edge_styleanimframes");
	var rset = document.getElementById("qmv_styleanim_dialog_checkbox_option_reset");
	var aptype = document.getElementById("qmv_styleanim_dialog_checkbox_option_applytype");
	if (type=="editclip")
	{
		//initialize the values
		var cl = owner.qm_clip;
		
		var i;
		for (i in cl)
		{
			if (cl[i])
			{
				qmv.sanimp.stylevals[i].start = cl[i].start;
				qmv.sanimp.stylevals[i].end = cl[i].end;

				qmv.sanimp.appliedlist[i] = qmv.sanimp.stylelist[i];
				if (!def) def = i;
			}
		}
			
		frinp.value = owner.qm_frames;
				
		if (owner.qm_reset)
			rset.checked = true;
		else
			rset.checked = false;
		
		
		if (owner.qm_aptype=='inline')
			aptype.checked = true;
		else
			aptype.checked = false;	
	}
	else
	{
		frinp.value = 20;
		
	}
		
	qmvi_styleanim_dialog_create_lists(def);
	qmv_styleanim_enable_disable_start_stop();
}

function qmv_styleanim_enable_disable_start_stop()
{
	
		
	var is_empty = true;
	for (var i in qmv.sanimp.appliedlist)
	{
		if (qmv.sanimp.appliedlist[i])
		{
			is_empty = false;
			break;
		}
	}
	
	
	var sec = document.getElementById('qmvi_styleanim_dialog_startend_container');
	var cov = document.getElementById('qmvi_styleanim_dialog_startend_container_cover');
	if (is_empty)
	{
		sec.style.visibility = "hidden";
		cov.style.visibility = "inherit";
		
	}
	else
	{
		sec.style.visibility = "inherit";
		cov.style.visibility = "hidden";
		
	}
	

}


function qmv_styleanim_matchend_update_dialog(type,owner)
{

	
	var l = 0;
	var td = document.getElementById("qmv_styleanim_matchend_dialog_option_count");
	if (td && (l = td.getAttribute("animcount")))
		l = parseInt(l);
	else
		l = 0;
	
	var rule = "#qm[i] .qmsub";
	if (qmv.sanimp.group=="items_main")
		rule = "#qm[i].qmmc .qmitem-m.qmactive";
	if (qmv.sanimp.group=="items_sub")
		rule = "#qm[i].qmmc .qmitem-s.qmactive";
	
	
	
	var c = 0;
	for (var i=0;i<l;i++)
	{
		var cb = document.getElementById("qmv_styleanim_matchend_dialog_option"+c);
		if (cb && cb.checked)
		{
			
			var sname = cb.getAttribute("animname");
			var val = cb.getAttribute("animvalue");
			
			if (sname && val)
			{
				if (owner && owner.askmatch)
					rule = owner.askmatch[sname][1];
				
				var inp = qmv_find_update_tree_value("css",rule,sname,val,false,true);
				if (inp) qmv_evt_update_tree_value(inp);
			}
			c++;
		}
	}

	
	

}

function qmv_styleanim_preset_update_dialog(type,owner)
{

	var sb = document.getElementById("qmvi_styleanim_preset_choose");
	if (sb.value)
	{
			
		var ads = "styleanim_"+qmv.sanimp.group+"_"+qmv.sanimp.type;
		var inp = qmv_find_update_tree_value("addon","styleanim",ads,sb.value,false,true);
		if (inp)
		{
			qmv.sanimp.cur_clip = [0,0];
			
			qmv_evt_update_tree_value(inp);
			qmv_styleanim_panel_addremove_addon(true);
			
			var sbc = sb.childNodes[sb.selectedIndex];
			if (sbc)
			{
							
				if (qmv.sanimp.group!="subs")
				{
					
					var sval = "false";
					if (sbc.quickstop) sval = "true";
				
					var nt = "main";
					if (qmv.sanimp.group=="items_sub")
						nt = "sub";
						
					inp = qmv_find_update_tree_value("addon","styleanim", "styleanim_item_"+nt+"_quickstop",sval,false,true);
					qmv_evt_update_tree_value(inp);
					
				}
				
				
				if (sbc.askmatch)
				{
					
					var sown = {askmatch:sbc.askmatch}
					qmv_show_dialog('styleanim_match_end_vals',sown,null,null,null,null,null,null,null,null,true);
					
				}
				
				
			}
		}
		
		
		return true;
	}
	else
		qmv_show_dialog("alert",null,"First select an animation from the list.",320);

}

function qmv_styleanim_advanced_update_dialog(type,owner)
{

	var cb = document.getElementById("qmv_styleanim_dialog_checkbox_option_reset");
	if (cb)
	{
		var advanced_cb = document.getElementById("qmv_styleanim_advanced_dialog_checkbox_option_reset");
		if (advanced_cb.checked)
			cb.checked = true;
		else
			cb.checked = false;
	}
	
	var cb = document.getElementById("qmv_styleanim_dialog_checkbox_option_applytype");
	if (cb)
	{
		var advanced_cb = document.getElementById("qmv_styleanim_advanced_dialog_checkbox_option_applytype");
		if (advanced_cb.checked)
			cb.checked = true;
		else
			cb.checked = false;
	}

}

function qmv_styleanim_panel_delete_selected_clip()
{
	
	var clobj = qmvi_transition_panel_timeline_get_clip_select_object(qmv.sanimp.cur_clip);
	if (clobj)
	{
		clobj[qp].removeChild(clobj);
		
		qmv.sanimp.cur_clip = [0,0];
		
		var has_clip = qmvi_transition_panel_update_timeline();
		qmv_styleanim_panel_autoturn_addon_onoff();
	
	}
	else
	{
		qmv_show_dialog("alert",null,"The timeline is empty, there are no clips to delete.",360);
	
	}

}


function qmv_styleanim_update_dialog(type,owner)
{

	setobj = new Object();
		
		
	var sobj = new Object();
	var is_empty = true;
	for (var i in qmv.sanimp.appliedlist)
	{
		if (qmv.sanimp.appliedlist[i])
		{
			sobj[i] = qmv.sanimp.stylevals[i];
			is_empty = false;
		}
	}
		
	setobj.qm_clip = sobj;
		
	
	//check the clip for start and end values
	var good_vals = false;
	for (var i in setobj.qm_clip)
	{
		if (setobj.qm_clip[i])
		{
			if (!setobj.qm_clip[i].start && !setobj.qm_clip[i].end)
			{
				setobj.qm_clip[i] = null;
				continue;
			}
				
			good_vals = true;
			if (!setobj.qm_clip[i].start)
				setobj.qm_clip[i].start = setobj.qm_clip[i].end;
				
			if (!setobj.qm_clip[i].end)
				setobj.qm_clip[i].end = setobj.qm_clip[i].start;
		}
	}
	
	if (!good_vals)
		setobj.qm_clip =new Object();
		
	
	var fval = document.getElementById("qmvi_df_edge_styleanimframes").value;
	if (!fval)
		fval = 1;
	else
		fval = parseInt(fval);
	
	setobj.qm_frames = fval;
		
	var rset = document.getElementById("qmv_styleanim_dialog_checkbox_option_reset").checked;
	if (rset)
		setobj.qm_reset = true;
	else
		setobj.qm_reset = false;
	
	var aptype = document.getElementById("qmv_styleanim_dialog_checkbox_option_applytype").checked;
	if (aptype)
		setobj.qm_aptype = 'inline';
	else
		setobj.qm_aptype = 'stylesheet';
	
	
	if (type=="add clip")
	{
		var nclip = qmvi_transition_panel_create_timeline_new_clip(setobj.qm_frames,setobj.qm_clip,setobj.qm_reset,setobj.qm_aptype);
		owner[qp].appendChild(nclip);
		qmv.sanimp.cur_clip = qmvi_transition_panel_timeline_get_clip_select_index(nclip);
	}
	else
	{
		var clo = qmvi_transition_panel_timeline_get_clip_select_object(qmv.sanimp.cur_clip);
		
		for (var i in setobj)
			clo[i] = setobj[i];
		
	}
	
	if (is_empty)
		qmv.sanimp.cur_clip = [0,0];
	
		
	var has_clip = qmvi_transition_panel_update_timeline();
	qmv_styleanim_panel_autoturn_addon_onoff();
		
}


function qmv_styleanim_panel_autoturn_addon_onoff()
{

	//check if there are any animations set and auto check / uncheck the addon status
	var ctypes = "styleanim_subs_show styleanim_subs_hide styleanim_items_main_show styleanim_items_main_hide styleanim_items_sub_show styleanim_items_sub_hide";
	ctypes = ctypes.split(" ");
	var f1 = false;
	for (var i=0;i<ctypes.length;i++)
	{
		if (qmv_find_update_tree_value("addon","styleanim",ctypes[i],null,true))
			f1 = true;
	}
	qmv_styleanim_panel_addremove_addon(f1);

}



function qmv_styleanim_panel_addremove_addon(status)
{

	//add or remove the styleanim add-on
	var cb = document.getElementById("qmv_iadd_styleanim");
	if (status)
	{
		if (!cb.checked)
		{
			
			cb.checked = true;
			qmv_evt_addremove_addon(new Object(),cb);
		}
	}
	else
	{
		if (cb.checked)
		{
			cb.checked = false;
			qmv_evt_addremove_addon(new Object(),cb);
		}
	}


}

function qmv_styleanim_startend_change()
{

	//warn if the number of values are different
	var sobj = document.getElementById('qmvi_df_edge_startvalue');
	var eobj = document.getElementById('qmvi_df_edge_endvalue');
	if (sobj.value && eobj.value)
	{
		var et = eobj.value.replace(/ ,/g,"");
		et = et.replace(/, /g,"");
		
		var st = sobj.value.replace(/ ,/g,"");
		st = st.replace(/, /g,"");
		
		et = et.split(" ");
		st = st.split(" ");
		
		if (et.length!=st.length)
		{
			qmv_show_dialog("alert",window,"<b>Warning:</b> The number of start and end values must match and be of the same type for the style animator to function correctly.",450);
		}
		
	}

	
	//save the values
	var apply_styles = document.getElementById("qmvi_styleanim_styles_apply");
	if (apply_styles.value)
	{
		qmv.sanimp.stylevals[apply_styles.value].start = document.getElementById('qmvi_df_edge_startvalue').value;
		qmv.sanimp.stylevals[apply_styles.value].end = document.getElementById('qmvi_df_edge_endvalue').value;
	}
	
	

}


function qmvi_styleanim_dialog_select_style()
{

	var apply_styles = document.getElementById("qmvi_styleanim_styles_apply");
	var stype = apply_styles.value;
	var stlow = stype.toLowerCase();
	
	var scontainer = document.getElementById("qmvi_styleanim_dialog_start_container");
	var econtainer = document.getElementById("qmvi_styleanim_dialog_end_container");
	
	
	if (!stype || stype=="none")
		return;
		
	var dtype = 'unit';
	if (stlow.indexOf("color")+1)
		dtype='color';
	else if (stype=="top" || stype=="left" || stype=="width" || stype=="height" || stype=="fontSize")
		dtype='unit';
	else if (stype=="margin" || stype=="borderWidth" || stype=="padding" || stype=="borderRadius")
		dtype = "edge-"+stype.toLowerCase();
	else if (stype=="opacity")
		dtype = "float";
	else if (stype==(qmv.css_prefix2+"Transform"))
		dtype = "transform";
	else
		dtype=stype.toLowerCase();
	
	
	
	var ih = '';
	ih = qmv_dialog_edge_part("startvalue",dtype,'Start Value',"qmv_styleanim_startend_change()",true);
	scontainer.innerHTML = ih;
		
	ih = qmv_dialog_edge_part("endvalue",dtype,'End Value',"qmv_styleanim_startend_change()",true);
	econtainer.innerHTML = ih;
	
	//apply the default / saved values
	var inp_s = document.getElementById("qmvi_df_edge_startvalue");
	var inp_e = document.getElementById("qmvi_df_edge_endvalue");
	
	inp_s.value = qmv.sanimp.stylevals[stype].start;
	inp_e.value = qmv.sanimp.stylevals[stype].end;
	if (stlow.indexOf("color")+1)
	{
		qmvi_set_dialog_color(inp_s.value,document.getElementById('qmvi_df_edge_button_startvalue'));
		qmvi_set_dialog_color(inp_e.value,document.getElementById('qmvi_df_edge_button_endvalue'));
	}

}

