function qmvi_styleanim_show_match_end_vals_dialog()
{
	if (qmv.sanimp.type=="show")
	{
		var ci = 0;
		for (var i in qmv.sanimp.appliedlist)
		{
			if (qmv.sanimp.appliedlist[i])
			{
				var ev;
				if ((ev = qmv.sanimp.stylevals[i]) && (ev = ev.end))
				{
					qmv_show_dialog('styleanim_match_end_vals',this,null,null,null,null,null,null,null,null,true);
					return;
					
				}
			}
		}
		
		qmv_show_dialog("alert",null,"Before matching end values apply animation styles to the clip.",440);
	}
	else
		qmv_show_dialog("alert",null,"Match end values are available with 'show' animations only.",440);
	

}

