function qmvi_transition_tab_switch(e,a)
{
	
	if (qmv.cur_dialog && qmv.cur_dialog.type && qmv.cur_dialog.type.indexOf("styleanim")+1)
		qmv_hide_dialog();

	var ra = new Array("subs","items_main","items_sub");

	

	var on = null;
	for (var i=0;i<ra.length;i++)
	{

		var tab = document.getElementById("qmvi_transition_tab_"+ra[i]);
		if (tab!=a)
		{
			
			tab.style.backgroundColor = "";
			if (qmad.br_ie)
				tab.style.cursor = "hand";
			else
				tab.style.cursor = "pointer";
			
		}
		else
			on = ra[i];

	}
	
	if (on)
	{
		
		a.style.backgroundColor = "#f3f3f3";
		a.style.cursor = "default";
		
	}


	//save the group tab state	
	qmv.sanimp.group = on;
	qmv.sanimp.cur_clip = [0,0];
	qmvi_transition_panel_initialize();
		

}


function qmvi_report_tab_switch(e,a)
{

	
	var ra = new Array("all","edits","warnings","info");


	var on = null;
	for (var i=0;i<ra.length;i++)
	{

		var tab = document.getElementById("qmvi_report_tab_"+ra[i]);
		if (tab!=a)
		{
			
			tab.style.backgroundColor = "";
			if (qmad.br_ie)
				tab.style.cursor = "hand";
			else
				tab.style.cursor = "pointer";
			
		}
		else
			on = ra[i];

	}
	
	if (on)
	{
		
		a.style.backgroundColor = "#f3f3f3";
		a.style.cursor = "default";
		qmv.report.tab = on;
	}


	qmvi_report_tab_switch_hide_show_items();

}

function qmvi_bbar_tab_switch(e,a)
{

	var ra = new Array("itemeditor","transitions","reportlog");
	var ra2 = new Array("qmvi_itemeditor_panel","qmvi_transition_panel","qmvi_report_panel");

	var on = null;
	for (var i=0;i<ra.length;i++)
	{

		var tab = document.getElementById("qmvi_bbar_tab_"+ra[i]);
		var panel = document.getElementById(ra2[i]);
		if (tab!=a)
		{
			tab.style.backgroundColor = "";
			tab.style.borderColor = "";
			if (ra2[i]!="qmvi_report_panel") panel.style.visibility = "hidden";
			if (qmad.br_ie)
				tab.style.cursor = "hand";
			else
				tab.style.cursor = "pointer";

		}
		else
		{
			on = ra[i];
				
			qmv_persistent_save_setting("bottom_bar_tab_state",on)
				
			if (on=="itemeditor")
				qmv_htmleditor_init_dialog(document.getElementById("qmv_edittext_field"),true);	
			
			if (ra2[i]!="qmvi_report_panel")
				panel.style.visibility = "inherit";
			
		}

	}
	
	if (on)
	{
		
		a.style.backgroundColor = "#e7eaed";
		a.style.borderColor = "#e7eaed #666 #666 #666";
		a.style.cursor = "default";
		
	}

}



function qmvi_report_tab_switch_hide_show_items()
{

	var ro = document.getElementById("qmvi_report_panel_data_inner");
	var ch = ro.childNodes;
	
	for (var i=0;i<ch.length;i++)
	{
		if (ch[i].tagName=="DIV")
		{
			var section = ch[i].getAttribute("section");


			if (qmv.report.tab=="all" || section==qmv.report.tab)
				ch[i].style.display = "block";
			else
				ch[i].style.display = "none";

		}

	}

}


function qmvi_report_mark_line(e,a)
{
	
	if (qmv["report"+qmv.id].marked)
		qmv["report"+qmv.id].marked.firstChild.style.visibility = "hidden";

	a.firstChild.style.visibility = "visible";
	
	qmv["report"+qmv.id].marked_index = a.getAttribute("index");
	qmv["report"+qmv.id].marked = a;

	var st = a[qp].scrollTop;
	var wh = a[qp].offsetHeight;
	var ot = a.offsetTop;

	if (ot-st>wh)
		a[qp].scrollTop = ot-wh;
	else if ((ot-a.offsetHeight)<st)
		a[qp].scrollTop = (ot-a.offsetHeight-5);
	

	if (qmvi_report_get_next_undo_redo("undo"))
	{
		var cb = document.getElementById("qmvi_report_button_undo");
		cb.src = qmv.base+"images/qmv_r_button_undo.gif";
		cb = document.getElementById("qmvbb_button_img_undo");
		cb.src = qmv.base+"images/qmv_bb_undo.gif";
	}
	else
	{
		cb = document.getElementById("qmvi_report_button_undo");
		cb.src = qmv.base+"images/qmv_r_button_undo_disabled1.gif";
		cb = document.getElementById("qmvbb_button_img_undo");
		cb.src = qmv.base+"images/qmv_bb_undo_off.gif";
	}
		
	if (qmvi_report_get_next_undo_redo("redo"))
	{
		var cb = document.getElementById("qmvi_report_button_redo");
		cb.src = qmv.base+"images/qmv_r_button_redo.gif";
		cb = document.getElementById("qmvbb_button_img_redo");
		cb.src = qmv.base+"images/qmv_bb_redo.gif";
	}
	else
	{
		cb = document.getElementById("qmvi_report_button_redo");
		cb.src = qmv.base+"images/qmv_r_button_redo_disabled1.gif";
		cb = document.getElementById("qmvbb_button_img_redo");
		cb.src = qmv.base+"images/qmv_bb_redo_off.gif";
	}

	

	//qmvi_report_disable_undo_and_redo_buttons();
	

}



