function qmvi_vd_size_csshtml_panel(mp,a,ad,show)
{

	if (!mp)
		mp = qmv.qmvi_design_panel;

	if (!a)
		a = document.getElementById("qmvi_csshtml_panel");

	if (!ad)
		ad = document.getElementById("qmvi_csshtml_panel_data");

	
		
	var padding_adjust = 50;
	

	a.style.top = mp.style.top;
	a.style.left = mp.style.left;
	a.style.width = parseInt(mp.style.width)+padding_adjust+'px';
	a.style.height = parseInt(mp.style.height)+padding_adjust+'px';
	
	
	ad.style.height = "0px";
	ad.style.width = "0px";
	
	ad.style.height = (ad.scrollHeight)+"px";
	ad.style.width = (ad.scrollWidth)+"px";
	
	
	if (show) a.style.visibility = "inherit";

	return ad;
}

function qmvi_v_b_click_direction(a)
{

	var kc;

	if (a.src.indexOf("down_hover.gif")+1)
		kc=40;
	else if (a.src.indexOf("up_hover.gif")+1)
		kc= 38;
	else if (a.src.indexOf("left_hover.gif")+1)
		kc= 37;
	else if (a.src.indexOf("right_hover.gif")+1)
		kc= 39;

	
	qmvi_navigate_menu(kc,qmv.cur_item);

}



function qmvi_navigate_menu(kc,targ)
{


	var na;
	var ish = false;
	
	var c1;
	if (document.defaultView && document.defaultView.getComputedStyle)
		c1 = document.defaultView.getComputedStyle(targ, null).getPropertyValue("float");
	else if (targ.currentStyle)
		c1 = targ.currentStyle.styleFloat;		

	if (c1 && c1.toLowerCase()=="left")
		ish = true;

	var is_multi = false;
	if (targ && targ[qp] && targ[qp].tagName=="DD")
		is_multi = true;
	
	
	if (kc==40) //down
	{
		
		
		if (qmv.addons.tree_menu["on"+qmv.id])
		{

			if (targ.cdiv)
				qmvi_kc_fnl(targ);
			else
			{

				na = qmvi_kc_getnp(targ,"next");
				if (na)
				{
					qm_oo(new Object(),na);
				}
				else if (targ[qp].idiv)
				{
					na = qmvi_kc_getnp(targ[qp].idiv,"next");
					if (na)
						qm_oo(new Object(),na);
				}

			}	

		}
		else
		{
		

			if (targ.cdiv && ish)
			{
				qmvi_kc_fnl(targ);
			}
			else
			{
					
				na = qmvi_kc_getnp(targ,"next");
				if (na)
					qm_oo(new Object(),na);
	
			}
		}
		
	
	}
	else if (kc==38) //up
	{
	
		na = qmvi_kc_getnp(targ,"previous");
		if (na)
		{
			qm_oo(new Object(),na);

		}
		else
		{
			
			
			var pi = qmv_kc_get_parent_item(targ[qp][qp]);
			if (pi)
				qm_oo(new Object(),pi);

	
		}


	}
	else if (kc==39) //right
	{	
		if (is_multi && !targ.cdiv)
		{
			var r = qmvi_get_multi_columns(targ);
			if (r)
			{
				if (r.id>-1 && r.id<r.columns.length-1)
				{
					var sel = r.columns[r.id+1].getElementsByTagName("DD");
					if (sel[0] && sel[0].firstChild)
						qm_oo(new Object(),sel[0].firstChild);
			
				}
			}	
		
		}
		else
		{
			if (!qmv.addons.tree_menu["on"+qmv.id])
			{

				if (ish)
				{
				
					na = qmvi_kc_getnp(targ,"next");
					if (na)
						qm_oo(new Object(),na);
					
			
				}
				else if (targ.cdiv)
				{
				
					qmvi_kc_fnl(targ);

				}

			}
		}


	}
	else if (kc==37) //left
	{	
		if (is_multi)
		{
			var r = qmvi_get_multi_columns(targ);
			if (r)
			{
				if (r.id>0 && r.id<r.columns.length)
				{
					var sel = r.columns[r.id-1].getElementsByTagName("DD");
					if (sel[0] && sel[0].firstChild)
					{
						qm_oo(new Object(),sel[0].firstChild);
						return;
					}
			
				}
			}	
		
		}
		
		if (!qmv.addons.tree_menu["on"+qmv.id])
		{
				
			if (ish)
			{
			
				na = qmvi_kc_getnp(targ,"previous");
				if (na)
					qm_oo(new Object(),na);
				
			}
			else
			{
			
				var pi = qmv_kc_get_parent_item(targ[qp][qp]);
				if (pi)
					qm_oo(new Object(),pi);
				

			}	
		}
	

	}
	
	

}


function qmv_kc_get_parent_item(d)
{
	
	if (d.tagName=="DL" && d.className.indexOf("qmmulti")+1)
		d = d[qp][qp];
	
	var dc=d.childNodes;
	
	for(var i=0;i<dc.length;i++)
	{
		if(dc[i].cdiv&&dc[i].cdiv.style.visibility=="inherit")
			return dc[i];
	}
	return null;

}

function qmvi_kc_fnl(t)
{





	if (qmv.addons.tree_menu["on"+qmv.id])
	{
		if (t.cdiv.className.indexOf("qmfh")+1)
		{
			qm_oo(new Object(),t);	
			return;
		}

	}

	var ch = t.cdiv.childNodes;

	for (var i=0;i<ch.length;i++)
	{
		
		if ((ch[i].tagName=="A") || (ch[i].tagName=="DL" && ch[i].className.indexOf("qmmulti")+1) || (ch[i].tagName=="SPAN" && ch[i].className && (ch[i].className.indexOf("qmcbox")+1 ||  ch[i].className.indexOf("qmtitle")+1 || ch[i].className.indexOf("qmdivider")+1)))
		{	 
			if (ch[i].tagName=="DL")
			{
				var sd = ch[i].firstChild;
				if (sd && sd.tagName=="DD")
				{
					qm_oo(new Object(),sd.firstChild);
				}
			}
			else
				qm_oo(new Object(),ch[i]);
				
			return;

		}

	}

}


function qmvi_kc_getnp(na,type)
{

	
	
	var is_multi = false;
	if (na[qp] && na[qp].tagName=="DD" && na[qp][qp].className.indexOf("qmmulti")+1)
	{
		na = na[qp];
		is_multi = true;
	}
	
	
	while (((na = na[type+"Sibling"]) && na.tagName!="A" && na.tagName!="SPAN" && na.tagName!="DD") || (na && na.noselect))
		continue;
	
	if (!na || na.className.indexOf("qmclear")+1 || na.isselector || na.noselect)
		return;
	else
	{
		if (is_multi)
			return na.firstChild;
		else
			return na;
		
	}
}

