function qmv_delete_menu_ok(id,select_remaining)
{
	
	
	
	qmv_delete_pointer_objects("qm"+id);
		
	var cm = document.getElementById("qm"+id);
	if (cm)
	{

		
		if (qmv.addons.tree_menu["on"+id])
			qmv_update_tree_menu(true,null,true,true,id);

		if (qmv.addons.scroll["on"+id])
			qmv_update_scroll(true,null,true,true,id);
		
		if (qmv.addons.ibcss["on"+id])
			qmv_update_ibcss(true,null,true,true,id);
	

		var j;
		for (j in qmv.addons)
			qmv.addons[j]["on"+id] = null;
		

		qmad["qm"+id]=null;
	
		
		if (cm[qp].menufloater)
			cm[qp][qp].removeChild(cm[qp]);
		else
			cm[qp].removeChild(cm);
		
				
		
		var c=0;
		while (qmv["style_rules"+c])
		{
			

			var r = qmv["style_rules"+c];
			var sheet = qmv["style_rules_sheet"+c]
		
			for (var i=0;i<r.length;i++)
			{
				
				if (r[i].selectorText && (r[i].selectorText.indexOf("#qm"+id)+1 && r[i].selectorText.indexOf("qmcoreindicator")==-1))
				{
					
					if (qmv.styles_removetype == "removerule")
						sheet.removeRule(i);
					else
						sheet.deleteRule(i);
					
					i--;
					
				}
		
			}

			c++;

		}

		qmv["report"+id] = null;
			
		if (select_remaining)
		{

			for (var i=0;i<10;i++)
			{
				var a;
				if (a = document.getElementById("qm"+i))
				{
					qm_oo(new Object(),a.getElementsByTagName("A")[0]);	
					break;
				}

			}
		}

	}

}

