function qmvi_thumb_loader_creator(is_create)
{

	var ra_all = [];
	var ra_vertical = [];
	var ra_horizontal = [];
	var params = qmv.thumb_params;

	var tmch = document.getElementById("qmvt2").childNodes;
	for (var g=0;g<tmch.length;g++)
	{
		var section_div;
		if (section_div = tmch[g].cdiv)
		{
			var tpates_ch = section_div.childNodes;
			for (var h=0;h<tpates_ch.length;h++)
			{
				var ta = tpates_ch[h];
				if (ta.tagName=="A")
				{
				
					var ch = ta.cdiv.childNodes;
					for (var j=0;j<ch.length;j++)
					{
						var colorvar;
						if (colorvar = ch[j].getAttribute("qmtv"))
						{
							var typeid = colorvar.split("|")[0];
							var color = colorvar.split("|")[1];
							
							if (typeid==23) //skip scroller
								continue;
							
							var style="box";
							if (ta.getAttribute("is_radius"))
								style="radius";
							
							
							var title = "";
							if (is_create)
								title=qmvi_thumb_creator_get_template_title(ta);
							
							
							var an = "all_"+style+"_"+typeid+"_"+color;
							if (is_create)
								qmvi_thumb_creator_make_thumb(typeid,color,ch[j],an,params);
							
							
							ra_all.push({name:title,fname:an,color:color,tree_node:ch[j]});
							
							
							if (qmvi_thumb_creator_get_set_variation(ta.cdiv,"vertical"))
							{
								an = "vertical_"+style+"_"+typeid+"_"+color;
								if (is_create)
									qmvi_thumb_creator_make_thumb(typeid,color,ch[j],an,params);
									
								ra_vertical.push({name:title,fname:an,color:color,tree_node:ch[j]});
							}
							
							
							if (qmvi_thumb_creator_get_set_variation(ta.cdiv,"horizontal"))
							{
								an = "horizontal_"+style+"_"+typeid+"_"+color;
								if (is_create)
									qmvi_thumb_creator_make_thumb(typeid,color,ch[j],an,params);
									
								ra_horizontal.push({name:title,fname:an,color:color,tree_node:ch[j]});	
							}
							
							
						}
						
					}
					
				}
			}
		}
	}
	
	
	return {all:ra_all,vertical:ra_vertical,horizontal:ra_horizontal};
}


function qmvi_thumb_creator_get_template_title(a)
{
	
	var ch = a.childNodes;
	for (var i=0;i<ch.length;i++)
	{
	
		if (ch[i].nodeType==3 && ch[i].nodeValue)
		{
			var ischar = ch[i].nodeValue.match(/[0-9a-zA-Z]/g);
			if (ischar)
			{
				return ch[i].nodeValue;
			}
		}
	}

	return "";

}



function qmvi_thumb_creator_get_set_variation(root,type)
{

	var inps = root.getElementsByTagName("INPUT");
	for (var i=0;i<inps.length;i++)
	{
		var mt = inps[i][qp].getAttribute("qmmod");
		if (mt && inps[i].getAttribute("type").toLowerCase()=="radio" || inps[i].getAttribute("type").toLowerCase()=="checkbox")
		{
			if (type=="vertical" && mt.indexOf("create|isvertical|true")+1)
			{
				inps[i].checked = true;
				return inps[i];
			}
			if (type=="horizontal" && mt.indexOf("create|isvertical|false")+1)
			{
				inps[i].checked = true;
				return inps[i];
			}
			else if (type=="horizontal" && root.idiv.getAttribute("is_horizontal"))
				return true;

			else if (type=="vertical" && root.idiv.getAttribute("is_vertical"))
				return true;
			
			
		}
		
	}

}


function qmvi_thumb_creator_make_html_page(thumbs)
{
	
	var ih = '';
	
	//re-organize the main cats
	var thumbs = {Horizontal:thumbs.horizontal,Vertical:thumbs.vertical};
	
	for (var i in thumbs)
	{
		//if (i=="all")
			//continue;
		
		ih += '<h1 class="info_tbar">Visual NodeFire Drop Down Menus - '+i+' Templates</h1>';
		ih += '<p>The following templates are included in the visual interface in the same order as presented below (<a href="/download.asp">download</a>).</p>';
		ih += '<div class="nb_spacer" style="height:15px">&nbsp;</div>';
		ih += '<div>';
		
			var factor = 1;
			var imgn = [];
			for (var j in thumbs[i])
			{
				if (typeof thumbs[i][j]=="object")
					imgn.push({name:thumbs[i][j].name,tree_node:thumbs[i][j].tree_node,orig_category:thumbs[i][j].color,category:thumbs[i][j].color,fname:thumbs[i][j].fname,width:parseInt(qmv.thumb_params.width*factor),height:parseInt(qmv.thumb_params.height*factor)});
			}
			
			var cats = qmvi_image_selector_create_add_image_spaces_categorize2(imgn);
			for (var j=0;j<cats.length;j++)
			{
				
				//color variation title
				var ct = qmvi_thumbnail_creator_adjust_color_titles(cats[j].category);
				ih += '<div class="color_type">'+ct+'</div>';
				
				var imgn = cats[j].imgn;
				for (var k=0;k<imgn.length;k++)
				{
					
					ih += '<div class="thumbnail"><a rel="NF.lightBox={id:\'allt_'+ct+'_'+i+'\', width:900, height:660, params:nflbParams_simple(), styles:{backgroundColor:\'#fff\'}}" title="'+imgn[k].name+'" href="/tplatesite/'+imgn[k].fname+'.html">';
					ih += '<img src="/tplatethumbs/'+imgn[k].fname+'.png" width="'+imgn[k].width+'" height="'+imgn[k].height+'"></a></div>';
					
				
				}
			
				ih += '<div class="nb_spacer" style="height:20px;clear:both;">&nbsp;</div>';
			
			
			}
		
		ih += '</div>';
		ih += '<div style="clear:both;"></div>';

	}
	
	return ih;
	
}


function qmvi_thumb_creator_make_thumb(typeid,color,a,fname,params)
{

	var iframe = document.createElement("IFRAME");
	iframe.style.width="1000px";
	iframe.style.height="200px";
	iframe.style.position="absolute";
	iframe.style.visibility="hidden";
	
	document.body.appendChild(iframe);
	var cw = iframe.contentWindow;
	cw.fname = fname;
	cw.params = params;
	
	cw.iframe_id = "tqmv_"+fname;
	iframe.id = "tqmv_"+fname;
	
	cw.onload=function(event,wait)
	{
		qmvi_thumb_creator_handle_iframe_load(this.iframe_id,false);
	}

	var thumb_style = {};
	if ((typeid==27 && color=="darkbackground") || (typeid==26 && color=="darkbackground") || (typeid==28 && color=="darkbackground"))
		thumb_style.body="margin:5px;";
	else if (typeid==19 || typeid==2)
		thumb_style.body="margin:5px 0px 0px 10px;";
	else if (typeid==13)
		thumb_style.body="margin:10px;";


	var pcontent = qmvi_template_dialog_show_template(typeid,color,null,a,thumb_style);
	pcontent = pcontent.replace(/file:\/\/\/.*?(qmimages)/g,'../qmimages');
	parent.xqmv_save_thumb_doc(pcontent,cw.fname+".html");
	
	pcontent = qmvi_template_dialog_show_template(typeid,color,null,a,thumb_style,true);
	pcontent = pcontent.replace(/file:\/\/\/.*?(qmimages)/g,'../qmimages');
	parent.xqmv_save_thumb_doc(pcontent,cw.fname+".html","tplatesite");
	
	iframe.src="chrome://nodefire/content/tplatedocs/"+cw.fname+".html";

}


function qmvi_thumb_creator_handle_iframe_load(id,wait)
{
	var ifr = document.getElementById(id).contentWindow;
	
	if (!wait)
	{
		var gqm = ifr.document.getElementById("qm0");
		var cursor = ifr.document.getElementById("thumb_cursor");
		cursor.style.visibility = "visible";
		
		var fa = ifr.document.getElementsByTagName("A")[0];
		if (fa.cdiv)
		{
			
			var cursor_set = false;
			ifr.qm_oo(new Object(),fa,true);
			var ch = fa.cdiv.childNodes;
			for (var i=0;i<ch.length;i++)
			{
				if (ch[i].cdiv)
				{
					ifr.qm_oo(new Object(),ch[i],true);
					
					var wh = qmv_get_offset(ch[i]);
					cursor.style.top = (12+wh[1])+"px";
					cursor.style.left = (40+wh[0])+"px";
					cursor_set = true;
					
					break;
				}
							
			}
			
			if (!cursor_set)
			{
				var wh = qmv_get_offset(fa);
				cursor.style.top = (15+wh[1])+"px";
				cursor.style.left = (40+wh[0])+"px";
			}
				
		}
		
		//wait 20 seconds to make sure all animation are done running and everthing loaded - doesn't take that long
		//but it might when several 100 menus are created and animating in the background at once.
		setTimeout("qmvi_thumb_creator_handle_iframe_load('"+id+"',true)",20000);
		
	}
	else
	{
		var p = ifr.params;
		qmvi_create_screen_grab_image(ifr,ifr.fname+".png",p,true);
	}
}


function qmvi_create_screen_grab_image(cw,fname,p,is_tplate_thumb)
{
  	   
    var canvas = document.createElement("canvas");  
    canvas.style.width = p.width+"px";  
    canvas.style.height = p.height+"px";  
    canvas.width = p.width;  
    canvas.height = p.height;  
    
    var ctx = canvas.getContext("2d");  
    ctx.clearRect(p.x,p.y,p.width,p.height);  
    ctx.save();
    ctx.scale(1,1);
    ctx.drawWindow(cw,p.x,p.y,p.width,p.height,"rgb(255,255,255)");  
		
    ctx.restore();  
	parent.xqmv_save_canvas_to_png(canvas,fname,is_tplate_thumb)
	
}


